return ['domain'=>'brikpanel','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'es_ES','project-id-version'=>'BrikPanel','pot-creation-date'=>'2026-09-27T14:55:44+00:00','po-revision-date'=>'2026-09-27 14:39+0000','x-generator'=>'Claude (BrikPanel auto-translation)','messages'=>['BrikPanel: WooCommerce Admin Dashboard Theme'=>'BrikPanel: WooCommerce Admin Dashboard Theme','Beautiful and modern Shopify-style WooCommerce admin panel & dashboard, fully free, forever.'=>'Panel de administración y dashboard WooCommerce moderno y bonito al estilo Shopify, totalmente gratis, para siempre.','Brksoft'=>'Brksoft','https://brksoft.com/'=>'https://brksoft.com/','Home page'=>'Página de inicio','BrikPanel could not load all of its files.'=>'BrikPanel no ha podido cargar todos sus archivos.','Some plugin files are missing, most likely from an interrupted update or a security scan. BrikPanel is running in a limited mode. Please reinstall the plugin (deactivate, delete, then install the latest version again) to restore full functionality. Your settings and data are kept.'=>'Faltan algunos archivos del plugin, probablemente por una actualización interrumpida o un análisis de seguridad. BrikPanel funciona en modo limitado. Reinstala el plugin (desactívalo, bórralo y vuelve a instalar la última versión) para restaurar toda la funcionalidad. Tus ajustes y datos se conservan.','WooCommerce is not active on this site, so BrikPanel features are disabled here. Activate WooCommerce to enable BrikPanel.'=>'WooCommerce no está activo en este sitio, por lo que las funciones de BrikPanel están desactivadas aquí. Activa WooCommerce para habilitar BrikPanel.','%d hidden notice'=>'%d aviso oculto' . "\0" . '%d avisos ocultos','Other plugins and themes posted these notices. BrikPanel keeps them hidden, click to show.'=>'Otros plugins y temas publicaron estos avisos. BrikPanel los mantiene ocultos, haz clic para mostrarlos.','Settings'=>'Ajustes','Ad Platforms integration'=>'Integración de plataformas publicitarias','Pull daily ad spend from Google Ads and Meta Ads to calculate true ROAS and Net Profit on the dashboard. Turn it off below to hide the admin page and stop all background sync jobs. Your connections stay saved.'=>'Importa el gasto diario en publicidad de Google Ads y Meta Ads para calcular el ROAS real y el beneficio neto en el panel. Desactívalo abajo para ocultar la página de administración y detener todas las tareas de sincronización en segundo plano. Tus conexiones se mantienen guardadas.','Enable Ad Platforms integration'=>'Activar integración de plataformas publicitarias','When on, the Ad Platforms admin menu, daily sync, and dashboard ROAS / Net Profit cards are active. When off, the module is dormant: no menu item, no scheduled sync, no dashboard cards.'=>'Cuando está activado, el menú de plataformas publicitarias, la sincronización diaria y las tarjetas de ROAS / beneficio neto del dashboard están activas. Cuando está desactivado, el módulo permanece inactivo: sin elemento de menú, sin sincronización programada, sin tarjetas del dashboard.','Integrations'=>'Integraciones','ROAS'=>'ROAS','Pull today\'s spend from your connected ad platforms now, instead of waiting for the daily sync.'=>'Consulta ahora mismo el gasto de hoy en tus plataformas publicitarias conectadas, en lugar de esperar a la sincronización diaria.','Update ad spend'=>'Actualizar el gasto publicitario','Show ad cost per order'=>'Mostrar el coste publicitario por pedido','Ad cost per order'=>'Coste publicitario por pedido','compact KPI sub-label inside the ROAS card: ad spend divided by order countCost / order'=>'Coste / pedido','How Ad cost per order is calculated'=>'Cómo se calcula el coste publicitario por pedido','Ad spend for the selected period divided by the orders placed in it.'=>'Gasto publicitario del periodo seleccionado dividido entre los pedidos realizados en dicho periodo.','Orders placed by store administrators are not counted.'=>'Los pedidos realizados por los administradores de la tienda no se contabilizan.','Marketplace orders are not counted, because ad spend drives your own store.'=>'Los pedidos del marketplace no se tienen en cuenta, ya que el gasto publicitario se destina a tu propia tienda.','Google Ads'=>'Google Ads','Meta Ads'=>'Meta Ads','Your session expired. Reload the page and try again.'=>'Tu sesión ha caducado. Actualiza la página e inténtalo de nuevo.','Permission denied.'=>'Permiso denegado.','No ad platform is connected yet. Connect one to pull spend.'=>'Aún no hay ninguna plataforma publicitaria conectada. Conecta una para obtener los datos de gasto.','Ad spend was just updated. Try again in %d second.'=>'El gasto publicitario se acaba de actualizar. Vuelve a intentarlo en %d segundo.' . "\0" . 'El gasto publicitario se acaba de actualizar. Vuelve a intentarlo en %d segundos.','Ad spend updated, but %s could not be reached.'=>'Se ha actualizado el gasto publicitario, pero no se ha podido acceder a %s.','Ad spend updated.'=>'Gasto publicitario actualizado.','Revenue / Ad spend'=>'Ingresos / Gasto en publicidad','Ad currency differs from store'=>'La moneda de la publicidad difiere de la de la tienda','Updating…'=>'Actualizando…','Could not update ad spend. Please try again.'=>'No se ha podido actualizar el gasto publicitario. Inténtalo de nuevo.','Google Ads connection was revoked for security. Please reconnect.'=>'La conexión con Google Ads se revocó por seguridad. Vuelve a conectar.','Not connected to Google Ads.'=>'No conectado a Google Ads.','The BrikPanel proxy returned an unverifiable response and was rejected.'=>'El proxy de BrikPanel devolvió una respuesta no verificable y fue rechazada.','Request to Google Ads failed after retries.'=>'La solicitud a Google Ads falló tras los reintentos.','Meta ad account statusDisabled'=>'Desactivada','Meta ad account statusUnsettled'=>'Pendiente de pago','Meta ad account statusPending review'=>'Pendiente de revisión','Meta ad account statusPending closure'=>'Pendiente de cierre','Meta ad account statusIn grace period'=>'En periodo de gracia','Meta ad account statusClosed'=>'Cerrada','Meta ad account statusAny active'=>'Cualquiera activa','Meta ad account statusAny closed'=>'Cualquiera cerrada','Meta ad account statusInactive'=>'Inactiva','Meta Ads connection was revoked for security. Please reconnect.'=>'La conexión con Meta Ads se revocó por seguridad. Vuelve a conectar.','Your Meta authorisation is no longer valid, so the connection was dropped. Click Connect Meta Ads to authorise again. Your imported history is untouched.'=>'Tu autorización de Meta ya no es válida, por lo que se cerró la conexión. Haz clic en Conectar Meta Ads para autorizar de nuevo. Tu historial importado permanece intacto.','Not connected to Meta Ads.'=>'No conectado a Meta Ads.','Request to Meta Ads failed after retries.'=>'La solicitud a Meta Ads falló tras los reintentos.','Meta rejected the saved authorisation. Click Re-authorize to reconnect your Meta account.'=>'Meta rechazó la autorización guardada. Haz clic en Volver a autorizar para reconectar tu cuenta de Meta.','Your Meta connection is missing the ads_read permission. Click Re-authorize and make sure you leave the advertising permission enabled on the Meta consent screen.'=>'A tu conexión de Meta le falta el permiso ads_read. Haz clic en Volver a autorizar y asegúrate de dejar activado el permiso de publicidad en la pantalla de consentimiento de Meta.','Meta rejected the request for this ad account. Check that the ad account ID is correct and that your Meta user can view it.'=>'Meta rechazó la solicitud para esta cuenta publicitaria. Comprueba que el ID de la cuenta publicitaria es correcto y que tu usuario de Meta puede verla.','Meta is rate-limiting this connection right now. The next scheduled sync will pick up where this one stopped.'=>'Meta está limitando la frecuencia de esta conexión en este momento. La próxima sincronización programada continuará donde se detuvo esta.','Meta could not find that ad account. Check the ad account ID and try again.'=>'Meta no encontró esa cuenta publicitaria. Comprueba el ID de la cuenta publicitaria e inténtalo de nuevo.','Unknown platform.'=>'Plataforma desconocida.','This connection is not available yet, it is pending platform approval.'=>'Esta conexión aún no está disponible, está pendiente de la aprobación de la plataforma.','Could not reach the BrikPanel proxy. Please try again in a moment.'=>'No se pudo contactar con el proxy de BrikPanel. Inténtalo de nuevo en un momento.','Could not start OAuth: proxy returned an error.'=>'No se pudo iniciar OAuth: el proxy devolvió un error.','Disconnected.'=>'Desconectado.','OAuth session expired. Please try connecting again.'=>'La sesión OAuth ha caducado. Intenta conectar de nuevo.','Unknown platform in OAuth state.'=>'Plataforma desconocida en el estado OAuth.','OAuth callback was for a different user. Aborted.'=>'La devolución de llamada OAuth era para otro usuario. Cancelado.','Could not reach the BrikPanel proxy.'=>'No se pudo contactar con el proxy de BrikPanel.','OAuth redemption failed. Please try connecting again.'=>'Falló el canje OAuth. Intenta conectar de nuevo.','Could not save tokens. Please try again.'=>'No se pudieron guardar los tokens. Inténtalo de nuevo.','Google Ads connected.'=>'Google Ads conectado.','Meta Ads connected.'=>'Meta Ads conectado.','Connection cancelled: the permission request was declined on the platform’s consent screen. Nothing was saved. Click Connect to try again.'=>'Conexión cancelada: se rechazó la solicitud de permisos en la pantalla de consentimiento de la plataforma. No se guardó nada. Haz clic en Conectar para intentarlo de nuevo.','The platform needs you to complete the consent screen. Click Connect to try again.'=>'La plataforma necesita que completes la pantalla de consentimiento. Haz clic en Conectar para intentarlo de nuevo.','The advertising platform is temporarily unavailable. Please try connecting again in a few minutes.'=>'La plataforma publicitaria no está disponible temporalmente. Vuelve a intentar la conexión en unos minutos.','The connection did not complete. Nothing was saved. Please try again.'=>'La conexión no se completó. No se guardó nada. Inténtalo de nuevo.','The connection did not complete (%s). Nothing was saved. Please try again.'=>'La conexión no se completó (%s). No se guardó nada. Inténtalo de nuevo.','Meta connected, but the advertising permission (ads_read) was not granted, so no spend can be imported. Click Re-authorize and leave the advertising permission enabled.'=>'Meta se conectó, pero no se concedió el permiso de publicidad (ads_read), por lo que no se puede importar el gasto. Haz clic en Volver a autorizar y deja activado el permiso de publicidad.','Google Ads connected, but the Google Ads permission was not granted, so no spend can be imported. Click Connect again and leave the Google Ads permission ticked on Google’s permission screen.'=>'Google Ads está conectado, pero no se concedió el permiso de Google Ads, así que no se puede importar ningún gasto. Haz clic de nuevo en Conectar y deja marcado el permiso de Google Ads en la pantalla de permisos de Google.','Ad Platforms'=>'Plataformas publicitarias','Connecting…'=>'Conectando…','Disconnect this platform? Your synced spend data will be deleted.'=>'¿Desconectar esta plataforma? Los datos de gasto sincronizados se eliminarán.','Syncing…'=>'Sincronizando…','Sync queued. Refresh the page in a moment.'=>'Sincronización en cola. Actualiza la página en un momento.','Saved.'=>'Guardado.','Loading accounts…'=>'Cargando cuentas…','No ad accounts found for this connection.'=>'No se encontraron cuentas publicitarias para esta conexión.','Something went wrong. Please try again.'=>'Algo salió mal. Inténtalo de nuevo.','Nothing logged yet.'=>'Todavía no hay registros.','log entry severityNote'=>'Aviso','Error'=>'Error','History import stopped'=>'Importación del historial detenida','Only manager accounts were found. A manager account holds no spend of its own, so pick the ad account you actually advertise from: enter its ID below and put the manager ID in the Manager (MCC) field.'=>'Solo se encontraron cuentas de administrador. Una cuenta de administrador no tiene gasto propio, así que elige la cuenta publicitaria con la que realmente anuncias: introduce su ID abajo y pon el ID de administrador en el campo «ID de cuenta de administrador (MCC)».','This is a manager account. It usually holds no spend of its own, so the import may come back empty. If it does, use the ID of the ad account you advertise from instead.'=>'Esta es una cuenta de administrador. Normalmente no tiene gasto propio, por lo que la importación puede quedar vacía. Si ocurre, usa el ID de la cuenta publicitaria con la que anuncias.','Connected'=>'Conectado','Not connected'=>'No conectado','Enter an ad account ID first.'=>'Introduce primero un ID de cuenta publicitaria.','Manager'=>'Administrador','Loading history… %1$d of %2$d 90-day chunks done'=>'Cargando historial… %1$d de %2$d bloques de 90 días completados','Just now'=>'Ahora mismo','Loading imported data…'=>'Cargando datos importados…','No spend data imported yet. It appears here once the first sync or backfill completes.'=>'Aún no se ha importado ningún dato de gasto. Aparecerá aquí cuando se complete la primera sincronización o el llenado de datos.','Could not load imported data.'=>'No se pudieron cargar los datos importados.','Account %s'=>'Cuenta %s','%1$s to %2$s'=>'%1$s a %2$s','%s days with spend'=>'%s días con gasto','Total spend'=>'Gasto total','Impressions'=>'Impresiones','Clicks'=>'Clics','Avg CTR'=>'CTR medio','Avg CPC'=>'CPC medio','Avg CPM'=>'CPM medio','Month'=>'Mes','Spend'=>'Gasto','CTR'=>'CTR','CPC'=>'CPC','Days'=>'Días','All time'=>'Histórico','Connect this platform first.'=>'Conecta primero esta plataforma.','That does not look like a valid ad account ID.'=>'Eso no parece un ID de cuenta publicitaria válido.','Could not save the manager account ID. Please try again.'=>'No se pudo guardar el ID de la cuenta de administrador. Inténtalo de nuevo.','Synced %d day of spend data.'=>'%d día de datos de gasto sincronizado.' . "\0" . '%d días de datos de gasto sincronizados.','Ad spend daily sync'=>'Sincronización diaria de gasto publicitario','Pulls yesterday plus the last 7 days of spend from each connected ad platform.'=>'Importa el día de ayer más los últimos 7 días de gasto de cada plataforma publicitaria conectada.','Ad spend backfill chunk'=>'Bloque de relleno de gasto publicitario','One 90-day slice of the initial historical pull when an ad platform is first connected.'=>'Una porción de 90 días de la importación histórica inicial al conectar una plataforma publicitaria por primera vez.','The history import stopped because the connection to this platform was lost. Connect again to resume it.'=>'La importación del historial se detuvo porque se perdió la conexión con esta plataforma. Vuelve a conectar para reanudarla.','The history import stopped because the selected ad account changed. Pick the account again to restart it.'=>'La importación del historial se detuvo porque cambió la cuenta publicitaria seleccionada. Vuelve a elegir la cuenta para reiniciarla.','Not connected.'=>'No conectado.','Pending Google approval'=>'Pendiente de aprobación de Google','Google Ads needs to approve our API access before this connection can go live. It will be enabled automatically once approved. No action is needed from you.'=>'Google Ads necesita aprobar nuestro acceso a la API antes de que esta conexión pueda activarse. Se habilitará automáticamente una vez aprobada. No necesitas hacer nada.','Connect Google Ads'=>'Conectar Google Ads','Pending Meta approval'=>'Pendiente de aprobación de Meta','Meta needs to review our app before this connection can go live. It will be enabled automatically once approved. No action is needed from you.'=>'Meta necesita revisar nuestra aplicación antes de que esta conexión pueda activarse. Se habilitará automáticamente una vez aprobada. No necesitas hacer nada.','Connect Meta Ads'=>'Conectar Meta Ads','Coming soon'=>'Próximamente','Saved connection could not be read.'=>'No se pudo leer la conexión guardada.','Your credentials are still stored and have not been deleted, but this site cannot decrypt them. This usually follows a change to the site address, a move to a new server, or new security keys in wp-config.php. Connect again to store a fresh copy.'=>'Tus credenciales siguen guardadas y no se han eliminado, pero este sitio no puede descifrarlas. Suele ocurrir tras un cambio en la dirección del sitio, una migración a un servidor nuevo o nuevas claves de seguridad en wp-config.php. Vuelve a conectar para guardar una copia nueva.','Reconnect required'=>'Se requiere volver a conectar','The stored authorisation stopped working, so no new spend is being imported. Your existing history is untouched. Connect again to resume syncing.'=>'La autorización guardada dejó de funcionar, por lo que no se está importando gasto nuevo. Tu historial existente permanece intacto. Vuelve a conectar para reanudar la sincronización.','BrikPanel only reads your ad results: total daily spend, impressions and clicks. It never creates, edits or deletes anything in your account.'=>'BrikPanel solo lee los resultados de tus anuncios: gasto diario total, impresiones y clics. Nunca crea, edita ni elimina nada en tu cuenta.','BrikPanel will request read-only access (ads_read) to your Meta ad accounts. We only pull total daily spend, impressions and clicks.'=>'BrikPanel solicitará acceso de solo lectura (ads_read) a tus cuentas publicitarias de Meta. Solo importamos el gasto diario total, impresiones y clics.','Google’s permission screen still asks for broad access (“See, edit, create, and delete your Google Ads accounts and data”) because the Google Ads API has only one permission and offers no read-only option. If you want the permission itself narrowed, connect with a Google account that has Read-only access to the Ads account.'=>'La pantalla de permisos de Google sigue pidiendo un acceso amplio («Ver, editar, crear y eliminar tus cuentas y datos de Google Ads») porque la API de Google Ads tiene un único permiso y no ofrece una opción de solo lectura. Si quieres limitar el propio permiso, conecta con una cuenta de Google que tenga acceso de solo lectura a la cuenta de Ads.','Connected as'=>'Conectado como','(email not shared)'=>'(email no compartido)','One more step'=>'Un paso más','Load accounts'=>'Cargar cuentas','Save'=>'Guardar','Can’t find your account?'=>'¿No encuentras tu cuenta?','If your ad account is owned by a Business Manager it may not appear in the list above. Enter its ID manually. You can find it in Meta Ads Manager, shown next to the account name.'=>'Si tu cuenta publicitaria pertenece a un Business Manager, puede que no aparezca en la lista de arriba. Introduce su ID manualmente. Lo encontrarás en el Administrador de anuncios de Meta, junto al nombre de la cuenta.','Enter your Google Ads customer ID manually if it is not listed above. Digits only, no dashes. You can find it at the top-right of your Google Ads account.'=>'Introduce manualmente tu ID de cliente de Google Ads si no aparece arriba. Solo dígitos, sin guiones. Lo encontrarás arriba a la derecha en tu cuenta de Google Ads.','Manager (MCC) account ID (optional)'=>'ID de cuenta de administrador (MCC) (opcional)','Only fill in if you access the chosen account through a Google Ads manager. Digits only, no dashes.'=>'Rellena solo si accedes a la cuenta elegida a través de un administrador de Google Ads. Solo dígitos, sin guiones.','Last successful sync'=>'Última sincronización exitosa','ago'=>'hace','(last attempt failed, check the error log)'=>'(el último intento falló, revisa el registro de errores)','Sync now'=>'Sincronizar ahora','Re-authorize'=>'Volver a autorizar','Disconnect'=>'Desconectar','Connect Google Ads and Meta Ads so BrikPanel can show real ROAS and Net Profit on the dashboard.'=>'Conecta Google Ads y Meta Ads para que BrikPanel pueda mostrar el ROAS real y el beneficio neto en el dashboard.','Imported spend data'=>'Datos de gasto importados','Everything BrikPanel has pulled so far, broken down by month. This is the raw data behind the dashboard ROAS and Net Profit figures.'=>'Todo lo que BrikPanel ha importado hasta ahora, desglosado por mes. Estos son los datos brutos detrás de las cifras de ROAS y beneficio neto del panel.','Refresh'=>'Actualizar','How it works'=>'Cómo funciona','Connect each platform once. Tokens are stored encrypted on this server and are sent only over HTTPS to our brksoft.com helper, which fetches your ad spend from Google and Meta.'=>'Conecta cada plataforma una vez. Los tokens se guardan cifrados en este servidor y solo se envían por HTTPS a nuestro asistente de brksoft.com, que obtiene tu gasto publicitario de Google y Meta.','After that, the last 7 days are refreshed once per day to capture late corrections.'=>'Después, los últimos 7 días se actualizan una vez al día para capturar correcciones tardías.','Spend is stored in the ad account currency. The dashboard shows ad-currency totals next to your store revenue so you can compare them directly.'=>'El gasto se almacena en la moneda de la cuenta de publicidad. El panel muestra los totales en la moneda de la publicidad junto a los ingresos de tu tienda para que puedas compararlos directamente.','Recent activity'=>'Actividad reciente','Last 50 entries from the sync log, errors and routine notes alike. Token values are redacted before storage.'=>'Las últimas 50 entradas del registro de sincronización, tanto errores como avisos rutinarios. Los valores de los tokens se ocultan antes de guardarlos.','View log'=>'Ver registro','Clear log'=>'Limpiar registro','System default'=>'Predeterminado del sistema','Appearance'=>'Apariencia','Customize how the BrikPanel admin interface looks. Changes apply to dashboard, products, orders, coupons, segments, the top bar, sidebar, and the modern login page. The rest of WordPress admin is untouched.'=>'Personaliza el aspecto de la interfaz de administración de BrikPanel. Los cambios se aplican al dashboard, productos, pedidos, cupones, segmentos, la barra superior, la barra lateral y la página de inicio de sesión moderna. El resto de la administración de WordPress no se ve afectada.','Interface font'=>'Tipografía de la interfaz','Pick the typeface used across BrikPanel. "System default" stays on your operating system\'s native font (no external request). Other choices load a single Google Fonts stylesheet with display: swap.'=>'Elige la tipografía usada en BrikPanel. "Predeterminada del sistema" mantiene la fuente nativa de tu sistema operativo (sin solicitudes externas). Otras opciones cargan una sola hoja de estilos de Google Fonts con display: swap.','Accent color'=>'Color de acento','Primary color used for buttons, focus rings, toggles, and active highlights. The BrikPanel default is a near-black gray (#303030); pick anything you like.'=>'Color principal usado para botones, marcos de foco, conmutadores y destacados activos. El predeterminado de BrikPanel es un gris casi negro (#303030); elige el que prefieras.','Sidebar icon style'=>'Estilo de los iconos de la barra lateral','Choose how the sidebar menu icons look. "Solid" uses the original filled icons (matching Shopify\'s admin). "Line" uses a thinner outline set for a lighter look.'=>'Elige el aspecto de los iconos del menú lateral. "Sólido" usa los iconos rellenos originales (a juego con el panel de Shopify). "Línea" usa un conjunto de contornos más finos para un aspecto más ligero.','Solid (filled, original)'=>'Sólido (relleno, original)','Line (thin outline)'=>'Línea (contorno fino)','Custom brand logo'=>'Logotipo de marca personalizado','Replace the BrikPanel mark in the admin top bar and on the modern login page with your own logo. Pick an image from your media library, or paste an external image URL to load it from a CDN. The logo applies as soon as it is set; use Remove to go back to the default BrikPanel icon and your site name. When a URL is set it takes priority over the media library pick. PNG or SVG with a transparent background gives the cleanest result. Recommended size: 256×256 px or wider.'=>'Sustituye la marca de BrikPanel de la barra superior del panel y de la página de acceso moderna por tu propio logotipo. Elige una imagen de tu biblioteca de medios o pega la URL de una imagen externa para cargarla desde un CDN. El logotipo se aplica en cuanto se define; usa Quitar para volver al icono predeterminado de BrikPanel y al nombre de tu sitio. Cuando hay una URL definida, tiene prioridad sobre la imagen elegida en la biblioteca. Un PNG o SVG con fondo transparente da el resultado más limpio. Tamaño recomendado: 256×256 px o mayor.','Custom CSS'=>'CSS personalizado','Add your own CSS to fine-tune the BrikPanel interface: change button colors, backgrounds, spacing, and more. Your rules load last, so they override the built-in styles. Tip: prefix your selectors with a BrikPanel class (for example .brikpanel-dashboard, .brikpanel-topbar, .brikpanel-pe) so the changes stay inside BrikPanel and leave the rest of the admin untouched.'=>'Añade tu propio CSS para ajustar la interfaz de BrikPanel: cambia colores de botones, fondos, espaciados y más. Tus reglas se cargan al final, así que sustituyen a los estilos integrados. Consejo: empieza tus selectores con una clase de BrikPanel (por ejemplo .brikpanel-dashboard, .brikpanel-topbar, .brikpanel-pe) para que los cambios se queden dentro de BrikPanel y no afecten al resto del administrador.','No logo selected'=>'Ningún logotipo seleccionado','Replace logo'=>'Sustituir logotipo','Select logo'=>'Seleccionar logotipo','Remove'=>'Eliminar','Or load from an image URL (CDN)'=>'O carga desde la URL de una imagen (CDN)','Select brand logo'=>'Seleccionar logotipo de marca','Use this image'=>'Usar esta imagen','Store Health'=>'Salud de la tienda','BrikControl scans your store in the background and flags issues, like products missing images or bot traffic in your figures, from the topbar shield and its own Store Health page. Turn it off to hide all of that and stop the scheduled scans. Your latest results stay saved, so turning it back on restores them.'=>'BrikControl analiza tu tienda en segundo plano y señala problemas, como productos sin imágenes o tráfico de bots en tus cifras, desde el escudo de la barra superior y su propia página Salud de la tienda. Desactívalo para ocultar todo eso y detener los análisis programados. Tus últimos resultados se conservan, así que al reactivarlo vuelven a aparecer.','Enable Store Health (BrikControl)'=>'Activar Salud de la tienda (BrikControl)','When on, the Store Health page, topbar shield and daily background scans are active. When off, the entire module is dormant: no menu item, no topbar icon, and no scheduled scans.'=>'Cuando está activado, la página Salud de la tienda, el escudo de la barra superior y los análisis diarios en segundo plano están activos. Cuando está desactivado, todo el módulo queda inactivo: sin elemento de menú, sin icono en la barra superior y sin análisis programados.','Clean up'=>'Limpiar','%s item cleaned up.'=>'%s elemento limpiado.' . "\0" . '%s elementos limpiados.','%s row restored.'=>'%s fila restaurada.' . "\0" . '%s filas restauradas.','Bot traffic'=>'Tráfico de bots','Clean up bot traffic'=>'Limpiar tráfico de bots','Put the previous figures and deleted entries back? This restores %s row exactly as it was before the cleanup.'=>'¿Recuperar las cifras anteriores y las entradas eliminadas? Se restaurará %s fila exactamente como estaba antes de la limpieza.' . "\0" . '¿Recuperar las cifras anteriores y las entradas eliminadas? Se restaurarán %s filas exactamente como estaban antes de la limpieza.','No analytics history has been recorded yet.'=>'Todavía no se ha registrado ningún historial de analíticas.','%s daily figure'=>'%s cifra diaria' . "\0" . '%s cifras diarias','%s abandoned-cart entry'=>'%s entrada de carrito abandonado' . "\0" . '%s entradas de carritos abandonados','Looks like bot traffic: %s'=>'Parece tráfico de bots: %s','No bot traffic found in the last %s day.'=>'No se encontró tráfico de bots en el último %s día.' . "\0" . 'No se encontró tráfico de bots en los últimos %s días.','%s daily figure counted more add-to-carts than the store had visitors that day, which cannot be real.'=>'%s cifra diaria registró más añadidos al carrito que visitantes tuvo la tienda ese día, algo que no puede ser real.' . "\0" . '%s cifras diarias registraron más añadidos al carrito que visitantes tuvo la tienda ese día, algo que no puede ser real.','%1$s daily figure sits at least %2$s times above its own normal and counted at least %3$s events. Automated traffic leaves this shape behind, though a real promotion can look like it too.'=>'%1$s cifra diaria está al menos %2$s veces por encima de su propio valor normal y registró al menos %3$s eventos. Es la huella que deja el tráfico automatizado, aunque una promoción real también puede parecerse.' . "\0" . '%1$s cifras diarias están al menos %2$s veces por encima de su propio valor normal y registraron al menos %3$s eventos. Es la huella que deja el tráfico automatizado, aunque una promoción real también puede parecerse.','%1$s abandoned-cart entry was almost certainly written by a script (the "%2$s" check explains why).'=>'%1$s entrada de carrito abandonado casi seguro la escribió un script (la comprobación "%2$s" explica por qué).' . "\0" . '%1$s entradas de carritos abandonados casi seguro las escribió un script (la comprobación "%2$s" explica por qué).','%s abandoned-cart entry was almost certainly written by a script.'=>'%s entrada de carrito abandonado casi seguro la escribió un script.' . "\0" . '%s entradas de carritos abandonados casi seguro las escribió un script.','The cleanup lowers each flagged figure to the highest value it could honestly have had, scales that day\'s traffic sources and device counts to match, deletes the flagged entries, and keeps everything it changed so one click puts it back.'=>'La limpieza baja cada cifra marcada al valor más alto que podía tener honestamente, ajusta en proporción las fuentes de tráfico y los recuentos de dispositivos de ese día, elimina las entradas marcadas y guarda todo lo que cambió para que un clic lo devuelva.','No day counted more add-to-carts than the store had visitors, no figure stands far above its own normal, and no abandoned-cart entry looks scripted.'=>'Ningún día contó más añadidos al carrito que visitantes, ninguna cifra está muy por encima de lo normal y ninguna entrada de carrito abandonado parece de un script.','More products or pages are affected than one pass covers; these are the worst %s. Run the check again after cleaning them to see the rest.'=>'Hay más productos o páginas afectados de los que cubre una pasada; estos son los %s peores. Vuelve a ejecutar la comprobación tras limpiarlos para ver el resto.','Open the list below first. The cleanup rewrites your own analytics history, and a real campaign day can look like a robot day. You can undo it afterwards.'=>'Abre primero la lista de abajo. La limpieza reescribe tu propio historial de analíticas y un día de campaña real puede parecer un día de robots. Después puedes deshacerla.','Last %s day checked'=>'Último %s día revisado' . "\0" . 'Últimos %s días revisados','Impossible days'=>'Días imposibles','Extreme days'=>'Días extremos','Scripted cart entries'=>'Entradas de carrito de scripts','Events to be removed'=>'Eventos que se eliminarán','What would change'=>'Qué cambiaría','Date'=>'Fecha','What'=>'Qué','Recorded'=>'Registrado','Corrected to'=>'Corregido a','Why'=>'Por qué','Clean up bot traffic?'=>'¿Limpiar el tráfico de bots?','%s daily figure is lowered.'=>'Se reducirá %s cifra diaria.' . "\0" . 'Se reducirán %s cifras diarias.','That removes about %s recorded event.'=>'Eso elimina unos %s evento registrado.' . "\0" . 'Eso elimina unos %s eventos registrados.','%s abandoned-cart entry is deleted.'=>'Se eliminará %s entrada de carrito abandonado.' . "\0" . 'Se eliminarán %s entradas de carritos abandonados.','Your products, orders and customers are not touched. Everything changed is kept in a restore point so you can undo it at any time.'=>'Tus productos, pedidos y clientes no se tocan. Todo lo que cambia se guarda en un punto de restauración para que puedas deshacerlo en cualquier momento.','%s daily figure lowered'=>'%s cifra diaria reducida' . "\0" . '%s cifras diarias reducidas','%s abandoned-cart entry deleted'=>'%s entrada de carrito abandonado eliminada' . "\0" . '%s entradas de carritos abandonados eliminadas','Nothing needed cleaning up.'=>'No había nada que limpiar.','Done: %s.'=>'Hecho: %s.','Page #%s'=>'Página #%s','Product #%s'=>'Producto #%s','Store visitors'=>'Visitantes de la tienda','Product views'=>'Visualizaciones de producto','Store add-to-carts'=>'Añadidos al carrito de la tienda','Checkout visits'=>'Visitas al pago','Abandoned-cart entries written by scripts'=>'Entradas de carritos abandonados escritas por scripts','Deleted'=>'Eliminado','Certain, by the "%s" check'=>'Seguro, según la comprobación "%s"','Certain'=>'Seguro','Add-to-carts: %s'=>'Añadidos al carrito: %s','Page views: %s'=>'Páginas vistas: %s','More adds than visitors'=>'Más añadidos que visitantes','More adds than store visitors'=>'Más añadidos que visitantes de la tienda','Far above its own normal'=>'Muy por encima de su valor normal','An undo is running for this check. Try again in a moment.'=>'Se está deshaciendo una acción de esta comprobación. Vuelve a intentarlo en un momento.','The restore point could not be written, so nothing more was changed.'=>'No se pudo escribir el punto de restauración, así que no se cambió nada más.','The restore point is full. Undo the last cleanup or leave it in place, then run the check again.'=>'El punto de restauración está lleno. Deshaz la última limpieza o déjala como está y vuelve a ejecutar la comprobación.','A cleanup is running for this check. Try again in a moment.'=>'Se está ejecutando una limpieza de esta comprobación. Vuelve a intentarlo en un momento.','There is nothing to undo.'=>'No hay nada que deshacer.','Abandoned cart entries'=>'Registros de carritos abandonados','The abandoned-carts table could not be found.'=>'No se encontró la tabla de carritos abandonados.','BrikPanel creates it when the plugin is activated. Deactivate and reactivate BrikPanel, then run this check again.'=>'BrikPanel la crea al activar el plugin. Desactiva y vuelve a activar BrikPanel y luego ejecuta de nuevo esta comprobación.','The abandoned-cart entries could not be read.'=>'No se pudieron leer las entradas de carritos abandonados.','The database refused one of the scan queries: %s'=>'La base de datos rechazó una de las consultas del escaneo: %s','No abandoned-cart entries to check yet.'=>'Todavía no hay entradas de carritos abandonados que revisar.','Entries appear here once a shopper types an email at checkout or in the signup popup.'=>'Las entradas aparecen aquí cuando un cliente escribe un correo electrónico en el pago o en la ventana emergente de registro.','%s entry was almost certainly written by a script, not a shopper'=>'%s entrada casi seguro la escribió un script, no un cliente' . "\0" . '%s entradas casi seguro las escribió un script, no un cliente','These entries carry a browser id this plugin never issued, or arrive in shapes a browser cannot produce: one browser id typing many different addresses within minutes, one address arriving from many browser ids within minutes, or dozens of empty signups inside a single minute.'=>'Estas entradas llevan un ID de navegador que este plugin nunca emitió o llegan de formas que un navegador no puede producir: un ID de navegador que escribe muchas direcciones distintas en pocos minutos, una dirección que llega desde muchos ID de navegador en pocos minutos o decenas de registros vacíos en un solo minuto.','This check only reports; the "%s" check on this page deletes the certain ones, with a restore point.'=>'Esta comprobación solo informa; la comprobación "%s" de esta página elimina las seguras, con un punto de restauración.','This check only reports and changes nothing.'=>'Esta comprobación solo informa y no cambia nada.','The capture endpoint now refuses foreign browser ids and rate-limits by connection, so new entries of this kind should stop.'=>'El punto de captura ahora rechaza los ID de navegador ajenos y limita la frecuencia por conexión, así que las nuevas entradas de este tipo deberían parar.','%s further entry repeats in a way that is suspicious but not conclusive.'=>'%s entrada más se repite de una forma sospechosa pero no concluyente.' . "\0" . '%s entradas más se repiten de formas sospechosas pero no concluyentes.','%s entry repeats in a way a script would produce'=>'%s entrada se repite como lo haría un script' . "\0" . '%s entradas se repiten como lo haría un script','One browser id with several addresses, one address across several browser ids, or a burst of empty signups. A shared computer, a shopper on several devices or a busy promotion can look exactly the same, so open the list below and check before deleting anything. Nothing has been changed by this check.'=>'Un ID de navegador con varias direcciones, una dirección en varios ID de navegador o una ráfaga de registros vacíos. Un ordenador compartido, un cliente con varios dispositivos o una promoción con mucho movimiento pueden verse igual, así que abre la lista de abajo y revisa antes de eliminar nada. Esta comprobación no ha cambiado nada.','Your abandoned-cart entries look like real shoppers.'=>'Tus entradas de carritos abandonados parecen de clientes reales.','Every browser id has the shape this plugin issues, no browser id juggles many addresses, no address is spread across many browser ids, and no minute holds a burst of empty signups.'=>'Cada ID de navegador tiene la forma que emite este plugin, ningún ID de navegador maneja muchas direcciones, ninguna dirección se reparte entre muchos ID de navegador y ningún minuto tiene una ráfaga de registros vacíos.','More groups matched than one pass counts; only the %s largest groups per pattern are included, so these figures are lower bounds.'=>'Coincidieron más grupos de los que cuenta una pasada; solo se incluyen los %s grupos más grandes por patrón, así que estas cifras son mínimos.','Certain groups'=>'Grupos seguros','Likely groups'=>'Grupos probables','Entries involved (at least)'=>'Entradas implicadas (como mínimo)','Entries involved'=>'Entradas implicadas','Entries checked'=>'Entradas revisadas','Coupons for flagged emails'=>'Cupones de correos marcados','Coupons with no cart entry'=>'Cupones sin entrada de carrito','Entries that look automated'=>'Entradas que parecen automatizadas','Pattern'=>'Patrón','Certainty'=>'Certeza','Identifier'=>'Identificador','Entries'=>'Entradas','Example email'=>'Correo de ejemplo','First seen'=>'Visto por primera vez','One browser id, %1$s address in %2$s'=>'Un ID de navegador, %1$s dirección en %2$s' . "\0" . 'Un ID de navegador, %1$s direcciones en %2$s','One address, %1$s browser id in %2$s'=>'Una dirección, %1$s ID de navegador en %2$s' . "\0" . 'Una dirección, %1$s ID de navegador en %2$s','%s empty popup signup in one minute'=>'%s registro vacío en la ventana emergente en un minuto' . "\0" . '%s registros vacíos en la ventana emergente en un minuto','%s empty checkout signup in one minute'=>'%s registro vacío en el pago en un minuto' . "\0" . '%s registros vacíos en el pago en un minuto','Browser id not issued by this plugin'=>'ID de navegador no emitido por este plugin','Likely'=>'Probable','under a minute'=>'menos de un minuto','Open Abandoned Carts and search for the example addresses below. This check changed nothing. "%s" on this page removes the certain entries; delete a likely one by hand only once you are sure it is not a shopper.'=>'Abre Carritos abandonados y busca las direcciones de ejemplo de abajo. Esta comprobación no ha cambiado nada. "%s" en esta página elimina las entradas seguras; elimina una probable a mano solo cuando estés seguro de que no es un cliente.','Open Abandoned Carts and search for the example addresses below. This check changed nothing; delete an entry by hand only once you are sure it is not a shopper.'=>'Abre Carritos abandonados y busca las direcciones de ejemplo de abajo. Esta comprobación no ha cambiado nada; elimina una entrada a mano solo cuando estés seguro de que no es un cliente.','Open Abandoned Carts'=>'Abrir Carritos abandonados','Popup signups among these entries were handed real coupons (codes starting with BRIK-). Each is single-use and locked to the address it was issued to, so nobody else can redeem it; review them in your coupon list if you want them gone.'=>'Algunos registros de la ventana emergente entre estas entradas recibieron cupones reales (códigos que empiezan por BRIK-). Cada uno es de un solo uso y está vinculado a la dirección para la que se emitió, así que nadie más puede canjearlo; revísalos en tu lista de cupones si quieres quitarlos.','Open coupons'=>'Abrir cupones','Product cost records'=>'Registros de coste de productos','Remove extra copies'=>'Eliminar copias sobrantes','Every product cost is saved once.'=>'El coste de cada producto está guardado una sola vez.','No product or variation has a copy of its cost stored more than once.'=>'Ningún producto ni variación tiene su coste guardado más de una vez.','%s product has its cost saved more than once'=>'%s producto tiene su coste guardado más de una vez' . "\0" . '%s productos tienen su coste guardado más de una vez','Your reports already count each cost once, so your profit figures are correct. The extra copies can still confuse exports and other plugins. Removing them keeps the copy your product pages show today, so no cost changes.'=>'Tus informes ya cuentan cada coste una sola vez, así que tus cifras de beneficio son correctas. Aun así, las copias sobrantes pueden confundir a las exportaciones y a otros plugins. Al eliminarlas se conserva la copia que muestran hoy tus páginas de producto, así que ningún coste cambia.','%s of these holds different numbers in its copies; the first saved number is the one in use and the one that stays.'=>'%s de ellos tiene números distintos en sus copias; el primer número guardado es el que se usa y el que se conserva.' . "\0" . '%s de ellos tienen números distintos en sus copias; el primer número guardado es el que se usa y el que se conserva.','Open the list below to see which products are affected. Products are often copied this way by an import or by duplicating a product.'=>'Abre la lista de abajo para ver qué productos están afectados. Los productos suelen copiarse así al importar o al duplicar un producto.','Remove %s extra cost copy? The cost each product shows today does not change, and the removed copy is kept so you can undo this.'=>'¿Eliminar %s copia sobrante del coste? El coste que muestra hoy cada producto no cambia, y la copia eliminada se guarda para que puedas deshacerlo.' . "\0" . '¿Eliminar %s copias sobrantes del coste? El coste que muestra hoy cada producto no cambia, y las copias eliminadas se guardan para que puedas deshacerlo.','Put the removed cost copies back? This restores %s row exactly as it was.'=>'¿Recuperar las copias del coste eliminadas? Se restaurará %s fila exactamente como estaba.' . "\0" . '¿Recuperar las copias del coste eliminadas? Se restaurarán %s filas exactamente como estaban.','Products affected'=>'Productos afectados','Extra copies'=>'Copias sobrantes','Copies with different numbers'=>'Copias con números distintos','Affected products'=>'Productos afectados','Product'=>'Producto','Field'=>'Campo','Copies'=>'Copias','Saved numbers (first one stays)'=>'Números guardados (se conserva el primero)','%s extra cost copy removed.'=>'%s copia sobrante del coste eliminada.' . "\0" . '%s copias sobrantes del coste eliminadas.','%s cost copy put back.'=>'%s copia del coste recuperada.' . "\0" . '%s copias del coste recuperadas.','(empty)'=>'(vacío)','Cost of goods (WooCommerce)'=>'Coste de mercancía (WooCommerce)','Cost of goods (BrikPanel)'=>'Coste de mercancía (BrikPanel)','Adds to parent cost'=>'Se suma al coste del producto principal','Cost of goods (%s)'=>'Coste de mercancía (%s)','The restore point is full. Undo the last correction or leave it in place, then run the check again.'=>'El punto de restauración está lleno. Deshaz la última corrección o déjala como está y vuelve a ejecutar la comprobación.','%s copy was not put back because that cost was changed or cleared after the cleanup.'=>'%s copia no se restauró porque ese coste se cambió o se borró después de la limpieza.' . "\0" . '%s copias no se restauraron porque esos costes se cambiaron o se borraron después de la limpieza.','Product image health'=>'Salud de imágenes de productos','Scanning… %1$s / %2$s product'=>'Escaneando… %1$s / %2$s producto' . "\0" . 'Escaneando… %1$s / %2$s productos','No products to check yet.'=>'Todavía no hay productos que revisar.','No product images to check yet.'=>'Todavía no hay imágenes de productos que revisar.','%1$s oversized (%2$s of %3$s) · %4$s modern format'=>'%1$s demasiado grandes (%2$s de %3$s) · %4$s en formato moderno','Install %s'=>'Instalar %s','%1$s product image (%2$s) is larger than 1 MB. It slows down your product pages and hurts SEO. Compress it to under 200 KB where possible.'=>'%1$s imagen de producto (%2$s) pesa más de 1 MB. Ralentiza tus páginas de producto y perjudica el SEO. Comprímela por debajo de 200 KB cuando sea posible.' . "\0" . '%1$s imágenes de productos (%2$s) pesan más de 1 MB. Ralentizan tus páginas de producto y perjudican el SEO. Comprímelas por debajo de 200 KB cuando sea posible.','%s product image points to a file that no longer exists on disk. Upload it again or remove it from the product.'=>'%s imagen de producto apunta a un archivo que ya no existe en el servidor. Súbela de nuevo o quítala del producto.' . "\0" . '%s imágenes de productos apuntan a archivos que ya no existen en el servidor. Súbelas de nuevo o quítalas de sus productos.','Your product images are well optimised. Keep an eye on this metric as you upload new products.'=>'Tus imágenes de productos están bien optimizadas. Vigila esta métrica cuando subas productos nuevos.','Total images'=>'Imágenes totales','Over 1 MB'=>'Más de 1 MB','WebP / AVIF'=>'WebP / AVIF','JPEG / PNG'=>'JPEG / PNG','Missing files'=>'Archivos faltantes','Product SKU index'=>'Índice de SKU de productos','Clean up index'=>'Limpiar índice','WooCommerce product tables were not found.'=>'No se encontraron las tablas de productos de WooCommerce.','%s SKU is reserved by a product that no longer exists'=>'%s SKU está reservado por un producto que ya no existe' . "\0" . '%s SKU están reservados por productos que ya no existen','WooCommerce keeps a fast SKU index alongside your products. %s entry in it points at a product that was deleted. The WordPress admin will tell you that SKU is free, but the REST API refuses to create a product with it, so ERP, import and sync integrations fail with "already present in the lookup table".'=>'WooCommerce mantiene un índice rápido de SKU junto a tus productos. %s entrada de ese índice apunta a un producto que se eliminó. El administrador de WordPress te dirá que ese SKU está libre, pero la API REST se niega a crear un producto con él, así que las integraciones de ERP, importación y sincronización fallan con "already present in the lookup table".' . "\0" . 'WooCommerce mantiene un índice rápido de SKU junto a tus productos. %s entradas de ese índice apuntan a productos que se eliminaron. El administrador de WordPress te dirá que esos SKU están libres, pero la API REST se niega a crear productos con ellos, así que las integraciones de ERP, importación y sincronización fallan con "already present in the lookup table".','%s leftover index row from deleted products'=>'%s fila de índice sobrante de productos eliminados' . "\0" . '%s filas de índice sobrantes de productos eliminados','None of them hold a SKU, so nothing is blocked today, but the index has drifted far enough from your catalogue that a delete path is leaking rows.'=>'Ninguna guarda un SKU, así que hoy no hay nada bloqueado, pero el índice se ha alejado tanto de tu catálogo que alguna forma de borrar está dejando filas atrás.','%s leftover index row, harmless'=>'%s fila de índice sobrante, inofensiva' . "\0" . '%s filas de índice sobrantes, inofensivas','This row carries no SKU, so it blocks nothing and slows nothing down. You can clear it whenever you like.'=>'Esta fila no guarda ningún SKU, así que no bloquea ni ralentiza nada. Puedes borrarla cuando quieras.' . "\0" . 'Estas filas no guardan ningún SKU, así que no bloquean ni ralentizan nada. Puedes borrarlas cuando quieras.','Every index entry matches a real product.'=>'Cada entrada del índice corresponde a un producto real.','Remove %s leftover index row? Products in your catalogue are not affected.'=>'¿Eliminar %s fila de índice sobrante? Los productos de tu catálogo no se ven afectados.' . "\0" . '¿Eliminar %s filas de índice sobrantes? Los productos de tu catálogo no se ven afectados.','Leftover index rows'=>'Filas de índice sobrantes','Blocked SKUs'=>'SKU bloqueados','Leftover attribute rows'=>'Filas de atributos sobrantes','Indexed products'=>'Productos indexados','Product ID'=>'ID del producto','SKU'=>'SKU','%s leftover index row removed.'=>'%s fila de índice sobrante eliminada.' . "\0" . '%s filas de índice sobrantes eliminadas.','Use "%s" to remove them. Nothing in your catalogue is touched: only rows whose product no longer exists are deleted.'=>'Usa "%s" para eliminarlas. No se toca nada de tu catálogo: solo se borran las filas cuyo producto ya no existe.','After cleaning up, ask your integration to send the affected products again. The SKUs will be accepted.'=>'Después de limpiar, pide a tu integración que vuelva a enviar los productos afectados. Los SKU se aceptarán.','A product sitting in the trash also keeps its SKU reserved. Empty the trash before reusing a SKU.'=>'Un producto que está en la papelera también mantiene su SKU reservado. Vacía la papelera antes de reutilizar un SKU.','Rows keep piling up when products are removed by direct database queries. If you use a bulk-delete or cleanup plugin, prefer its standard mode over any "fast" or "direct SQL" option.'=>'Las filas se acumulan cuando los productos se eliminan con consultas directas a la base de datos. Si usas un plugin de borrado masivo o de limpieza, prefiere su modo estándar a cualquier opción "rápida" o de "SQL directo".','BrikControl: Full Health Scan'=>'BrikControl: escaneo de salud completo','Runs every BrikControl check and writes results to the dashboard.'=>'Ejecuta todas las comprobaciones de BrikControl y escribe los resultados en el dashboard.','BrikControl: Scan Batch'=>'BrikControl: lote de escaneo','Processes a single batch of a long-running BrikControl check.'=>'Procesa un único lote de una comprobación larga de BrikControl.','Scan queued. Refreshing…'=>'Escaneo en cola. Actualizando…','Could not start scan.'=>'No se pudo iniciar el escaneo.','Cleaning up…'=>'Limpiando…','Cleanup failed. Please try again.'=>'La limpieza falló. Inténtalo de nuevo.','Restoring…'=>'Restaurando…','Could not restore. Please try again.'=>'No se pudo restaurar. Inténtalo de nuevo.','All checks passing'=>'Todas las comprobaciones superadas','Not scanned yet'=>'Aún sin escanear','Scanning…'=>'Escaneando…','You do not have permission to access this page.'=>'No tienes permiso para acceder a esta página.','Not scanned yet. Run a scan to see results.'=>'Todavía no escaneado. Ejecuta un escaneo para ver resultados.','%s critical store health issue'=>'%s problema crítico de salud de la tienda' . "\0" . '%s problemas críticos de salud de la tienda','%s store health warning'=>'%s aviso de salud de la tienda' . "\0" . '%s avisos de salud de la tienda','Store health: all checks passing'=>'Salud de la tienda: todas las comprobaciones superadas','Rescan now'=>'Volver a escanear ahora','Open full report'=>'Abrir informe completo','Run a scan to see store health checks.'=>'Ejecuta un escaneo para ver las comprobaciones de salud de la tienda.','A scan is already running.'=>'Ya hay un escaneo en marcha.','Action Scheduler is unavailable.'=>'Action Scheduler no está disponible.','A scan is already in the queue.'=>'Ya hay un escaneo en la cola.','Scan queued.'=>'Escaneo en cola.','Missing dismiss target.'=>'Falta el destino del descarte.','Missing check id.'=>'Falta el ID de la comprobación.','This check has no automatic fix.'=>'Esta comprobación no tiene corrección automática.','A cleanup is already running for this check.'=>'Ya hay una limpieza en marcha para esta comprobación.','The cleanup could not be completed.'=>'No se pudo completar la limpieza.','More rows remain. Run the cleanup again.'=>'Quedan más filas. Vuelve a ejecutar la limpieza.','This check has nothing to undo.'=>'Esta comprobación no tiene nada que deshacer.','An undo is already running for this check.'=>'Ya se está deshaciendo algo en esta comprobación.','The undo could not be completed.'=>'No se pudo completar la acción de deshacer.','Scanning your store…'=>'Escaneando tu tienda…','If a known crawler is behind it, add it to "%1$s" or "%2$s" in the analytics settings, so it stops being counted at all.'=>'Si detrás hay un rastreador conocido, añádelo a "%1$s" o "%2$s" en los ajustes de analíticas para que deje de contarse por completo.','Excluded user agents'=>'Agentes de usuario excluidos','Excluded IP addresses'=>'Direcciones IP excluidas','Analytics settings'=>'Ajustes de analíticas','Invalid nonce.'=>'Nonce no válido.','just now'=>'ahora mismo','%s min ago'=>'hace %s min' . "\0" . 'hace %s min','%s h ago'=>'hace %s h' . "\0" . 'hace %s h','%s d ago'=>'hace %s d' . "\0" . 'hace %s d','Last scan: %s'=>'Último escaneo: %s','No scan completed yet.'=>'Aún no se ha completado ningún escaneo.','Scan now'=>'Escanear ahora','Critical'=>'Crítico','Warnings'=>'Avisos','OK'=>'OK','Pending'=>'Pendiente','No checks registered yet. Once the first scan finishes, you will see results here.'=>'Aún no hay comprobaciones registradas. Cuando termine el primer escaneo, verás los resultados aquí.','Warning'=>'Aviso','Health score'=>'Puntuación de salud','Active optimizer plugins:'=>'Plugins optimizadores activos:','Open'=>'Abrir','Clean up %s item?'=>'¿Limpiar %s elemento?' . "\0" . '¿Limpiar %s elementos?','Put the previous values back? This restores %s row exactly as it was before the last correction.'=>'¿Recuperar los valores anteriores? Se restaurará %s fila exactamente como estaba antes de la última corrección.' . "\0" . '¿Recuperar los valores anteriores? Se restaurarán %s filas exactamente como estaban antes de la última corrección.','Corrected %s'=>'Corregido el %s','Undo last correction'=>'Deshacer la última corrección','Details'=>'Detalles','Largest images (top 10)'=>'Imágenes más grandes (top 10)','Image'=>'Imagen','Size'=>'Tamaño','Format'=>'Formato','Action'=>'Acción','(no title)'=>'(sin título)','%s MB'=>'%s MB','Scanned %s'=>'Escaneado %s','Orders'=>'Pedidos','Products'=>'Productos','Analytics'=>'Analíticas','Subscribe to get special offers and updates.'=>'Suscríbete para recibir ofertas especiales y novedades.','Sign up and get %d%% off'=>'Suscríbete y consigue un %d %% de descuento','Get %d%% off'=>'Consigue un %d %% de descuento','Sign up and save'=>'Suscríbete y ahorra','Special offer'=>'Oferta especial','Subscribe'=>'Suscribirse','Enter your email'=>'Introduce tu correo electrónico','Thanks for subscribing!'=>'¡Gracias por suscribirte!','Please enter a valid email address.'=>'Introduce una dirección de correo electrónico válida.','Close'=>'Cerrar','Email address'=>'Dirección de correo electrónico','Your discount code'=>'Tu código de descuento','Apply it at checkout. Valid for 30 days.'=>'Aplícalo al finalizar la compra. Válido durante 30 días.','Already on your cart, the discount is in your total.'=>'Ya está en tu carrito, el descuento está en tu total.','Saved. It goes on your cart automatically, and you can still type it in at checkout.'=>'Guardado. Se aplica a tu carrito automáticamente y aun así puedes escribirlo al pagar.','Your code is saved. Reopen it any time from the tab at the bottom of the page.'=>'Tu código está guardado. Vuelve a abrirlo cuando quieras desde la pestaña de la parte inferior de la página.','Your code'=>'Tu código','Show your discount code'=>'Mostrar tu código de descuento','We sent your discount code to %s'=>'Hemos enviado tu código de descuento a %s','Check your inbox. If it landed in the Promotions tab, drag it to Primary so you never miss it.'=>'Revisa tu bandeja de entrada. Si llegó a la pestaña Promociones, arrástralo a Principal para no perdértelo.','Wrong address? Edit it'=>'¿Dirección incorrecta? Edítala','Update & resend'=>'Actualizar y reenviar','Cancel'=>'Cancelar','Sent to your new address'=>'Enviado a tu nueva dirección','Copy'=>'Copiar','Copied!'=>'¡Copiado!','OFF'=>'DTO.','Scratch me'=>'Ráscame','Active'=>'Activas','Abandoned'=>'Abandonado','Recovered'=>'Recuperado','Checkout'=>'Pago','Popup'=>'Ventana emergente','Account'=>'Cuenta','Imported'=>'Importado','cart statusEmail only'=>'Solo correo electrónico','cart statusConverted'=>'Convertido','Email'=>'Email','Name'=>'Nombre','Phone'=>'Teléfono','Cart'=>'Carrito','Cart total'=>'Total del carrito','Follow-ups'=>'Seguimientos','Source'=>'Origen','Status'=>'Estado','Created'=>'Creado','Last activity'=>'Última actividad','Highest cart value'=>'Carrito de mayor valor','Lowest cart value'=>'Carrito de menor valor','Oldest cart'=>'Carrito más antiguo','Newest cart'=>'Carrito más reciente','Today'=>'Hoy','Last 7 days'=>'Últimos 7 días','Last 30 days'=>'Últimos 30 días','Last 90 days'=>'Últimos 90 días','Custom range'=>'Rango personalizado','Editing is not available right now.'=>'La edición no está disponible en este momento.','Please wait a moment before trying again.'=>'Espera un momento antes de volver a intentarlo.','You have changed the address too many times. Please try later.'=>'Has cambiado la dirección demasiadas veces. Inténtalo más tarde.','Signup popup coupon (BrikPanel cart abandonment)'=>'Cupón de la ventana emergente de suscripción (abandono de carrito de BrikPanel)','Update BrikMentor to use this.'=>'Actualice BrikMentor para usar esto.','Hi {customer_name}, this is {store_name}. You left a few items in your cart - can I help you finish the order? {recovery_url}'=>'Hola {customer_name}, te escribo de {store_name}. Has dejado algunos artículos en tu carrito. ¿Te ayudo a completar el pedido? {recovery_url}','Message on WhatsApp: +%s (country guessed from your store address)'=>'Escribir por WhatsApp: +%s (país estimado a partir de la dirección de tu tienda)','Message on WhatsApp: +%s'=>'Escribir por WhatsApp: +%s','WhatsApp draft opened %1$s time · last %2$s'=>'Borrador de WhatsApp abierto %1$s vez · última %2$s' . "\0" . 'Borrador de WhatsApp abierto %1$s veces · última %2$s','WhatsApp draft opened %s time'=>'Borrador de WhatsApp abierto %s vez' . "\0" . 'Borrador de WhatsApp abierto %s veces','Next: %s'=>'Siguiente: %s','Last: %s'=>'Último: %s','%s email sent'=>'%s correo enviado' . "\0" . '%s correos enviados','Scheduled'=>'Programado','Not chased: %s'=>'Sin seguimiento: %s','Abandoned Carts'=>'Carritos abandonados','Emails collected from checkout and the signup popup, with a live snapshot of each cart.'=>'Correos electrónicos recogidos en la página de pago y en la ventana emergente de suscripción, con una instantánea en vivo de cada carrito.','Show an email signup popup to store visitors.'=>'Mostrar una ventana emergente de suscripción por correo a los visitantes de la tienda.','Email popup'=>'Ventana emergente de correo','Discount percentage for the coupon each popup signup receives. 0 disables the coupon.'=>'Porcentaje de descuento del cupón que recibe cada suscripción desde la ventana emergente. 0 desactiva el cupón.','Coupon'=>'Cupón','Export CSV'=>'Exportar CSV','Export Excel'=>'Exportar Excel','Email collection is currently turned off, so no new emails are being captured. You can re-enable it in the settings.'=>'La recogida de correos está desactivada, por lo que no se está capturando ninguna dirección nueva. Puedes volver a activarla en los ajustes.','Emails collected'=>'Correos electrónicos recogidos','Total cart value'=>'Valor total de los carritos','Active carts'=>'Carritos activos','Value in cart'=>'Valor en el carrito','Recoverable value'=>'Valor recuperable','Recover these carts on autopilot'=>'Recupera estos carritos en piloto automático','Recovered value'=>'Valor recuperado','Search email or name…'=>'Buscar correo o nombre…','Search email or name'=>'Buscar correo o nombre','Filter by status'=>'Filtrar por estado','All statuses'=>'Todos los estados','Filter by source'=>'Filtrar por origen','All sources'=>'Todas las fuentes','Filter by date range'=>'Filtrar por rango de fechas','Sort by'=>'Ordenar por','Clear'=>'Limpiar','Columns'=>'Columnas','Show, hide and reorder table columns'=>'Mostrar, ocultar y reordenar las columnas de la tabla','Drag to reorder, or hold Alt and press the arrow keys.'=>'Arrastra para reordenar, o mantén Alt y pulsa las flechas.','Reorder column: %s'=>'Reordenar columna: %s','From'=>'Desde','To'=>'Hasta','Loading…'=>'Cargando…','Previous'=>'Anterior','Next'=>'Siguiente','Something went wrong.'=>'Algo salió mal.','No emails captured yet.'=>'Aún no se ha capturado ningún correo electrónico.','Delete this entry?'=>'¿Eliminar esta entrada?','Delete'=>'Eliminar','No cart items recorded.'=>'No se ha registrado ningún artículo del carrito.','Order'=>'Pedido','item'=>'artículo','items'=>'artículos','Popup enabled.'=>'Ventana emergente activada.','Popup disabled.'=>'Ventana emergente desactivada.','Message on WhatsApp'=>'Escribir por WhatsApp','Send an email'=>'Enviar un correo electrónico','No phone number on file.'=>'No hay ningún número de teléfono registrado.','From their account'=>'De su cuenta','From a past order'=>'De un pedido anterior','No reminders sent.'=>'No se ha enviado ningún recordatorio.','Included with BrikMentor'=>'Incluido con BrikMentor','Invalid entry.'=>'Entrada no válida.','Link expired. Refresh the page and try again.'=>'El enlace ha caducado. Actualiza la página e inténtalo de nuevo.','First name'=>'Nombre','Last name'=>'Apellidos','Items'=>'Artículos','Currency'=>'Moneda','Cart contents'=>'Contenido del carrito','Created (UTC)'=>'Creado (UTC)','Last activity (UTC)'=>'Última actividad (UTC)','Abandoned at (UTC)'=>'Abandonado el (UTC)','Recovered at (UTC)'=>'Recuperado el (UTC)','Order ID'=>'ID del pedido','Export engine unavailable.'=>'El motor de exportación no está disponible.','Abandoned carts'=>'Carritos abandonados','Could not generate the Excel file.'=>'No se ha podido generar el archivo de Excel.','Cart abandonment'=>'Abandono de carrito','Popup title'=>'Título de la ventana emergente','Popup message'=>'Mensaje de la ventana emergente','Popup button text'=>'Texto del botón de la ventana emergente','Email placeholder'=>'Marcador de posición del correo electrónico','Success message'=>'Mensaje de éxito','Floating tab text'=>'Texto de la pestaña flotante','Invalid email warning'=>'Aviso de correo electrónico no válido','Error message'=>'Mensaje de error','Coupon heading'=>'Encabezado del cupón','Coupon note (saved for the cart)'=>'Nota del cupón (guardado para el carrito)','Coupon note (already on the cart)'=>'Nota del cupón (ya en el carrito)','Coupon note'=>'Nota del cupón','Reopen note'=>'Nota para volver a abrirlo','Floating tab after signup'=>'Pestaña flotante tras la suscripción','Copy button'=>'Botón Copiar','Copy button, once copied'=>'Botón Copiar, una vez copiado','Discount badge word'=>'Palabra de la insignia de descuento','Scratch card label'=>'Etiqueta del rasca y gana','Emailed confirmation'=>'Confirmación por correo electrónico','Emailed confirmation note'=>'Nota de la confirmación por correo electrónico','Edit address link'=>'Enlace para editar la dirección','Edit address, save button'=>'Editar dirección, botón de guardar','Edit address, cancel button'=>'Editar dirección, botón de cancelar','Edit address, done'=>'Editar dirección, hecho','Popup text per language'=>'Texto de la ventana emergente por idioma','The fields above are what shoppers reading %s see. Write the same popup here for each of your other languages. Anything you leave empty falls back to the wording above.'=>'Los campos de arriba son los que ven los compradores que leen %s. Escribe aquí la misma ventana emergente para cada uno de tus otros idiomas. Todo lo que dejes vacío vuelve al texto de arriba.','The popup itself is already written in %s in the fields above. What is left here is the wording the popup writes on its own, which follows your site language. Translate it if your language is not one BrikPanel ships a translation for.'=>'La ventana emergente ya está escrita en %s en los campos de arriba. Aquí queda el texto que la propia ventana emergente escribe, que sigue el idioma de tu sitio. Tradúcelo si BrikPanel no incluye una traducción para tu idioma.','Coupon panel and messages'=>'Panel del cupón y mensajes','Written by the popup itself. Translate these too, or leave them to your site language.'=>'Los escribe la propia ventana emergente. Tradúcelos también o déjalos en el idioma de tu sitio.','Collect customer emails from the checkout page and an optional signup popup, so abandoned carts can be followed up. Collected emails are listed on the Abandoned Carts page.'=>'Recoge los correos electrónicos de los clientes desde la página de pago y desde una ventana emergente opcional, para poder hacer seguimiento de los carritos abandonados. Los correos recogidos se muestran en la página Carritos abandonados.','Email collection'=>'Recogida de correos electrónicos','Capture emails typed at checkout (and from the popup) together with a cart snapshot'=>'Capturar los correos escritos al finalizar la compra (y los de la ventana emergente) junto con una instantánea del carrito','Mark cart as abandoned after'=>'Marcar el carrito como abandonado tras','minutes of inactivity'=>'minutos de inactividad','A cart with a known email and no activity for this long is marked as abandoned.'=>'Un carrito con un correo electrónico conocido y sin actividad durante este tiempo se marca como abandonado.','Count as recovered within'=>'Contar como recuperado dentro de','days'=>'días','An order only counts as a recovery when the matching cart was last active within this many days. Older carts are left untouched, so a customer coming back a month later is recorded as a new sale rather than a recovered cart.'=>'Un pedido solo cuenta como recuperación cuando el carrito correspondiente estuvo activo por última vez dentro de este número de días. Los carritos más antiguos se dejan intactos, así que un cliente que vuelve un mes después se registra como una venta nueva y no como un carrito recuperado.','WhatsApp message'=>'Mensaje de WhatsApp','Placeholders: %s'=>'Marcadores: %s','Opens as an editable draft in WhatsApp, so nothing is sent until you press send. Write it in any language, and use line breaks freely - they are kept. {items} lists every product on its own line, so give it a line of its own. {recovery_url} rebuilds the shopper\'s cart in one tap; {cart_url} is just your cart page.'=>'Se abre como un borrador editable en WhatsApp, así que no se envía nada hasta que pulsas enviar. Escríbelo en cualquier idioma y usa saltos de línea con libertad: se conservan. {items} lista cada producto en su propia línea, así que dale una línea propia. {recovery_url} reconstruye el carrito del cliente con un toque; {cart_url} es solo la página de tu carrito.','Show a signup popup to store visitors (not shown on the checkout page)'=>'Mostrar una ventana emergente de suscripción a los visitantes (no se muestra en la página de pago)','Visitors who leave their email here are matched with their cart later, even if they never type an email at checkout. After closing, the popup stays available as a small floating tab.'=>'Los visitantes que dejan aquí su correo se asocian después con su carrito, aunque nunca escriban un correo al finalizar la compra. Tras cerrarla, la ventana emergente sigue disponible como una pequeña pestaña flotante.','Popup discount'=>'Descuento de la ventana emergente','% off coupon for popup signups'=>'% de descuento del cupón para las suscripciones desde la ventana emergente','Each signup gets a personal single-use percentage coupon restricted to their email, valid for 30 days. Set to 0 to collect emails without a coupon.'=>'Cada suscripción recibe un cupón porcentual personal de un solo uso, restringido a su correo electrónico y válido durante 30 días. Ponlo a 0 para recoger correos sin cupón.','Apply automatically'=>'Aplicar automáticamente','Add the signup coupon to the visitor\'s cart for them'=>'Añadir el cupón de registro al carrito del visitante por él','The visitor never has to copy the code down. If their cart is empty when they sign up, the code waits and goes on as soon as they add something. They can still type it in at checkout either way. Ignored while a companion plugin delivers the coupon by email.'=>'El visitante nunca tiene que copiar el código. Si su carrito está vacío cuando se registra, el código espera y se aplica en cuanto añade algo. En cualquier caso, aún puede escribirlo al pagar. Se ignora mientras un plugin complementario envíe el cupón por correo electrónico.','Offer animation'=>'Animación de la oferta','Visual style of the animated discount badge at the top of the popup. Only shown while a popup discount is set.'=>'Estilo visual de la insignia animada de descuento en la parte superior de la ventana emergente. Solo se muestra mientras haya un descuento configurado.','Sealed envelope: the seal pops and the coupon rises'=>'Sobre sellado: el sello salta y el cupón asciende','Pocket card: coupon springs out of a pocket'=>'Tarjeta de bolsillo: el cupón sale de un bolsillo','Scratch card: a coin scratches the foil away'=>'Tarjeta rasca y gana: una moneda raspa la lámina','Slot machine: reels spin and land on the discount'=>'Máquina tragaperras: los rodillos giran y se detienen en el descuento','Magnetic assembly: pieces fly in and form the coupon'=>'Montaje magnético: las piezas llegan volando y forman el cupón','Classic ticket: floating coupon with a shine sweep'=>'Ticket clásico: cupón flotante con un barrido de brillo','Shown on the small tab that stays on the left edge after the popup is closed. Leave empty to use the discount-based default.'=>'Se muestra en la pequeña pestaña que permanece en el borde izquierdo después de cerrar la ventana emergente. Déjalo vacío para usar el texto predeterminado basado en el descuento.','Wait for cookie banner'=>'Esperar al banner de cookies','Show the popup only after the visitor answers the cookie banner'=>'Mostrar la ventana emergente solo después de que el visitante responda al banner de cookies','Stops the popup from landing on top of a cookie banner the visitor has not dealt with yet. Accepting and declining both release it, because signing up for an offer is not tracking. On a store with no cookie banner nothing changes, and the popup opens after 30 seconds in any case, so it can never be lost.'=>'Evita que la ventana emergente aparezca sobre un banner de cookies que el visitante aún no ha respondido. Tanto aceptar como rechazar la liberan, porque suscribirse a una oferta no es rastreo. En una tienda sin banner de cookies no cambia nada y, en cualquier caso, la ventana se abre a los 30 segundos, así que nunca se pierde.','Popup delay'=>'Retardo de la ventana emergente','seconds after the page loads'=>'segundos después de cargarse la página','Do not show again for'=>'No volver a mostrar durante','days after a visitor closes the floating tab'=>'días después de que un visitante cierre la pestaña flotante','Closing the popup itself only collapses it into the floating tab; this cooldown applies when the visitor dismisses the tab too.'=>'Cerrar la ventana emergente solo la contrae en la pestaña flotante; este periodo de espera se aplica cuando el visitante descarta también la pestaña.','Mark abandoned carts'=>'Marcar los carritos abandonados','Flips inactive captured carts to abandoned and notifies integrations.'=>'Pasa a abandonados los carritos capturados que están inactivos y avisa a las integraciones.','%d item was added to your cart from a shared link.'=>'%d artículo se añadió a tu carrito desde un enlace compartido.' . "\0" . '%d artículos se añadieron a tu carrito desde un enlace compartido.','The shared link could not add any products to your cart. They may be out of stock or no longer available.'=>'El enlace compartido no ha podido añadir ningún producto a tu carrito. Puede que estén agotados o que ya no estén disponibles.','Cart share'=>'Compartir carrito','Pick the products a customer asked for, then send them one link that fills their cart.'=>'Elige los productos que te ha pedido un cliente y envíale un único enlace que llene su carrito.','Search products by name or SKU…'=>'Buscar productos por nombre o SKU…','No products yet. Search above to add the items your customer requested.'=>'Todavía no hay productos. Busca arriba para añadir los artículos que te pidió tu cliente.','Share link'=>'Enlace para compartir','Your link appears here once you add a product.'=>'Tu enlace aparecerá aquí en cuanto añadas un producto.','Share on WhatsApp'=>'Compartir por WhatsApp','verb: share the cart linkShare'=>'Compartir','Pick a variation for every variable product so it can be included in the link.'=>'Elige una variación para cada producto variable para que pueda incluirse en el enlace.','When the customer opens the link, these products land in their cart and they go straight to checkout.'=>'Cuando el cliente abra el enlace, estos productos irán a su carrito e irá directo a finalizar la compra.','This product has no variations.'=>'Este producto no tiene variaciones.','Share cart'=>'Compartir carrito','Share this cart'=>'Compartir este carrito','Anyone who opens this link gets these items in their cart.'=>'Cualquiera que abra este enlace recibirá estos artículos en su carrito.','WhatsApp'=>'WhatsApp','Your cart is empty, so there is nothing to share yet.'=>'Tu carrito está vacío, así que todavía no hay nada que compartir.','Here is my cart:'=>'Este es mi carrito:','Build a cart of products in the admin and hand a customer one link that fills their cart, and let customers share their own cart from the store. Great for orders that come in over Instagram, WhatsApp or Facebook.'=>'Crea un carrito de productos desde el escritorio y dale al cliente un único enlace que llene su carrito; además, tus clientes pueden compartir su propio carrito desde la tienda. Ideal para los pedidos que llegan por Instagram, WhatsApp o Facebook.','Enable shareable cart links and the admin cart builder'=>'Activar los enlaces de carrito compartible y el creador de carritos del escritorio','Storefront share button'=>'Botón de compartir en la tienda','Show a "Share cart" button on the store cart page so customers can share their own cart'=>'Muestra un botón "Compartir carrito" en la página del carrito de la tienda para que los clientes puedan compartir su propio carrito','The button appears on the cart page and copies a link that reproduces the current cart.'=>'El botón aparece en la página del carrito y copia un enlace que reproduce el carrito actual.','Coupons'=>'Cupones','Add coupon'=>'Añadir cupón','Search coupons...'=>'Buscar cupones...','All'=>'Todos','Published'=>'Publicado','Draft'=>'Borrador','Trash'=>'Papelera','Newest first'=>'Más recientes primero','Oldest first'=>'Más antiguos primero','Code A-Z'=>'Código A-Z','Code Z-A'=>'Código Z-A','selected'=>'seleccionados','Select all'=>'Seleccionar todos','Deselect all'=>'Deseleccionar todos','Publish'=>'Publicar','Set as draft'=>'Establecer como borrador','Move to trash'=>'Mover a la papelera','Code'=>'Código','Type'=>'Tipo','Amount'=>'Importe','Description'=>'Descripción','Usage / limit'=>'Uso / Límite','Revenue'=>'Ingresos','Expiry date'=>'Fecha de caducidad','Edit coupon'=>'Editar cupón','General'=>'General','Coupon code'=>'Código del cupón','e.g. SUMMER2024'=>'p. ej. VERANO2024','Generate'=>'Generar','Optional description for internal use'=>'Descripción opcional para uso interno','Discount type'=>'Tipo de descuento','Percentage discount'=>'Descuento porcentual','Fixed cart discount'=>'Descuento fijo en el carrito','Fixed product discount'=>'Descuento fijo en el producto','Free shipping'=>'Envío gratis','Usage restrictions'=>'Restricciones de uso','Minimum spend'=>'Gasto mínimo','No minimum'=>'Sin mínimo','Maximum spend'=>'Gasto máximo','No maximum'=>'Sin máximo','Individual use only'=>'Solo uso individual','Cannot be used with other coupons'=>'No se puede usar con otros cupones','Exclude sale items'=>'Excluir artículos en oferta','Limit the coupon to these products. Leave empty to allow all products.'=>'Limita el cupón a estos productos. Déjalo vacío para permitir todos los productos.','Exclude products'=>'Excluir productos','Search products to exclude…'=>'Buscar productos a excluir…','Coupon will not apply when the cart contains these products.'=>'El cupón no se aplicará cuando el carrito contenga estos productos.','Product categories'=>'Categorías de producto','Search categories…'=>'Buscar categorías…','Coupon applies only to products in these categories. Leave empty to allow all categories.'=>'El cupón se aplica solo a productos en estas categorías. Déjalo vacío para permitir todas las categorías.','Exclude categories'=>'Excluir categorías','Search categories to exclude…'=>'Buscar categorías a excluir…','Coupon will not apply to products in these categories.'=>'El cupón no se aplicará a productos en estas categorías.','Assigned customers'=>'Clientes asignados','Search customers by name, username or email…'=>'Busca clientes por nombre, nombre de usuario o correo electrónico…','Only these customers can use the coupon. Pick registered users from the list, or type any email address (wildcards like *@example.com work too) and press Enter. A picked user is matched by their account email, so it works even if they check out with a different billing address.'=>'Solo estos clientes pueden usar el cupón. Elige usuarios registrados de la lista o escribe cualquier dirección de correo electrónico y pulsa Intro (los comodines como *@example.com también funcionan). Un usuario elegido se identifica por el correo de su cuenta, así que funciona aunque pague con otra dirección de facturación.','Usage limits'=>'Límites de uso','Usage limit per coupon'=>'Límite de uso por cupón','Unlimited'=>'Ilimitado','Usage limit per user'=>'Límite de uso por usuario','Limit usage to X items'=>'Limitar uso a X artículos','All matching items'=>'Todos los artículos coincidentes','Caps the number of matching items the discount applies to per cart. Only used with product or category restrictions.'=>'Limita el número de artículos coincidentes a los que se aplica el descuento por carrito. Solo se usa con restricciones de producto o categoría.','Usage count'=>'Recuento de uso','Save changes'=>'Guardar cambios','Coupon code is required.'=>'Se requiere el código del cupón.','A coupon with this code already exists.'=>'Ya existe un cupón con este código.','Coupon updated!'=>'¡Cupón actualizado!','Coupon created!'=>'¡Cupón creado!','Invalid coupon ID.'=>'ID de cupón no válido.','Coupon not found.'=>'Cupón no encontrado.','Coupon permanently deleted.'=>'Cupón eliminado permanentemente.','Coupon moved to trash.'=>'Cupón movido a la papelera.','Coupon status changed to %s.'=>'Estado del cupón cambiado a %s.','Coupon duplicated!'=>'¡Cupón duplicado!','user display name (username)%1$s (%2$s)'=>'%1$s (%2$s)','(deleted product #%d)'=>'(producto eliminado #%d)','(deleted category #%d)'=>'(categoría eliminada #%d)','When your store takes orders in more than one currency, BrikPanel converts every order to your store currency before adding it up, so Revenue, Average Order Value and the sales chart are never a meaningless mix of currencies. If you use a multi-currency plugin such as CURCY, the exact rate from the day of each sale is read automatically from the order; you only need the rates below for currencies that arrive without one.'=>'Cuando tu tienda recibe pedidos en más de una moneda, BrikPanel convierte cada pedido a la moneda de tu tienda antes de sumarlo, para que los ingresos, el valor medio del pedido y el gráfico de ventas nunca sean una mezcla sin sentido de monedas. Si usas un plugin multimoneda como CURCY, el tipo de cambio exacto del día de cada venta se lee automáticamente del pedido; solo necesitas los tipos de abajo para las monedas que llegan sin uno.','Exchange rates to your store currency'=>'Tasas de cambio a la moneda de tu tienda','Your store currency is %s. Enter how much one unit of each currency below is worth in it.'=>'La moneda de tu tienda es %s. Introduce cuánto vale en ella una unidad de cada moneda de abajo.','All of your orders are already in %s, so there is nothing to convert here.'=>'Todos tus pedidos ya están en %s, por lo que no hay nada que convertir aquí.','Leave a rate empty to count those orders at their original number (no conversion). Orders that already carry a rate from your multi-currency plugin ignore the values here and always use their own day-of-sale rate.'=>'Deja una tasa vacía para contar esos pedidos con su número original (sin conversión). Los pedidos que ya llevan una tasa de tu plugin multimoneda ignoran los valores de aquí y siempre usan su propia tasa del día de la venta.','Customer Analytics'=>'Analíticas de clientes','%1$s repeat (%2$s)'=>'%1$s recurrente (%2$s)' . "\0" . '%1$s recurrentes (%2$s)','Invalid request.'=>'Solicitud no válida.','User ID'=>'ID de usuario','Order count'=>'Número de pedidos','Total spent (LTV)'=>'Total gastado (LTV)','Average order value'=>'Valor medio del pedido','Recency (days)'=>'Recencia (días)','First order'=>'Primer pedido','Last order'=>'Último pedido','Invalid segment.'=>'Segmento no válido.','Segment'=>'Segmento','R'=>'R','F'=>'F','M'=>'M','Cohort month'=>'Mes de cohorte','Period offset (months)'=>'Desplazamiento del periodo (meses)','Cohort size'=>'Tamaño de cohorte','Retained customers'=>'Clientes retenidos','Retention rate (%)'=>'Tasa de retención (%)','Action Scheduler is not available.'=>'Action Scheduler no está disponible.','Customer metrics recomputed.'=>'Métricas de clientes recalculadas.','User #%d'=>'Usuario n.º %d','Exclusions saved.'=>'Exclusiones guardadas.','Last refreshed: %s'=>'Última actualización: %s','Exclude customers'=>'Excluir clientes','Recompute now'=>'Recalcular ahora','Refreshing…'=>'Actualizando…','Lifetime value'=>'Valor de vida','RFM segments'=>'Segmentos RFM','Cohort retention'=>'Retención por cohorte','Total customers'=>'Clientes totales','Average LTV'=>'LTV medio','Median:'=>'Mediana:','Total LTV'=>'LTV total','AOV:'=>'AOV:','Top customer'=>'Mejor cliente','highest lifetime spend'=>'mayor gasto de por vida','LTV distribution'=>'Distribución del LTV','How many customers fall into each lifetime-spend bracket.'=>'Cuántos clientes caen en cada tramo de gasto de por vida.','Top customers by LTV'=>'Mejores clientes por LTV','Sorted by lifetime spend, descending. Click a row to open the customer profile.'=>'Ordenados por gasto de por vida, descendente. Haz clic en una fila para abrir el perfil del cliente.','Customer'=>'Cliente','AOV'=>'AOV','LTV'=>'LTV','Recency'=>'Recencia','Customer segments'=>'Segmentos de clientes','Each customer is scored from 1 to 5 on Recency, Frequency, and Monetary value, then placed into one of the RFM segments below. Click a card to drill into its customers.'=>'Cada cliente recibe una puntuación de 1 a 5 en recencia, frecuencia y valor monetario, y luego se coloca en uno de los segmentos RFM de abajo. Haz clic en una tarjeta para ver sus clientes.','Segment customers'=>'Clientes del segmento','Export this segment (CSV)'=>'Exportar este segmento (CSV)','Clear selection'=>'Limpiar selección','RFM'=>'RFM','Click a segment above to load its customers.'=>'Haz clic en un segmento arriba para cargar sus clientes.','Each row is a monthly cohort of customers acquired that month. Each cell shows the % of that cohort who placed at least one order N months later.'=>'Cada fila es una cohorte mensual de clientes adquiridos ese mes. Cada celda muestra el % de esa cohorte que realizó al menos un pedido N meses después.','Window:'=>'Ventana:','Last 6 months'=>'Últimos 6 meses','Last 12 months'=>'Últimos 12 meses','Last 24 months'=>'Últimos 24 meses','Average retention by month offset'=>'Retención media por desplazamiento de mes','Across all cohorts in the selected window. Useful for spotting where the typical drop-off happens.'=>'En todas las cohortes del periodo seleccionado. Útil para ver dónde se produce la caída típica.','Export matrix (CSV)'=>'Exportar matriz (CSV)','Exclude customers from analytics'=>'Excluir clientes de las analíticas','Pick the accounts you do not want counted as customers, for example a point-of-sale or staff login that places many orders. Their orders still count toward your shop revenue and order totals, but they are left out of customer averages, segments, and retention so the numbers reflect your real customers.'=>'Elige las cuentas que no quieres que se cuenten como clientes, por ejemplo un terminal de punto de venta o un acceso de personal que realiza muchos pedidos. Sus pedidos siguen contando para los ingresos y totales de pedidos de tu tienda, pero quedan fuera de las medias de clientes, los segmentos y la retención, de modo que las cifras reflejen a tus clientes reales.','People'=>'Personas','Search by name or email…'=>'Buscar por nombre o correo electrónico…','Roles'=>'Roles','Everyone with a checked role is excluded too.'=>'Todos los que tengan un rol marcado también quedan excluidos.','Cost of goods'=>'Coste de mercancía','Expenses (taxes, ad spend, supplier costs)'=>'Gastos (impuestos, gasto en publicidad, costes de proveedores)','Returns (refunds)'=>'Devoluciones (reembolsos)','Coupons (discounts given)'=>'Cupones (descuentos aplicados)','Move up'=>'Subir','Move down'=>'Bajar','Reset to default'=>'Restablecer a valores predeterminados','Hide sidebar'=>'Ocultar barra lateral','Show sidebar'=>'Mostrar barra lateral','Toggle navigation'=>'Alternar navegación','Clearing cache…'=>'Limpiando caché…','Cache could not be cleared.'=>'No se pudo limpiar la caché.','BrikPanel dashboard'=>'Dashboard de BrikPanel','Dashboard'=>'Dashboard','Admin'=>'Administración','Live visitors right now'=>'Visitantes en vivo ahora mismo','live'=>'en vivo','Search orders'=>'Buscar pedidos','Search'=>'Buscar','Create'=>'Crear','New product'=>'Nuevo producto','New order'=>'Nuevo pedido','New coupon'=>'Nuevo cupón','Cart share link'=>'Enlace para compartir el carrito','New post'=>'Nueva entrada','Order notifications'=>'Notificaciones de pedidos','Needs attention'=>'Requiere atención','Processing orders'=>'Pedidos en proceso','Pending payment'=>'Pago pendiente','On hold'=>'En espera','Out of stock'=>'Agotado','New customers today'=>'Nuevos clientes hoy','Hidden notices from other plugins'=>'Avisos ocultos de otros plugins','Hidden notices'=>'Avisos ocultos','From other plugins &amp; themes'=>'De otros plugins y temas','No hidden notices on this page.'=>'No hay avisos ocultos en esta página.','View store'=>'Ver tienda','Your profile'=>'Tu perfil','BrikPanel settings'=>'Ajustes de BrikPanel','Network Admin'=>'Administración de la red','Log out'=>'Cerrar sesión','Store coming soon'=>'Tienda próximamente','store visibility badgeComing soon'=>'Próximamente','Your store is hidden from visitors. Click to change site visibility.'=>'Tu tienda está oculta para los visitantes. Haz clic para cambiar la visibilidad del sitio.','Purge %s'=>'Purgar %s','Clear cache'=>'Limpiar caché','Clear all caches'=>'Limpiar todas las cachés','Your session has expired. Please reload the page.'=>'Tu sesión ha caducado. Vuelve a cargar la página.','You are not allowed to do this.'=>'No tienes permiso para hacer esto.','Pick one or more widgets in "Include WordPress dashboard widgets" above and save. Each embedded widget then appears here so you can choose who sees it.'=>'Elige uno o más widgets en "Incluir widgets del escritorio de WordPress" arriba y guarda. Cada widget incrustado aparecerá aquí para que puedas elegir quién lo ve.','Visible to'=>'Visible para','Who can see this widget'=>'Quién puede ver este widget','Everyone'=>'Todos','Admins only'=>'Solo administradores','Specific roles'=>'Roles específicos','Hide from these roles'=>'Ocultar a estos roles','Profit (Revenue, Cost of goods, Net profit)'=>'Beneficio (Ingresos, Coste de mercancía, Beneficio neto)','KPI cards (Sales, Orders, AOV, Visitors, Conversion)'=>'Tarjetas de KPIs (Ventas, Pedidos, AOV, Visitantes, Conversión)','Sales over time + Live visitors'=>'Ventas a lo largo del tiempo + Visitantes en vivo','Conversion funnel + Order rates'=>'Embudo de conversión + Tasas de pedidos','Order locations globe + Top countries/cities'=>'Globo de ubicaciones de pedidos + Países/ciudades principales','Top products + Recent orders'=>'Productos principales + Pedidos recientes','Most viewed pages + Most added to cart'=>'Páginas más vistas + Más añadidos al carrito','Visitors by device + Customer types + Traffic sources'=>'Visitantes por dispositivo + Tipos de cliente + Fuentes de tráfico','Customer segments (RFM)'=>'Segmentos de clientes (RFM)','Low stock + Customer lifetime value'=>'Stock bajo + Valor de vida del cliente','Subscriptions'=>'Suscripciones','WordPress dashboard widgets'=>'Widgets del escritorio de WordPress','Marketplace analytics (BrikMarket)'=>'Analíticas de marketplace (BrikMarket)','With marketplace'=>'Con marketplace','Copy everything'=>'Copiar todo','Collecting data…'=>'Recopilando datos…','Copied to clipboard!'=>'¡Copiado al portapapeles!','Failed, try again'=>'Falló, inténtalo de nuevo','What does “Copy everything” do?'=>'¿Qué hace «Copiar todo»?','Bundles your store’s key data (KPIs, profit and margins, cost of goods, ad spend, expenses, top products and categories, customers and settings) into a single Markdown report and copies it to your clipboard. Paste it into ChatGPT, Claude or any AI tool to get instant analysis, insights and recommendations about your store.'=>'Reúne los datos clave de tu tienda (KPI, beneficio y márgenes, coste de mercancía, gasto publicitario, gastos, productos y categorías más vendidos, clientes y ajustes) en un único informe Markdown y lo copia en tu portapapeles. Pégalo en ChatGPT, Claude o cualquier herramienta de IA para obtener al instante análisis, ideas y recomendaciones sobre tu tienda.','Ad spend settings'=>'Ajustes de gasto publicitario','Connect ad accounts'=>'Conectar cuentas publicitarias','Download the selected period as an Excel workbook (opens in Excel / Google Sheets)'=>'Descarga el periodo seleccionado como libro de Excel (se abre en Excel / Google Sheets)','Preparing…'=>'Preparando…','Yesterday'=>'Ayer','Custom'=>'Personalizado','Select dates'=>'Seleccionar fechas','Where this data comes from'=>'De dónde provienen estos datos','BrikPanel started measuring visitors and conversions on %s, the day it was activated. There is no visitor history before that date, so a recent install can read low or empty here. Your sales and orders are not affected. Those use your full WooCommerce history.'=>'BrikPanel empezó a medir visitantes y conversiones el %s, el día en que se activó. No hay historial de visitantes anterior a esa fecha, por lo que una instalación reciente puede mostrar cifras bajas o vacías aquí. Tus ventas y pedidos no se ven afectados. Esos usan todo tu historial de WooCommerce.','BrikPanel measures visitors and conversions from the day it was activated. There is no visitor history before that, so a recent install can read low or empty here. Your sales and orders are not affected. Those use your full WooCommerce history.'=>'BrikPanel mide visitantes y conversiones desde el día en que se activó. No hay historial de visitantes anterior a eso, por lo que una instalación reciente puede mostrar cifras bajas o vacías aquí. Tus ventas y pedidos no se ven afectados. Esos usan todo tu historial de WooCommerce.','About these numbers'=>'Acerca de estas cifras','Sales, orders, profit and customer figures use your full WooCommerce order history.'=>'Las cifras de ventas, pedidos, beneficio y clientes usan todo tu historial de pedidos de WooCommerce.','Visitors, conversion rate and the funnel are measured by BrikPanel from %s, the day it was activated, so they have no earlier history.'=>'Los visitantes, la tasa de conversión y el embudo los mide BrikPanel desde el %s, el día en que se activó, por lo que no tienen historial anterior.','Visitors, conversion rate and the funnel are measured by BrikPanel from the day it was activated, so they have no earlier history.'=>'Los visitantes, la tasa de conversión y el embudo los mide BrikPanel desde el día en que se activó, por lo que no tienen historial anterior.','Orders placed by store administrators are left out of every figure, so your own test orders do not change the totals.'=>'Los pedidos realizados por administradores de la tienda quedan fuera de todas las cifras, por lo que tus propios pedidos de prueba no cambian los totales.','Why this can look low'=>'Por qué esto puede parecer bajo','Orders placed by store administrators are not counted here, so test orders you place on your own admin account do not change this figure. Real customer orders are always included.'=>'Los pedidos realizados por administradores de la tienda no se cuentan aquí, por lo que los pedidos de prueba que hagas con tu propia cuenta de administración no cambian esta cifra. Los pedidos de clientes reales siempre se incluyen.','Total sales'=>'Ventas totales','Avg. order value'=>'Valor medio del pedido','Visitors'=>'Visitantes','Conversion rate'=>'Tasa de conversión','The total of all paid orders for the selected dates (Processing and Completed by default), with shipping included, tax taken out and any customer refunds in the period subtracted. Orders placed by store administrators are left out so your own test orders do not change it. Tax is taken out because of the "Tax in the Profit section" setting, so it is not in Expenses either.'=>'El total de todos los pedidos pagados de las fechas seleccionadas (En proceso y Completado por defecto), con el envío incluido, sin impuestos y con los reembolsos a clientes del periodo restados. Los pedidos realizados por administradores de la tienda quedan fuera para que tus propios pedidos de prueba no lo cambien. Los impuestos se restan por el ajuste "Impuestos en la sección de beneficios", así que tampoco están en los gastos.','The total of all paid orders for the selected dates (Processing and Completed by default), with shipping included and tax taken out. Orders placed by store administrators are left out so your own test orders do not change it. Tax is taken out because of the "Tax in the Profit section" setting, so it is not in Expenses either.'=>'El total de todos los pedidos pagados de las fechas seleccionadas (En proceso y Completado por defecto), con el envío incluido y sin impuestos. Los pedidos realizados por administradores de la tienda quedan fuera para que tus propios pedidos de prueba no lo cambien. Los impuestos se restan por el ajuste "Impuestos en la sección de beneficios", así que tampoco están en los gastos.','Operating costs for the period: ad spend from connected ad platforms (store currency only), payment processing fees charged by the gateway, supplier and stock costs from received purchase orders, plus anything logged in the Expenses module. Tax is not here because it is already taken out of Revenue. Open the breakdown to see each part.'=>'Costes operativos del periodo: gasto en anuncios de las plataformas conectadas (solo en la moneda de la tienda), comisiones de pago que cobra la pasarela, costes de proveedores y stock de las órdenes de compra recibidas, además de todo lo registrado en el módulo Gastos. Los impuestos no están aquí porque ya se restan de los ingresos. Abre el desglose para ver cada parte.','The total of all paid orders for the selected dates (Processing and Completed by default), with tax and shipping included and any customer refunds in the period subtracted. Orders placed by store administrators are left out so your own test orders do not change it. You can change which statuses count under Settings, then Analytics.'=>'El total de todos los pedidos pagados de las fechas seleccionadas (En proceso y Completado por defecto), con impuestos y envío incluidos y restando cualquier reembolso a clientes del periodo. Los pedidos realizados por administradores de la tienda quedan fuera para que tus propios pedidos de prueba no lo cambien. Puedes cambiar qué estados se cuentan en Ajustes y luego Analíticas.','The total of all paid orders for the selected dates (Processing and Completed by default), with tax and shipping included. Orders placed by store administrators are left out so your own test orders do not change it. You can change which statuses count under Settings, then Analytics.'=>'El total de todos los pedidos pagados de las fechas seleccionadas (En proceso y Completado por defecto), con impuestos y envío incluidos. Los pedidos realizados por administradores de la tienda quedan fuera para que tus propios pedidos de prueba no lo cambien. Puedes cambiar qué estados se cuentan en Ajustes y luego Analíticas.','Operating costs for the period: ad spend from connected ad platforms (store currency only), payment processing fees charged by the gateway, supplier and stock costs from received purchase orders, plus anything logged in the Expenses module. Tax is not here because it is shown under Revenue and taken off Net profit. Open the breakdown to see each part.'=>'Costes operativos del periodo: gasto en anuncios de las plataformas conectadas (solo en la moneda de la tienda), comisiones de pago que cobra la pasarela, costes de proveedores y stock de las órdenes de compra recibidas, además de todo lo registrado en el módulo Gastos. Los impuestos no están aquí porque se muestran bajo los ingresos y se restan del beneficio neto. Abre el desglose para ver cada parte.','Operating costs for the period: order tax, ad spend from connected ad platforms (store currency only), payment processing fees charged by the gateway, supplier and stock costs from received purchase orders, plus anything logged in the Expenses module. Open the breakdown to see each part.'=>'Costes operativos del periodo: impuestos de los pedidos, gasto en anuncios de las plataformas conectadas (solo en la moneda de la tienda), comisiones de pago que cobra la pasarela, costes de proveedores y stock de las órdenes de compra recibidas, además de todo lo registrado en el módulo Gastos. Abre el desglose para ver cada parte.','How Revenue is calculated'=>'Cómo se calculan los ingresos','Show revenue breakdown'=>'Mostrar desglose de ingresos','How cost of goods is calculated'=>'Cómo se calcula el coste de mercancía','The "Cost of goods" you set on each product, multiplied by the quantity sold in paid orders for the period. Variations use their own cost and fall back to the parent product. Any product with no cost set counts as zero, which overstates Net profit, so fill those in for an accurate margin.'=>'El "Coste de mercancía" que estableces en cada producto, multiplicado por la cantidad vendida en pedidos pagados del periodo. Las variaciones usan su propio coste y recurren al producto principal. Cualquier producto sin coste establecido cuenta como cero, lo que infla el beneficio neto, así que complétalos para obtener un margen preciso.','Expenses'=>'Gastos','What Expenses includes'=>'Qué incluyen los gastos','Add expense'=>'Añadir gasto','Show expense breakdown'=>'Mostrar desglose de gastos','Net profit'=>'Beneficio neto','How net profit is calculated'=>'Cómo se calcula el beneficio neto','Revenue minus Cost of goods, Tax and Expenses. This is what is left after the cost of what you sold, the tax and your operating costs for the period. A negative figure means a loss.'=>'Ingresos menos coste de mercancía, impuestos y gastos. Esto es lo que queda después del coste de lo que vendiste, los impuestos y tus costes operativos del periodo. Una cifra negativa significa una pérdida.','Revenue minus Cost of goods minus Expenses. This is what is left after the cost of what you sold and your operating costs for the period. A negative figure means a loss.'=>'Ingresos menos coste de mercancía menos gastos. Esto es lo que queda después del coste de lo que vendiste y tus costes operativos del periodo. Una cifra negativa significa una pérdida.','Fixed amount'=>'Importe fijo','Percentage of revenue'=>'Porcentaje de los ingresos','Cost per order'=>'Coste por pedido','which orders a per-order cost is charged onApplies to'=>'Se aplica a','Every order'=>'Todos los pedidos','Orders shipped free'=>'Pedidos con envío gratis','Shipping class'=>'Clase de envío','Title'=>'Título','e.g. Rent, Salaries, Credit card commission'=>'p. ej. Alquiler, Salarios, Comisión de tarjeta de crédito','the expense this cost is filed underPart of'=>'Forma parte de','optional'=>'opcional','Shows this cost under one you already have. Amounts stay separate.'=>'Muestra este coste bajo uno que ya tienes. Los importes se mantienen separados.','Repeats'=>'Se repite','One-time'=>'Único','Monthly'=>'Mensual','Weekly'=>'Semanal','Yearly'=>'Anual','Note (optional)'=>'Nota (opcional)','What is this for?'=>'¿Para qué sirve esto?','A repeating expense is counted automatically in every period from this date onward.'=>'Un gasto recurrente se cuenta automáticamente en cada periodo a partir de esta fecha.','A percentage cost is applied to your revenue in every period from this date onward (great for card or marketplace commission).'=>'Un coste porcentual se aplica a tus ingresos en cada periodo a partir de esta fecha (ideal para comisiones de tarjeta o de marketplace).','A per-order cost is charged once for every matching order in the period you are viewing (great for packaging, or the courier fee on orders you ship free).'=>'Un coste por pedido se cobra una vez por cada pedido que cumpla la condición en el periodo que estás viendo (ideal para el embalaje o la tarifa del transportista en pedidos con envío gratis).','Save expense'=>'Guardar gasto','Remove this expense?'=>'¿Eliminar este gasto?','What to remove'=>'Qué eliminar','Marketplace sales'=>'Ventas del marketplace','Marketplace orders'=>'Pedidos del marketplace','Avg. marketplace order'=>'Pedido medio del marketplace','Share of total revenue'=>'Proporción de los ingresos totales','Revenue by marketplace'=>'Ingresos por marketplace','Loading...'=>'Cargando...','Marketplace share'=>'Cuota del marketplace','Top categories from marketplaces'=>'Categorías principales de los marketplaces','Top marketplace products'=>'Productos principales del marketplace','Sales over time'=>'Ventas a lo largo del tiempo','Live visitors'=>'Visitantes en vivo','No active visitors'=>'Sin visitantes activos','Conversion funnel'=>'Embudo de conversión','Order rates'=>'Tasas de pedidos','Order locations'=>'Ubicaciones de pedidos','View mode'=>'Modo de vista','Customers'=>'Clientes','Toggle theme'=>'Alternar tema','Top countries'=>'Países principales','Top cities'=>'Ciudades principales','Top products'=>'Productos principales','Recent orders'=>'Pedidos recientes','Most viewed pages'=>'Páginas más vistas','Most added to cart'=>'Más añadidos al carrito','Visitors by device'=>'Visitantes por dispositivo','Device breakdown view'=>'Vista de desglose por dispositivo','Sources'=>'Fuentes','Top referrers'=>'Principales referencias','Customer types'=>'Tipos de clientes','View details →'=>'Ver detalles →','%s product'=>'%s producto' . "\0" . '%s productos','%s variation'=>'%s variación' . "\0" . '%s variaciones','%s sellable item'=>'%s artículo vendible' . "\0" . '%s artículos vendibles','%s unit in stock'=>'%s unidad en stock' . "\0" . '%s unidades en stock','Low stock'=>'Stock bajo','Sellable items counts each variable product by its purchasable variations, not as a single product. Units in stock is the total on-hand quantity across all stock-managed products.'=>'Los artículos vendibles cuentan cada producto variable por sus variaciones comprables, no como un único producto. Las unidades en stock son la cantidad total disponible en todos los productos con inventario gestionado.','Customer lifetime value'=>'Valor de vida del cliente','No products yet.'=>'Todavía no hay productos.','Stock management is turned off in WooCommerce, so stock levels are not tracked.'=>'La gestión de inventario está desactivada en WooCommerce, así que no se controlan las existencias.','Inventory settings'=>'Ajustes de inventario','None of your products track their stock quantity, so none can run low.'=>'Ninguno de tus productos controla su cantidad en stock, así que ninguno puede quedarse corto.','No product is running low.'=>'Ningún producto se está quedando sin stock.','%s product is out of stock'=>'%s producto está agotado' . "\0" . '%s productos están agotados','WordPress widgets'=>'Widgets de WordPress','Widget failed to load.'=>'Error al cargar el widget.','Cancelled'=>'Canceladas','Expired'=>'Caducadas','Pending cancellation'=>'Pendiente de cancelación','Tax'=>'Impuestos','Payment fees'=>'Comisiones de pago','Shipping cost'=>'Coste de envío','Other'=>'Otros','Supplier / stock'=>'Proveedor / stock','%1$s (%2$s × %3$d order)'=>'%1$s (%2$s × %3$d pedido)' . "\0" . '%1$s (%2$s × %3$d pedidos)','Gross sales'=>'Ventas brutas','Returns'=>'Devoluciones','Coupons (already in totals)'=>'Cupones (ya incluidos en los totales)','Includes %s tax'=>'Incluye %s de impuestos','%s of revenue'=>'%s de los ingresos','Processing fees on %s order are in a currency with no exchange rate, so they are not counted. Add a rate to include them.'=>'Las comisiones de %s pedido están en una moneda sin tipo de cambio, así que no se cuentan. Añade un tipo para incluirlas.' . "\0" . 'Las comisiones de %s pedidos están en una moneda sin tipo de cambio, así que no se cuentan. Añade un tipo para incluirlas.','%s order has no payment fee recorded, so processing costs are only counted on the rest.'=>'%s pedido no tiene registrada ninguna comisión de pago, así que los costes de procesamiento solo se cuentan en el resto.' . "\0" . '%s pedidos no tienen registrada ninguna comisión de pago, así que los costes de procesamiento solo se cuentan en el resto.','Payment fees are turned on, but none of the orders in this period record a processing fee. Your payment gateway may not store one, so this cost is not included.'=>'Las comisiones de pago están activadas, pero ningún pedido de este periodo registra una comisión de procesamiento. Puede que tu pasarela de pago no la guarde, así que este coste no se incluye.','Cost missing on %s item, profit overstated'=>'Falta el coste de %s artículo, beneficio sobrestimado' . "\0" . 'Falta el coste de %s artículos, beneficio sobrestimado','%s sold item has no cost set. Add its “Cost of goods” so Net profit is accurate.'=>'%s artículo vendido no tiene coste. Añade su “Coste de mercancía” para que el beneficio neto sea exacto.' . "\0" . '%s artículos vendidos no tienen coste. Añade su “Coste de mercancía” para que el beneficio neto sea exacto.','%s product is missing a cost'=>'A %s producto le falta el coste' . "\0" . 'A %s productos les falta el coste','date range separator to '=>' a ','%d day'=>'%d día' . "\0" . '%d días','%s item sold'=>'%s artículo vendido' . "\0" . '%s artículos vendidos','Guest'=>'Invitado','%s item'=>'%s artículo' . "\0" . '%s artículos','Organic'=>'Orgánico','Referral'=>'Referido','Campaign'=>'Campaña','Direct'=>'Directo','You do not have permission to export dashboard data.'=>'No tienes permiso para exportar datos del dashboard.','Export engine unavailable on this server.'=>'El motor de exportación no está disponible en este servidor.','New'=>'Nuevo','Includes tax'=>'Impuestos incluidos','Net of returns and tax'=>'Neto de devoluciones e impuestos','Excluding tax'=>'Sin impuestos','Net of returns'=>'Neto de devoluciones','Same as total sales'=>'Igual que ventas totales','BrikPanel report'=>'Informe de BrikPanel','Website'=>'Sitio web','Report period'=>'Periodo del informe','Duration'=>'Duración','Generated'=>'Generado','Key metrics'=>'Métricas clave','Metric'=>'Métrica','Value'=>'Valor','Change vs previous period'=>'Cambio vs periodo anterior','Items sold'=>'Artículos vendidos','Conversion rate (%)'=>'Tasa de conversión (%)','Profit'=>'Beneficio','Amount (%s)'=>'Importe (%s)','Context'=>'Contexto','Taken out of Revenue'=>'Restado de los ingresos','In Revenue, taken off Net profit'=>'Incluidos en los ingresos, restados del beneficio neto','of which Shipping cost'=>'de los cuales coste de envío','Included in expenses'=>'Incluido en gastos','of which Cost per order'=>'de los cuales coste por pedido','of which Payment fees'=>'de los cuales comisiones de pago','%s margin'=>'%s de margen','Returns & refunds'=>'Devoluciones y reembolsos','Returned / refunded orders'=>'Pedidos devueltos / reembolsados','Total orders'=>'Pedidos totales','Return & refund rate (%)'=>'Tasa de devolución y reembolso (%)','Customer lifetime value (all-time)'=>'Valor de vida del cliente (histórico)','Top customer LTV'=>'LTV del mejor cliente','Repeat customers'=>'Clientes recurrentes','Repeat rate (%)'=>'Tasa de repetición (%)','Note: the Orders tab lists every order placed in this period (all statuses). The “Orders” metric above counts paid orders only (processing + completed).'=>'Nota: la pestaña Pedidos lista todos los pedidos realizados en este periodo (todos los estados). La métrica «Pedidos» de arriba solo cuenta los pedidos pagados (en proceso + completados).','Stage'=>'Etapa','Count'=>'Cantidad','% of visitors'=>'% de visitantes','Add to cart'=>'Añadir al carrito','Share (%)'=>'Cuota (%)','Successful'=>'Exitoso','Failed'=>'Fallido','Device'=>'Dispositivo','Desktop'=>'Escritorio','Mobile'=>'Móvil','Tablet'=>'Tablet','Total'=>'Total','New vs Repeat (this period)'=>'Nuevos vs recurrentes (este periodo)','New customers'=>'Nuevos clientes','RFM segments (all-time)'=>'Segmentos RFM (histórico)','Customer metrics will appear after the nightly recompute.'=>'Las métricas de clientes aparecerán tras el recálculo nocturno.','Qty sold'=>'Cantidad vendida','No data for this period'=>'Sin datos para este periodo','Views'=>'Visualizaciones','Cart adds'=>'Añadidos al carrito','Revenue (%s)'=>'Ingresos (%s)','Country'=>'País','City'=>'Ciudad','Remaining'=>'Restante','Order #'=>'Pedido #','Total (%s)'=>'Total (%s)','No orders in this period'=>'Sin pedidos en este periodo','Summary'=>'Resumen','Funnel'=>'Embudo','Order status'=>'Estado del pedido','Devices'=>'Dispositivos','Most viewed'=>'Más vistos','Countries'=>'Países','Cities'=>'Ciudades','Orders (%d)'=>'Pedidos (%d)','Could not generate the Excel file. Please try again.'=>'No se pudo generar el archivo Excel. Inténtalo de nuevo.','Sidebar show/hide button'=>'Botón para mostrar/ocultar la barra lateral','Logo &amp; store name'=>'Logotipo y nombre de la tienda','Live visitors counter'=>'Contador de visitantes en vivo','Search bar'=>'Barra de búsqueda','Quick create button'=>'Botón de creación rápida','Hidden notices bell'=>'Campana de avisos ocultos','View store button'=>'Botón de ver tienda','Custom shortcut button'=>'Botón de acceso directo personalizado','User menu'=>'Menú de usuario','Added by a plugin'=>'Añadido por un plugin','Who can see this control'=>'Quién puede ver este control','Items in the create menu'=>'Elementos del menú de creación','Set a label and a target, then turn the button on above. The button stays hidden until both are filled in.'=>'Define una etiqueta y un destino, y después activa el botón arriba. El botón permanece oculto hasta que ambos estén rellenos.','Button label'=>'Etiqueta del botón','All orders'=>'Todos los pedidos','Button link'=>'Enlace del botón','Operational Expenses'=>'Gastos operativos','Payment fees are now counted as an expense.'=>'Las comisiones de pago ahora se cuentan como gasto.','Payment fees are no longer counted as an expense.'=>'Las comisiones de pago ya no se cuentan como gasto.','Track your operational costs to calculate net profit accurately.'=>'Registra tus costes operativos para calcular el beneficio neto con precisión.','Count the processing fee your payment provider charged on each order as an expense. The amount is read from the order itself, so no estimate is needed. It works with gateways that record their fee on the order, including Stripe, PayPal and WooPayments. Gateways that store no fee, and orders paid by bank transfer or cash, simply have none.'=>'Cuenta como gasto la comisión que tu proveedor de pagos cobró en cada pedido. El importe se lee del propio pedido, así que no hace falta estimarlo. Funciona con pasarelas que guardan su comisión en el pedido, como Stripe, PayPal y WooPayments. Las pasarelas que no guardan comisión y los pedidos pagados por transferencia o en efectivo simplemente no tienen.','Count payment fees as an expense'=>'Contar las comisiones de pago como gasto','Total (filtered)'=>'Total (filtrado)','All titles'=>'Todos los títulos','Apply'=>'Aplicar','Recurring'=>'Recurrente','money value of an expenseAmount'=>'Importe','Charged once for every matching order in the period you are viewing.'=>'Se cobra una vez por cada pedido que cumpla la condición en el periodo que estás viendo.','Optional notes…'=>'Notas opcionales…','Delete this expense?'=>'¿Eliminar este gasto?','Delete this expense and everything filed under it?'=>'¿Eliminar este gasto y todo lo que está archivado debajo?','Other costs are filed under this one, so it cannot go under another.'=>'Hay otros costes archivados debajo de este, así que no puede ir debajo de otro.','Part of %s'=>'Forma parte de %s','No expenses found.'=>'No se encontraron gastos.','Edit expense'=>'Editar gasto','Ongoing'=>'En curso','Edit'=>'Editar','Shipping class (removed)'=>'Clase de envío (eliminada)','You have a percentage-based cost below. If it was your estimate of card commission, it is now being deducted on top of the real fees. Delete or edit it to avoid counting the same cost twice.'=>'Tienes abajo un coste basado en porcentaje. Si era tu estimación de la comisión de tarjeta, ahora se está restando además de las comisiones reales. Elimínalo o edítalo para no contar el mismo coste dos veces.','%s / order'=>'%s / pedido','That shipping class no longer exists. Pick another one.'=>'Esa clase de envío ya no existe. Elige otra.','Required fields missing.'=>'Faltan campos obligatorios.','Amount must be a positive number.'=>'El importe debe ser un número positivo.','A percentage must be between 0 and 100.'=>'Un porcentaje debe estar entre 0 y 100.','Pick an expense you already have, or leave this empty.'=>'Elige un gasto que ya tengas o deja esto vacío.','An expense cannot be filed under itself.'=>'Un gasto no puede archivarse debajo de sí mismo.','Database error.'=>'Error de base de datos.','Invalid ID.'=>'ID no válido.','These figures changed while this dialog was open. Close it and try again.'=>'Estas cifras cambiaron mientras esta ventana estaba abierta. Ciérrela e inténtelo de nuevo.','Nothing to remove here.'=>'Aquí no hay nada que eliminar.','%d entry removed.'=>'%d entrada eliminada.' . "\0" . '%d entradas eliminadas.','This expense no longer exists.'=>'Este gasto ya no existe.','Commission'=>'Comisión','%1$s: %2$s of revenue.'=>'%1$s: %2$s de los ingresos.','This cost is a percentage of revenue, so removing it affects every period.'=>'Este coste es un porcentaje de los ingresos, por lo que eliminarlo afecta a todos los periodos.','%1$s: %2$s on every order you shipped free.'=>'%1$s: %2$s en cada pedido que enviaste gratis.','%1$s: %2$s on every order containing a %3$s item.'=>'%1$s: %2$s en cada pedido que contenga un artículo de %3$s.','%1$s: %2$s on every order.'=>'%1$s: %2$s en cada pedido.','This cost is charged per order, so removing it affects every period.'=>'Este coste se cobra por pedido, así que quitarlo afecta a todos los periodos.','Invalid date range.'=>'Intervalo de fechas no válido.','Removes %1$d entry · %2$s'=>'Elimina %1$d entrada · %2$s' . "\0" . 'Elimina %1$d entradas · %2$s','Only this period'=>'Solo este periodo','Includes %d entry outside this period.'=>'Incluye %d entrada fuera de este periodo.' . "\0" . 'Incluye %d entradas fuera de este periodo.','The whole repeating expense'=>'Todo el gasto recurrente','%1$s · %2$s · %3$s'=>'%1$s · %2$s · %3$s','Remove these expenses?'=>'¿Eliminar estos gastos?','%1$s: %2$d entry, %3$s in this period.'=>'%1$s: %2$d entrada, %3$s en este periodo.' . "\0" . '%1$s: %2$d entradas, %3$s en este periodo.','This period is where %s starts repeating. "Only this period" keeps that first entry. Choose the whole repeating expense to remove it as well.'=>'En este periodo empieza a repetirse %s. "Solo este periodo" conserva esa primera entrada. Elija todo el gasto recurrente para eliminarla también.','%s repeats, so removing it also stops every future occurrence.'=>'%s se repite, por lo que eliminarlo también detiene todas las repeticiones futuras.','These entries were created when stock orders were received. Removing them does not change the purchase orders.'=>'Estas entradas se crearon al recibir pedidos de stock. Eliminarlas no modifica los pedidos de compra.','Nothing, a cost on its own'=>'Nada, un coste independiente','Store costs'=>'Costes de la tienda','Google Sheets integration'=>'Integración con Google Sheets','Sync your orders, customers, and analytics straight to Google Sheets. Turn it off below to hide the admin page and stop all background sync jobs. Your connection and per-flow settings stay saved, so turning it back on restores everything.'=>'Sincroniza tus pedidos, clientes y analíticas directamente a Google Sheets. Desactívalo abajo para ocultar la página de administración y detener todos los trabajos de sincronización en segundo plano. Tu conexión y los ajustes por flujo permanecen guardados, así que volver a activarlo lo restaura todo.','Enable Google Sheets integration'=>'Activar integración con Google Sheets','When on, the Google Sheets admin menu, sync flows and AJAX endpoints are active. When off, the entire module is dormant: no menu item, no scheduled jobs, no order-write listeners.'=>'Cuando está activado, el menú de Google Sheets, los flujos de sincronización y los endpoints AJAX están activos. Cuando está desactivado, todo el módulo permanece inactivo: sin elemento de menú, sin trabajos programados, sin escuchadores de escritura de pedidos.','The BrikPanel service that renews your Google session is temporarily unreachable, so this sync was skipped. Your connection is still in place. It will resume on its own, or you can click Sync now again in a few minutes.'=>'El servicio de BrikPanel que renueva tu sesión de Google no está disponible temporalmente, así que se omitió esta sincronización. Tu conexión sigue activa. Se reanudará sola, o puedes pulsar «Sincronizar ahora» de nuevo en unos minutos.','Not connected to Google Sheets.'=>'No conectado a Google Sheets.','Request to Google Sheets failed after retries.'=>'La solicitud a Google Sheets falló tras los reintentos.','Sheets: customers + RFM snapshot'=>'Sheets: instantánea de clientes + RFM','Sheets: push expenses to Google Sheets'=>'Sheets: enviar gastos a Google Sheets','Sheets: pull expenses from Google Sheets'=>'Sheets: traer gastos desde Google Sheets','Order number'=>'Número de pedido','Order date'=>'Fecha del pedido','Subtotal'=>'Subtotal','Tax total'=>'Total impuestos','Shipping total'=>'Total envío','Discount total'=>'Total descuento','Order total'=>'Total del pedido','Payment method (key)'=>'Método de pago (clave)','Payment method'=>'Método de pago','Transaction ID'=>'ID de transacción','Coupon codes'=>'Códigos de cupón','Customer note'=>'Nota del cliente','Customer user ID'=>'ID de usuario del cliente','Shipping method'=>'Método de envío','Order COGS total'=>'Total de COGS del pedido','Billing first name'=>'Nombre de facturación','Billing last name'=>'Apellidos de facturación','Billing email'=>'Email de facturación','Billing phone'=>'Teléfono de facturación','Billing address 1'=>'Dirección de facturación 1','Billing address 2'=>'Dirección de facturación 2','Billing city'=>'Ciudad de facturación','Billing state'=>'Provincia de facturación','Billing postcode'=>'Código postal de facturación','Billing country'=>'País de facturación','Shipping first name'=>'Nombre de envío','Shipping last name'=>'Apellidos de envío','Shipping address 1'=>'Dirección de envío 1','Shipping address 2'=>'Dirección de envío 2','Shipping city'=>'Ciudad de envío','Shipping state'=>'Provincia de envío','Shipping postcode'=>'Código postal de envío','Shipping country'=>'País de envío','Line item ID'=>'ID de línea','Variation ID'=>'ID de la variación','Product name'=>'Nombre del producto','Variation attributes'=>'Atributos de la variación','Quantity'=>'Cantidad','Unit price'=>'Precio unitario','Line subtotal'=>'Subtotal de línea','Line tax'=>'Impuestos de línea','Line total'=>'Total de línea','Line COGS (cost × qty)'=>'COGS de línea (coste × cantidad)','Parent ID'=>'ID superior','Short description'=>'Descripción corta','Price'=>'Precio','Regular price'=>'Precio regular','Sale price'=>'Precio de oferta','Cost (COGS)'=>'Coste (COGS)','Stock'=>'Stock','Stock status'=>'Estado del stock','Permalink'=>'Enlace permanente','Customer key'=>'Clave de cliente','First order date'=>'Fecha del primer pedido','Last order date'=>'Fecha del último pedido','Total spent'=>'Total gastado','Recency score (R)'=>'Puntuación de recencia (R)','Frequency score (F)'=>'Puntuación de frecuencia (F)','Monetary score (M)'=>'Puntuación monetaria (M)','RFM segment'=>'Segmento RFM','Expense ID'=>'ID del gasto','Added on'=>'Añadido el','Custom field'=>'Campo personalizado','Almost there: Google did not grant access to your spreadsheets. On the Google permission screen, please keep the "See, edit, create and delete only the specific Google Drive files you use with this app" box checked, then connect again.'=>'Casi: Google no concedió acceso a tus hojas de cálculo. En la pantalla de permisos de Google, mantén marcada la casilla "Ver, editar, crear y eliminar solo los archivos específicos de Google Drive que uses con esta app", luego vuelve a conectar.','Google Sheets connected.'=>'Google Sheets conectado.','Sheets: flush new orders to Google Sheets'=>'Sheets: enviar nuevos pedidos a Google Sheets','Sheets: scheduled bulk order export'=>'Sheets: exportación masiva programada de pedidos','Sheets: update changed-status order rows'=>'Sheets: actualizar filas de pedidos con cambio de estado','Sheets: pull order status changes from Google Sheets'=>'Sheets: traer cambios de estado de pedidos desde Google Sheets','Status changed via Google Sheets sync.'=>'Estado cambiado mediante la sincronización de Google Sheets.','Sheets: push product changes to Google Sheets'=>'Sheets: enviar cambios de productos a Google Sheets','Sheets: pull product changes from Google Sheets'=>'Sheets: traer cambios de productos desde Google Sheets','Sheets: reports snapshot'=>'Sheets: instantánea de informes','Window'=>'Ventana','Successful orders'=>'Pedidos exitosos','Conversion rate %'=>'Tasa de conversión %','COGS %'=>'COGS %','Ad spend'=>'Gasto publicitario','Per-order costs'=>'Costes por pedido','Other expenses'=>'Otros gastos','Total expenses'=>'Gastos totales','Expenses %'=>'Gastos %','Net margin %'=>'Margen neto %','Conversion %'=>'Conversión %','Units sold'=>'Unidades vendidas','Checkout started'=>'Pago iniciado','Google Sheets'=>'Google Sheets','Connecting to Google…'=>'Conectando con Google…','Disconnect from Google Sheets?'=>'¿Desconectar de Google Sheets?','Sync queued. Check back in a moment.'=>'Sincronización en cola. Vuelve en un momento.','Spreadsheet created.'=>'Hoja de cálculo creada.','Creating spreadsheet…'=>'Creando hoja de cálculo…','Validating…'=>'Validando…','Spreadsheet is reachable.'=>'La hoja de cálculo es accesible.','Opening Google Picker…'=>'Abriendo Google Picker…','Could not open the Google Picker. Please try again.'=>'No se pudo abrir Google Picker. Inténtalo de nuevo.','Picking an existing spreadsheet is not available yet. Create a new one below.'=>'Aún no está disponible elegir una hoja de cálculo existente. Crea una nueva debajo.','The server ended the request before it finished. Nothing was lost: click Sync now again to continue where it stopped.'=>'El servidor terminó la petición antes de completarla. No se ha perdido nada: pulsa «Sincronizar ahora» otra vez para continuar donde se detuvo.','Syncing… Orders: %1$s, rows: %2$s'=>'Sincronizando… Pedidos: %1$s, filas: %2$s','Sync finished. Orders: %1$s, rows: %2$s.'=>'Sincronización terminada. Pedidos: %1$s, filas: %2$s.','Syncing… Product rows: %1$s'=>'Sincronizando… Filas de productos: %1$s','Sync finished. Product rows: %1$s.'=>'Sincronización terminada. Filas de productos: %1$s.','BrikPanel does not have access yet. Open the spreadsheet, share it with %s, then click Validate.'=>'BrikPanel aún no tiene acceso. Abre la hoja de cálculo, compártela con %s y haz clic en Validar.','No errors logged.'=>'No se han registrado errores.','Orders with no shipping method recorded are excluded while any box is ticked. Untick every box to export all orders.'=>'Los pedidos sin método de envío registrado quedan excluidos mientras haya alguna casilla marcada. Desmarca todas las casillas para exportar todos los pedidos.','No orders match this shipping filter, so nothing would be exported. Untick every box to export all orders.'=>'Ningún pedido coincide con este filtro de envío, así que no se exportaría nada. Desmarca todas las casillas para exportar todos los pedidos.','Counting…'=>'Contando…','This will WIPE the current target tab in Google Sheets and then re-push every order from scratch. Any rows you added manually to that tab will be lost. Continue?'=>'Esto BORRARÁ la pestaña destino actual en Google Sheets y volverá a enviar todos los pedidos desde cero. Se perderá cualquier fila añadida manualmente a esa pestaña. ¿Continuar?','Resetting…'=>'Restableciendo…','in %s minute (auto-refreshed)'=>'en %s minuto (se renueva automáticamente)' . "\0" . 'en %s minutos (se renueva automáticamente)','Pulling changes from Sheets…'=>'Obteniendo cambios desde Sheets…','This will WIPE the current Products tab in Google Sheets and then re-push every product from scratch. Any rows you added manually to that tab will be lost. Continue?'=>'Esto BORRARÁ la pestaña de Productos actual en Google Sheets y volverá a enviar todos los productos desde cero. Cualquier fila añadida manualmente se perderá. ¿Continuar?','This will WIPE the current Expenses tab in Google Sheets and then re-write it from your BrikPanel expenses. Any rows you typed into that tab and have not pulled in yet will be lost. Continue?'=>'Esto BORRARÁ la pestaña "Gastos" actual en Google Sheets y la reescribirá a partir de sus gastos de BrikPanel. Las filas que haya escrito ahí y todavía no se hayan importado se perderán. ¿Continuar?','Connect Google Sheets first.'=>'Conecta primero Google Sheets.','Google Drive access was not granted for this connection. Please disconnect and reconnect, keeping the Google Drive permission checked on the consent screen.'=>'No se concedió acceso a Google Drive para esta conexión. Desconecta y vuelve a conectar, manteniendo marcado el permiso de Google Drive en la pantalla de consentimiento.','Picking an existing spreadsheet is not available yet. Create a new BrikPanel spreadsheet instead.'=>'Aún no está disponible elegir una hoja de cálculo existente. Crea una nueva hoja de cálculo de BrikPanel.','Google session expired. Re-authorize and try again.'=>'La sesión de Google ha caducado. Vuelve a autorizar e inténtalo de nuevo.','Could not parse a spreadsheet ID from that input.'=>'No se pudo extraer un ID de hoja de cálculo de esa entrada.','BrikPanel can only use spreadsheets you create here or hand over with the “Choose existing spreadsheet” picker. Use the picker to grant access to this file.'=>'BrikPanel solo puede usar hojas de cálculo que crees aquí o que entregues con el selector «Elegir hoja de cálculo existente». Usa el selector para conceder acceso a este archivo.','Spreadsheet not found. Check the URL.'=>'Hoja de cálculo no encontrada. Comprueba la URL.','Spreadsheet created but no ID returned.'=>'Hoja de cálculo creada pero no se devolvió ningún ID.','Invalid "include orders from" date. Use the date picker.'=>'Fecha "incluir pedidos desde" no válida. Usa el selector de fechas.','Row layout was not changed: the target tab could not be wiped (rate limit or connection issue). Your other settings were saved. Wait a minute and try the layout switch again.'=>'El diseño de filas no se ha cambiado: no se pudo vaciar la pestaña de destino (límite de peticiones o problema de conexión). Tus otros ajustes se han guardado. Espera un minuto y vuelve a intentar el cambio de diseño.','Row layout changed. The target tab was wiped and all orders will re-export in the new layout. Click "Sync now" to fill it.'=>'Diseño de filas cambiado. La pestaña de destino se ha vaciado y todos los pedidos se volverán a exportar con el nuevo diseño. Pulsa «Sincronizar ahora» para rellenarla.','Unknown settings group.'=>'Grupo de ajustes desconocido.','Unknown flow.'=>'Flujo desconocido.','All %s order in this date and status range will be exported.'=>'Se exportará %s pedido de este rango de fechas y estados.' . "\0" . 'Se exportarán los %s pedidos de este rango de fechas y estados.','%1$s of %2$s orders matches this shipping filter.'=>'%1$s de %2$s pedidos coincide con este filtro de envío.' . "\0" . '%1$s de %2$s pedidos coinciden con este filtro de envío.','Pick or create a target spreadsheet first.'=>'Elige o crea primero una hoja de cálculo de destino.','Enable this sync first, then click Save before clicking Sync now.'=>'Activa primero esta sincronización, luego haz clic en Guardar antes de hacer clic en Sincronizar ahora.','A background sync is already running. It will finish on its own, or click "Sync now" again in a moment to watch progress.'=>'Ya hay una sincronización en segundo plano en marcha. Terminará por sí sola, o pulsa «Sincronizar ahora» otra vez en un momento para ver el progreso.','No orders matched the selected status filters and "include orders from" date. Adjust those settings and try again.'=>'Ningún pedido coincide con los filtros de estado seleccionados y la fecha "incluir pedidos desde". Ajusta esos parámetros e inténtalo de nuevo.','No new orders to sync. Every matching order is already marked synced. To wipe the target tab and re-push the full history, click "Reset & re-push everything".'=>'No hay pedidos nuevos que sincronizar. Todos los pedidos coincidentes ya están marcados como sincronizados. Para vaciar la pestaña de destino y volver a enviar todo el historial, haz clic en «Restablecer y volver a enviar todo».','Synced %2$d order (%1$d rows).'=>'Sincronizado %2$d pedido (%1$d filas).' . "\0" . 'Sincronizados %2$d pedidos (%1$d filas).','More running in background…'=>'Más en ejecución en segundo plano…','The target tab could not be wiped, so nothing was re-pushed and your existing rows were left untouched. This is usually a Google rate limit, wait a minute and click "Sync now" again.'=>'No se ha podido vaciar la pestaña de destino, así que no se ha vuelto a enviar nada y tus filas existentes se han dejado intactas. Suele ser un límite de peticiones de Google: espera un minuto y pulsa «Sincronizar ahora» otra vez.','Pushed %1$d new and updated %2$d existing product rows.'=>'Se enviaron %1$d filas nuevas y se actualizaron %2$d existentes.','Refreshed %2$d report tabs (%1$d rows).'=>'Actualizadas %2$d pestañas de informe (%1$d filas).','Synced %d customer.'=>'%d cliente sincronizado.' . "\0" . '%d clientes sincronizados.','Wrote %d expense to the sheet.'=>'Se ha escrito %d gasto en la hoja.' . "\0" . 'Se han escrito %d gastos en la hoja.','Added %1$d and updated %2$d from your edits in the sheet.'=>'Se han añadido %1$d y actualizado %2$d a partir de sus cambios en la hoja.','%1$s ago, %2$d rows'=>'hace %1$s, %2$d filas','Enable two-way sync for orders first, then click Save before clicking Pull now.'=>'Activa primero la sincronización bidireccional para pedidos, haz clic en Guardar y luego en «Obtener ahora».','Checked %1$d order rows. Applied %2$d status changes from Sheets, %3$d conflicts skipped.'=>'Se comprobaron %1$d filas de pedidos. Se aplicaron %2$d cambios de estado desde Sheets, %3$d conflictos omitidos.','Enable two-way sync for products first, then click Save before clicking Pull now.'=>'Activa primero la sincronización bidireccional para productos, haz clic en Guardar y luego en «Obtener ahora».','Checked %1$d product rows. Applied %2$d changes from Sheets, %3$d conflicts skipped.'=>'Se comprobaron %1$d filas de productos. Se aplicaron %2$d cambios desde Sheets, %3$d conflictos omitidos.','Enable two-way sync for expenses first, then click Save before clicking Pull now.'=>'Active primero la sincronización en dos sentidos para los gastos y pulse Guardar antes de usar "Traer ahora".','Read %1$d rows: added %2$d, updated %3$d, skipped %4$d.'=>'Se han leído %1$d filas: %2$d añadidas, %3$d actualizadas, %4$d omitidas.','%d row was changed in both places, so the BrikPanel version was kept.'=>'%d fila se cambió en los dos sitios, así que se ha conservado la versión de BrikPanel.' . "\0" . '%d filas se cambiaron en los dos sitios, así que se han conservado las versiones de BrikPanel.','%1$s (repeated %2$s times)'=>'%1$s (repetido %2$s veces)','The target tab could not be wiped (rate limit or connection issue), so the reset was cancelled to avoid duplicate rows. Nothing was changed. Wait a minute and try again.'=>'No se pudo vaciar la pestaña de destino (límite de peticiones o problema de conexión), así que el restablecimiento se canceló para evitar filas duplicadas. No se ha cambiado nada. Espera un minuto e inténtalo de nuevo.','Sync state cleared and target tab wiped. Click "Sync now" to repopulate it.'=>'Estado de sincronización borrado y pestaña destino limpiada. Haz clic en "Sincronizar ahora" para repoblarla.','Two-way columns'=>'Columnas bidireccionales','Edits you make in the sheet are written back to your store for these columns only: %s.'=>'Las ediciones que hagas en la hoja se escriben de vuelta en tu tienda solo para estas columnas: %s.','Every other column is one-way (store to sheet). Anything you type into those cells is display-only and will be overwritten on the next sync. Columns that sync back are marked with this glyph in the sheet header.'=>'Las demás columnas son unidireccionales (de la tienda a la hoja). Cualquier cosa que escribas en esas celdas es solo de visualización y se sobrescribirá en la próxima sincronización. Las columnas que se sincronizan de vuelta se marcan con este símbolo en el encabezado de la hoja.','Two-way sync is currently turned off, so edits in the sheet are not written back yet. Turn on "Two-way sync: apply status changes from Sheets" below and save to enable it.'=>'La sincronización bidireccional está desactivada, por lo que los cambios en la hoja aún no se escriben en la tienda. Activa "Sincronización bidireccional: aplicar cambios de estado desde Sheets" abajo y guarda para habilitarla.','Two-way sync is currently turned off, so edits in the sheet are not written back yet. Turn on the two-way sync option below and save to enable it.'=>'La sincronización bidireccional está desactivada, por lo que los cambios en la hoja aún no se escriben en la tienda. Activa la opción de sincronización bidireccional abajo y guarda para habilitarla.','Edits to this column sync back to your store'=>'Las ediciones de esta columna se sincronizan de vuelta a tu tienda','two-way'=>'bidireccional','Show more columns'=>'Mostrar más columnas','Custom checkout / order fields'=>'Campos personalizados de pago / pedido','Save columns'=>'Guardar columnas','View error log'=>'Ver registro de errores','Send your orders, customers, and analytics straight to a Google Sheet.'=>'Envía tus pedidos, clientes y analíticas directamente a una hoja de Google.','Connection'=>'Conexión','Reports'=>'Informes','Connect your Google account'=>'Conecta tu cuenta de Google','BrikPanel uses a single, narrow Google permission: no app verification screen, no scary “unverified app” warning. It can only touch a spreadsheet it creates for you or one you explicitly hand over. The rest of your Google Drive stays invisible to BrikPanel.'=>'BrikPanel usa un único permiso de Google muy limitado: sin pantalla de verificación de la app ni la temida advertencia de «app no verificada». Solo puede tocar una hoja de cálculo que cree para ti o una que le entregues expresamente. El resto de tu Google Drive sigue invisible para BrikPanel.','Drive (per-file): create a new spreadsheet, or open only the one you pick'=>'Drive (por archivo): crear una hoja de cálculo nueva o abrir solo la que elijas','Email: to display which Google account is connected'=>'Correo electrónico: para mostrar qué cuenta de Google está conectada','Connect Google Sheets'=>'Conectar Google Sheets','Google Drive access is missing.'=>'Falta el acceso a Google Drive.','Your account is connected, but the Google Drive permission was not granted, so creating or choosing a spreadsheet will fail. Click Disconnect, then connect again and keep the Google Drive checkbox ticked on the permission screen.'=>'Tu cuenta está conectada, pero no se concedió el permiso de Google Drive, así que crear o elegir una hoja de cálculo fallará. Haz clic en Desconectar, luego vuelve a conectar y mantén marcada la casilla de Google Drive en la pantalla de permisos.','Token expires'=>'El token caduca','unknown'=>'desconocido','Target spreadsheet'=>'Hoja de cálculo de destino','One spreadsheet is used for every flow. Each flow writes to its own tab inside it.'=>'Se usa una sola hoja de cálculo para cada flujo. Cada flujo escribe en su propia pestaña dentro de ella.','Open in Google Sheets ↗'=>'Abrir en Google Sheets ↗','Use an existing spreadsheet'=>'Usar una hoja de cálculo existente','Pick one of your Google spreadsheets. You only ever grant BrikPanel access to the single file you choose.'=>'Elige una de tus hojas de cálculo de Google. Solo concedes a BrikPanel acceso al único archivo que elijas.','Choose existing spreadsheet'=>'Elegir hoja de cálculo existente','or'=>'o','Create a new spreadsheet for BrikPanel'=>'Crear una nueva hoja de cálculo para BrikPanel','BrikPanel · %s'=>'BrikPanel · %s','Order sync'=>'Sincronización de pedidos','Push WooCommerce orders to a tab. Each row is one line item; variations get their own row with attribute columns.'=>'Envía los pedidos de WooCommerce a una pestaña. Cada fila es una línea de pedido; las variaciones tienen su propia fila con columnas de atributos.','Enable order sync'=>'Activar sincronización de pedidos','Target tab name'=>'Nombre de la pestaña destino','Row layout'=>'Diseño de filas','One row per order (items combined in one cell)'=>'Una fila por pedido (artículos combinados en una celda)','One row per line item (detailed)'=>'Una fila por línea de pedido (detallado)','Changing the layout wipes the target tab and re-exports every order in the new format, so rows from the two layouts are never mixed.'=>'Cambiar el diseño vacía la pestaña de destino y vuelve a exportar todos los pedidos en el nuevo formato, así que las filas de los dos diseños nunca se mezclan.','Real-time append on new order'=>'Añadir en tiempo real al recibir un nuevo pedido','Bulk export schedule'=>'Calendario de exportación masiva','Manual only'=>'Solo manual','Hourly'=>'Cada hora','Every 4 hours'=>'Cada 4 horas','Daily'=>'Diaria','Bulk export: include orders from'=>'Exportación masiva: incluir pedidos desde','Statuses to export'=>'Estados a exportar','Shipping methods to export'=>'Métodos de envío a exportar','Leave every box unchecked to export orders regardless of shipping method. Pick one or more to export only orders that used those methods.'=>'Deja todas las casillas sin marcar para exportar los pedidos independientemente del método de envío. Elige uno o más para exportar solo los pedidos que usaron esos métodos.','Two-way sync: apply status changes from Sheets'=>'Sincronización bidireccional: aplicar cambios de estado desde Sheets','When on, BrikPanel polls the Orders tab and writes any order_status edits back to WooCommerce. Only the Order status column is read back; other edits are display-only and get overwritten on the next push.'=>'Cuando está activado, BrikPanel consulta la pestaña Pedidos y devuelve cualquier edición de order_status a WooCommerce. Solo se lee la columna Estado del pedido; otras ediciones son solo de visualización y se sobrescriben en el próximo envío.','Poll interval'=>'Intervalo de consulta','Every 2 minutes'=>'Cada 2 minutos','Every 5 minutes'=>'Cada 5 minutos','Every 15 minutes'=>'Cada 15 minutos','Read the Orders tab right now and apply any status changes back to WooCommerce.'=>'Leer ahora la pestaña Pedidos y aplicar los cambios de estado a WooCommerce.','Pull now'=>'Obtener ahora','Wipe the target tab in Google Sheets and re-push the full order history from scratch. Any manual edits in that tab will be lost.'=>'Borra la pestaña destino en Google Sheets y vuelve a enviar el historial completo de pedidos desde cero. Se perderán todas las ediciones manuales de esa pestaña.','Reset & re-push everything'=>'Restablecer y volver a enviar todo','Columns to export'=>'Columnas a exportar','Mandatory columns (Order ID, Line item ID) are always included so we can de-duplicate rows.'=>'Las columnas obligatorias (ID del pedido, ID de línea) siempre se incluyen para poder eliminar filas duplicadas.','Product sync'=>'Sincronización de productos','Push WooCommerce products and variations to a tab so you can review stock at a glance. Variations get their own row. Edits to the Stock column flow back to WooCommerce.'=>'Envía productos y variaciones de WooCommerce a una pestaña para revisar el stock de un vistazo. Las variaciones tienen su propia fila. Las ediciones en la columna Stock se devuelven a WooCommerce.','Enable product sync'=>'Activar sincronización de productos','Categories to sync'=>'Categorías a sincronizar','Leave every box unchecked to sync all products. Pick one or more categories to sync only those products and their variations. Sub-categories are included automatically.'=>'Deja todas las casillas sin marcar para sincronizar todos los productos. Elige una o más categorías para sincronizar solo esos productos y sus variaciones. Las subcategorías se incluyen automáticamente.','No product categories found yet.'=>'Aún no se han encontrado categorías de productos.','Changing the categories? After saving, click "Sync now". The tab is rebuilt from scratch to match the new selection, with no empty gaps.'=>'¿Vas a cambiar las categorías? Después de guardar, haz clic en «Sincronizar ahora». La pestaña se reconstruye desde cero para coincidir con la nueva selección, sin huecos vacíos.','Two-way sync: apply stock edits from Sheets'=>'Sincronización bidireccional: aplicar cambios de stock desde Sheets','When on, BrikPanel polls the Products tab and writes any Stock cell edits back to WooCommerce. Only the Stock column is read back; other edits (price, name, etc.) are display-only and get overwritten on the next push.'=>'Cuando está activado, BrikPanel consulta la pestaña Productos y devuelve a WooCommerce cualquier edición en la celda Stock. Solo se lee la columna Stock; otras ediciones (precio, nombre, etc.) son solo de visualización y se sobrescriben en el próximo envío.','Read the Products tab right now and apply any Stock changes back to WooCommerce.'=>'Leer ahora la pestaña Productos y aplicar los cambios de stock a WooCommerce.','Wipe the Products tab in Google Sheets and re-push every product from scratch. Any manual edits in that tab will be lost.'=>'Borra la pestaña Productos en Google Sheets y vuelve a enviar todos los productos desde cero. Cualquier edición manual en esa pestaña se perderá.','Product ID is mandatory so rows can be de-duplicated. Stock is the only column that flows back to WooCommerce.'=>'El ID de producto es obligatorio para deduplicar las filas. Stock es la única columna que vuelve a WooCommerce.','Reports sync'=>'Sincronización de informes','Push BrikPanel\'s computed analytics into dedicated tabs. Each push overwrites the tab so you always see \'as-of-last-sync\' values.'=>'Envía las analíticas calculadas de BrikPanel a pestañas dedicadas. Cada envío sobrescribe la pestaña, así siempre ves los valores «a fecha de la última sincronización».','Enable reports sync'=>'Activar sincronización de informes','Snapshot interval'=>'Intervalo de instantánea','Every 6 hours'=>'Cada 6 horas','multi-window revenue, orders, AOV, conversion.'=>'ingresos, pedidos, AOV y conversión en múltiples ventanas.','last 90 days, one row per day.'=>'últimos 90 días, una fila por día.','top 50 by units sold, last 90 days.'=>'top 50 por unidades vendidas, últimos 90 días.','daily visitor → checkout funnel.'=>'embudo diario de visitante → pago.','revenue, costs, expenses and net profit for the last 7, 30 and 90 days and all time.'=>'ingresos, costes, gastos y beneficio neto de los últimos 7, 30 y 90 días y de todo el periodo.','Customers sync'=>'Sincronización de clientes','Each customer\'s metrics + RFM segment, refreshed after BrikPanel\'s nightly recompute. Tab is overwritten on every sync.'=>'Las métricas de cada cliente + el segmento RFM, actualizados tras el recálculo nocturno de BrikPanel. La pestaña se sobrescribe en cada sincronización.','Enable customers sync'=>'Activar sincronización de clientes','Customer key and email are mandatory so rows can be de-duplicated.'=>'La clave del cliente y el email son obligatorios para poder eliminar filas duplicadas.','Expenses sync'=>'Sincronización de gastos','Manage your operational costs in a spreadsheet instead of adding them one at a time. Turn on two-way sync and any row you type into the tab becomes a real expense in BrikPanel, counted in your net profit.'=>'Gestione sus costes operativos en una hoja de cálculo en lugar de añadirlos uno a uno. Con la sincronización en dos sentidos activada, cada fila que escriba en la pestaña se convierte en un gasto real en BrikPanel y cuenta en su beneficio neto.','Enable expenses sync'=>'Activar la sincronización de gastos','Two-way sync: add and edit expenses from the sheet'=>'Sincronización en dos sentidos: añada y edite gastos desde la hoja','When on, BrikPanel reads the tab on a schedule. Leave the Expense ID cell empty on a new row and it is added as a new expense, then the ID is filled in for you. Change a cell on an existing row and that expense is updated.'=>'Cuando está activada, BrikPanel lee la pestaña periódicamente. Deje vacía la celda "ID del gasto" en una fila nueva y se añadirá como un gasto nuevo, rellenando el ID por usted. Si cambia una celda de una fila existente, ese gasto se actualiza.','The tab holds one row per expense you manage: every one-off cost, plus the first row of each repeating cost. The extra dated copies BrikPanel creates from a repeating cost are not listed, because they are rebuilt from that first row whenever you change it.'=>'La pestaña contiene una fila por cada gasto que usted gestiona: todos los gastos puntuales y la primera fila de cada gasto que se repite. Las copias con fecha que BrikPanel crea a partir de un gasto repetido no aparecen, porque se reconstruyen desde esa primera fila cada vez que la modifica.','Set Type to "Percentage of revenue" for costs like card commission. The Amount cell then holds the rate, so 2.9 means 2.9%.'=>'Ponga el Tipo en "Porcentaje de los ingresos" para costes como la comisión de tarjeta. La celda Importe contiene entonces la tasa, de modo que 2,9 significa 2,9 %.','Deleting a row from the sheet does not delete the expense, because an empty row cannot be told apart from one that has not loaded yet. Delete it on the Operational Expenses screen instead.'=>'Borrar una fila de la hoja no borra el gasto, porque una fila vacía no puede distinguirse de una que aún no se ha cargado. Bórrelo en la pantalla de Gastos operativos.','Read the Expenses tab right now and add or update the expenses in BrikPanel.'=>'Leer ahora la pestaña "Gastos" y añadir o actualizar los gastos en BrikPanel.','Wipe the Expenses tab in Google Sheets and re-write it from your BrikPanel expenses. Rows you typed there and have not pulled in yet will be lost.'=>'Borra la pestaña "Gastos" en Google Sheets y la reescribe a partir de sus gastos de BrikPanel. Las filas que escribió ahí y aún no se han importado se perderán.','Expense ID, Date, Title and Amount are always included: they are what an expense is, and BrikPanel needs them to match a row back to the right entry.'=>'ID del gasto, Fecha, Título e Importe se incluyen siempre: son lo que define un gasto, y BrikPanel los necesita para relacionar cada fila con la entrada correcta.','You do not have permission to export BrikPanel settings.'=>'No tienes permiso para exportar los ajustes de BrikPanel.','Could not encode BrikPanel settings as JSON.'=>'No se pudieron codificar los ajustes de BrikPanel como JSON.','You do not have permission to import BrikPanel settings.'=>'No tienes permiso para importar ajustes de BrikPanel.','%d setting applied.'=>'%d ajuste aplicado.' . "\0" . '%d ajustes aplicados.','%d setting cleared to its default.'=>'%d ajuste restablecido a su valor predeterminado.' . "\0" . '%d ajustes restablecidos a sus valores predeterminados.','%d unknown key skipped.'=>'%d clave desconocida omitida.' . "\0" . '%d claves desconocidas omitidas.','%d link repointed to this site.'=>'%d enlace redirigido a este sitio.' . "\0" . '%d enlaces redirigidos a este sitio.','Your saved column layouts were applied to your own account.'=>'Tus diseños de columnas guardados se han aplicado a tu propia cuenta.','This file lists only the settings that had been saved on the source site. Anything it does not mention was left as it is here.'=>'Este archivo solo incluye los ajustes que se habían guardado en el sitio de origen. Todo lo que no menciona se ha dejado tal como está aquí.','This file was made by an older BrikPanel and does not include: %s. Those settings were left as they are here.'=>'Este archivo se creó con una versión anterior de BrikPanel y no incluye: %s. Esos ajustes se han dejado tal como están aquí.','Pick a BrikPanel JSON file before clicking Import.'=>'Elige un archivo JSON de BrikPanel antes de hacer clic en Importar.','That file is too large to be a BrikPanel settings export.'=>'Ese archivo es demasiado grande para ser una exportación de ajustes de BrikPanel.','Could not read the uploaded file. Please try again.'=>'No se pudo leer el archivo subido. Inténtalo de nuevo.','That file is not a valid BrikPanel settings export.'=>'Ese archivo no es una exportación de ajustes de BrikPanel válida.','The uploaded file did not contain any BrikPanel settings.'=>'El archivo subido no contiene ningún ajuste de BrikPanel.','That file was made by a newer BrikPanel. Update this site first, then import it.'=>'Ese archivo se creó con una versión más reciente de BrikPanel. Actualiza primero este sitio y luego impórtalo.','Export settings'=>'Exportar ajustes','Download your BrikPanel configuration as a single JSON file, covering %s.'=>'Descarga tu configuración de BrikPanel en un solo archivo JSON, que abarca %s.','Download JSON file'=>'Descargar archivo JSON','Your own column layouts travel with the file and are applied to the account that imports it. Connection keys, media library picks and anything holding a user or page ID from this site stay behind, so the brand logo has to be picked again after importing.'=>'Tus propios diseños de columnas viajan con el archivo y se aplican a la cuenta que lo importa. Las claves de conexión, las imágenes de la biblioteca de medios y todo lo que contenga un ID de usuario o de página de este sitio se quedan aquí, así que el logotipo de marca hay que volver a elegirlo después de importar.','Import settings'=>'Importar ajustes','Upload a JSON file exported from BrikPanel. This site is made to match the one the file came from: settings it carries are overwritten, and settings the source site had left at their default are reset here too. Unknown keys are skipped.'=>'Sube un archivo JSON exportado desde BrikPanel. Este sitio se ajusta al sitio del que procede el archivo: los ajustes que incluye se sobrescriben y los ajustes que el sitio de origen tenía en su valor predeterminado también se restablecen aquí. Las claves desconocidas se omiten.','Drag a .json file here'=>'Arrastra un archivo .json aquí','or click to browse'=>'o haz clic para explorar','Tip: export first if you want a quick rollback path.'=>'Consejo: exporta primero si quieres una ruta rápida para revertir.','Logging in...'=>'Iniciando sesión...','Log In'=>'Iniciar sesión','An error occurred. Please try again.'=>'Ha ocurrido un error. Inténtalo de nuevo.','Reset your password'=>'Restablece tu contraseña','Choose a new password'=>'Elige una nueva contraseña','Create an account'=>'Crea una cuenta','Check your email'=>'Revisa tu correo electrónico','Confirm your action'=>'Confirma tu acción','Confirm your email address'=>'Confirma tu dirección de correo electrónico','Welcome back'=>'Bienvenido de nuevo','%s · Powered by WordPress'=>'%s · Funciona con WordPress','Security check failed. Please refresh the page.'=>'Fallo en la comprobación de seguridad. Actualiza la página.','Please enter both username and password.'=>'Introduce nombre de usuario y contraseña.','Unknown username or email address.'=>'Nombre de usuario o dirección de email desconocidos.','The password you entered is incorrect.'=>'La contraseña introducida es incorrecta.','Please enter a username or email address.'=>'Introduce un nombre de usuario o dirección de email.','Please enter your password.'=>'Introduce tu contraseña.','Login failed. Please try again.'=>'Error al iniciar sesión. Inténtalo de nuevo.','Login successful! Redirecting...'=>'¡Inicio de sesión exitoso! Redirigiendo...','Login page logo'=>'Logotipo de la página de acceso','The login page uses your brand logo. Set it under %s.'=>'La página de acceso usa el logotipo de tu marca. Configúralo en %s.','Security check failed. Please reload and try again.'=>'La comprobación de seguridad falló. Vuelve a cargar la página e inténtalo de nuevo.','You do not have permission to change this.'=>'No tienes permiso para cambiar esto.','BrikPanel is on for your account. Switch off to use the classic WordPress admin for yourself only.'=>'BrikPanel está activado para tu cuenta. Desactívalo para usar la administración clásica de WordPress solo para ti.','BrikPanel is on for the whole store. Switch off to use the classic WordPress admin.'=>'BrikPanel está activado para toda la tienda. Desactívalo para usar la administración clásica de WordPress.','BrikPanel on'=>'BrikPanel activado','BrikPanel off'=>'BrikPanel desactivado','Switch BrikPanel off for your account and use the classic WordPress admin'=>'Desactivar BrikPanel para mi cuenta y usar la administración clásica de WordPress','Switch the BrikPanel interface back on for your account'=>'Volver a activar la interfaz de BrikPanel para mi cuenta','Switch BrikPanel off and use the classic WordPress admin'=>'Desactivar BrikPanel y usar la administración clásica de WordPress','Switch the BrikPanel interface back on'=>'Volver a activar la interfaz de BrikPanel','Could not change the BrikPanel switch. Please try again.'=>'No se pudo cambiar el interruptor de BrikPanel. Inténtalo de nuevo.','Site management'=>'Gestión del sitio','Default link'=>'Enlace predeterminado','Home'=>'Inicio','Marketing'=>'Marketing','Payments'=>'Pagos','Credit card'=>'Tarjeta de crédito','Invoice'=>'Factura','Tools'=>'Herramientas','Plugins'=>'Plugins','Users'=>'Usuarios','Comments'=>'Comentarios','Media'=>'Medios','Pages'=>'Páginas','Posts'=>'Entradas','Form'=>'Formulario','Snippets'=>'Snippets','More'=>'Más','Sidebar navigation'=>'Navegación de la barra lateral','Drag to reorder, toggle visibility, move items between sections, or add custom links.'=>'Arrastra para reordenar, alternar visibilidad, mover elementos entre secciones o añadir enlaces personalizados.','Reset to defaults'=>'Restablecer a valores predeterminados','Item spacing'=>'Espaciado entre elementos','Spacing between menu items'=>'Espaciado entre los elementos del menú','Compact'=>'Compacto','Comfortable'=>'Cómodo','Spacious'=>'Amplio','Sets the vertical gap between every sidebar item.'=>'Define el espacio vertical entre todos los elementos de la barra lateral.','Section heading label'=>'Etiqueta del encabezado de sección','Label for the Site management heading'=>'Etiqueta del encabezado Gestión del sitio','Rename the “Site management” heading that separates your store items from the rest. Leave blank to keep the default.'=>'Cambia el nombre del encabezado «Gestión del sitio» que separa los elementos de tu tienda del resto. Déjalo en blanco para mantener el predeterminado.','Who can see this item'=>'Quién puede ver este elemento','Spacer'=>'Separador','Spacer style'=>'Estilo del separador','Blank space'=>'Espacio en blanco','Divider line'=>'Línea divisoria','Remove spacer'=>'Quitar el separador','Heading'=>'Encabezado','e.g. Site content'=>'p. ej., Contenido del sitio','Heading text'=>'Texto del encabezado','Remove heading'=>'Quitar encabezado','This menu item does not exist on this site. It was most likely imported from another site, or the plugin that added it is no longer active.'=>'Este elemento de menú no existe en este sitio. Lo más probable es que se importara de otro sitio o que el plugin que lo añadió ya no esté activo.','Newly detected, not yet reviewed'=>'Recién detectado, aún sin revisar','Not available on this site'=>'No disponible en este sitio','Nothing on this site matches this item. Removing it is safe.'=>'Nada de este sitio coincide con este elemento. Es seguro quitarlo.','Visible in sidebar'=>'Visible en la barra lateral','Edit link'=>'Editar enlace','Delete link'=>'Eliminar enlace','Remove this menu item'=>'Quitar este elemento de menú','Rename or change icon'=>'Renombrar o cambiar icono','Manage submenu items'=>'Gestionar elementos de submenú','Submenu items'=>'Elementos de submenú','Visible in submenu'=>'Visible en el submenú','Add custom link'=>'Añadir enlace personalizado','Add spacer'=>'Añadir separador','Add heading'=>'Añadir encabezado','Top section'=>'Sección superior','Items above the “Site management” heading.'=>'Elementos por encima del encabezado «Gestión del sitio».','Items below the “Site management” heading. Leave empty to hide the heading.'=>'Elementos debajo del encabezado «Gestión del sitio». Déjalo vacío para ocultar el encabezado.','More menu'=>'Menú Más','Items shown inside the More dropdown.'=>'Elementos mostrados dentro del desplegable Más.','Custom link'=>'Enlace personalizado','Label'=>'Etiqueta','Customer support'=>'Soporte al cliente','URL'=>'URL','Icon'=>'Icono','Or paste a custom SVG icon'=>'O pega un icono SVG personalizado','Paste SVG code or a data:image/svg+xml;base64,… URI'=>'Pega código SVG o un URI data:image/svg+xml;base64,…','Paste an SVG from Icons8, SVG Repo or anywhere. It overrides the icon chosen above. Leave empty to use the icon above.'=>'Pega un SVG de Icons8, SVG Repo o de cualquier sitio. Sustituye al icono elegido arriba. Déjalo vacío para usar el icono de arriba.','Open in a new tab'=>'Abrir en una pestaña nueva','Use original'=>'Usar original','Edit custom link'=>'Editar enlace personalizado','Change icon'=>'Cambiar icono','Edit menu item'=>'Editar elemento de menú','That SVG could not be read. Paste valid SVG code or a data:image/svg+xml URI.'=>'No se pudo leer ese SVG. Pega código SVG válido o un URI data:image/svg+xml.','Reset sidebar navigation to its defaults? This clears all customizations and removes custom links.'=>'¿Restablecer la navegación de la barra lateral a sus valores predeterminados? Esto borra todas las personalizaciones y elimina los enlaces personalizados.','Remove this custom link?'=>'¿Eliminar este enlace personalizado?','Remove this menu item? It does not exist on this site, so removing it only clears the leftover setting.'=>'¿Quitar este elemento de menú? No existe en este sitio, así que quitarlo solo borra el ajuste sobrante.','Please enter a valid URL (starting with http:// or https://) or an admin path.'=>'Introduce una URL válida (comenzando por http:// o https://) o una ruta de administración.','Please enter a label.'=>'Introduce una etiqueta.','New section'=>'Nueva sección','Order statusReturn Draft'=>'Borrador de devolución','Order statusChange'=>'Cambio','orders bulk actionChange status to %s'=>'Cambiar el estado a %s','Select at least one status to import.'=>'Selecciona al menos un estado para importar.','%d status imported.'=>'%d estado importado.' . "\0" . '%d estados importados.','Order statuses'=>'Estados de pedido','Create your own order statuses. Use these for workflows WooCommerce does not cover out of the box, such as "Awaiting stock", "Packed" or "Ready for pickup". This applies to every order, whether it contains simple or variable products.'=>'Crea tus propios estados de pedido. Úsalos para flujos de trabajo que WooCommerce no cubre de serie, como "En espera de stock", "Empaquetado" o "Listo para recoger". Esto se aplica a todos los pedidos, ya contengan productos simples o variables.','Import from another plugin'=>'Importar desde otro plugin','We found custom order statuses created outside BrikPanel. Adopt them here so you can safely deactivate the other plugin: your orders keep their status, colour and filters. This is the same for orders with simple or variable products.'=>'Hemos encontrado estados de pedido personalizados creados fuera de BrikPanel. Adóptalos aquí para poder desactivar el otro plugin con seguridad: tus pedidos conservan su estado, su color y sus filtros. Funciona igual para pedidos con productos simples o variables.','Import selected'=>'Importar los seleccionados','%s order'=>'%s pedido' . "\0" . '%s pedidos','Currently provided by another active plugin.'=>'Actualmente lo proporciona otro plugin activo.','active plugin'=>'plugin activo','Used by orders but no longer registered by any plugin. Orders show the raw status key until you import it.'=>'Lo usan pedidos, pero ya no lo registra ningún plugin. Los pedidos muestran la clave de estado sin procesar hasta que lo importes.','needs rescue'=>'necesita rescate','Imported statuses appear in the list below, where you can rename the colour or remove them. Only import statuses from a plugin you plan to remove. A status marked "active plugin" is still managed by that plugin.'=>'Los estados importados aparecen en la lista de abajo, donde puedes renombrarlos, cambiar su color o eliminarlos. Importa solo estados de un plugin que vayas a quitar. Un estado marcado como "plugin activo" lo sigue gestionando ese plugin.','Your custom statuses'=>'Tus estados personalizados','Add as many as you need. Pick a colour so each one stands out in the orders list.'=>'Añade tantos como necesites. Elige un color para que cada uno destaque en la lista de pedidos.','Add status'=>'Añadir estado','No custom statuses yet. Click "Add status" to create your first one.'=>'Aún no hay estados personalizados. Haz clic en "Añadir estado" para crear el primero.','Status name'=>'Nombre del estado','Remove status'=>'Eliminar estado','Removing a status that orders already use will leave those orders showing the raw status key until you re-create it. Existing status keys cannot be renamed.'=>'Eliminar un estado que ya usan pedidos hará que esos pedidos muestren la clave del estado sin procesar hasta que vuelvas a crearlo. Las claves de estado existentes no se pueden renombrar.','Remove this status? Orders already using it will show the raw status key until you re-create it.'=>'¿Eliminar este estado? Los pedidos que ya lo usan mostrarán la clave del estado sin procesar hasta que vuelvas a crearlo.','new'=>'nuevo','Importing…'=>'Importando…','Import failed. Please try again.'=>'La importación ha fallado. Inténtalo de nuevo.','Your order {order_number} is now {order_status}'=>'Tu pedido {order_number} ahora está {order_status}','Your order status has changed'=>'El estado de tu pedido ha cambiado','Hi {customer_first_name},

This is a quick update on your order {order_number} placed on {order_date}. Its status is now: {order_status}.

{order_items}

Order total: {order_total}

You can view your order here: {order_view_url}

Thank you for shopping with {site_title}.'=>'Hola {customer_first_name}:

Te informamos brevemente sobre tu pedido {order_number} realizado el {order_date}. Su estado ahora es: {order_status}.

{order_items}

Total del pedido: {order_total}

Puedes ver tu pedido aquí: {order_view_url}

Gracias por comprar en {site_title}.','New status name'=>'Nombre del nuevo estado','List of items'=>'Lista de artículos','Order view link'=>'Enlace para ver el pedido','Customer first name'=>'Nombre del cliente','Customer full name'=>'Nombre completo del cliente','Customer email'=>'Correo electrónico del cliente','Store name'=>'Nombre de la tienda','Status change emails'=>'Correos de cambio de estado','Send an email automatically when an order moves into one of your custom statuses. Each email is styled like your other WooCommerce emails and can use placeholders such as {order_number}.'=>'Envía un correo automáticamente cuando un pedido pasa a uno de tus estados personalizados. Cada correo se muestra con el estilo del resto de tus correos de WooCommerce y puede usar marcadores como {order_number}.','Create a custom status above first, then set up its email here.'=>'Crea primero un estado personalizado arriba y después configura aquí su correo.','On'=>'Activado','Off'=>'Desactivado','Send to'=>'Enviar a','Store admin'=>'Administrador de la tienda','Extra recipients'=>'Destinatarios adicionales','name@example.com, warehouse@example.com'=>'nombre@ejemplo.com, almacen@ejemplo.com','Subject'=>'Asunto','Message'=>'Mensaje','Insert placeholder'=>'Insertar marcador','Show in the sidebar'=>'Mostrar en la barra lateral','Ticked boxes open in the right column instead of the More tab.'=>'Las cajas marcadas se abren en la columna derecha en lugar de en la pestaña «Más».','Additional details'=>'Detalles adicionales','No additional details for this order.'=>'No hay detalles adicionales para este pedido.','Order custom fields'=>'Campos personalizados del pedido','Show a chosen list of order custom fields (extra checkout fields and other order meta) as a clean "Additional details" card on the order page. The card only appears for orders that actually have one of these fields filled in.'=>'Muestra una lista elegida de campos personalizados del pedido (campos adicionales de pago y otros metadatos del pedido) como una tarjeta limpia de "Detalles adicionales" en la página del pedido. La tarjeta solo aparece para los pedidos que realmente tienen uno de estos campos rellenado.','Fields to display'=>'Campos a mostrar','Pick which order custom fields to show. The list is detected automatically from your existing orders. Leave empty to show none.'=>'Elige qué campos personalizados del pedido mostrar. La lista se detecta automáticamente de tus pedidos existentes. Déjalo vacío para no mostrar ninguno.','Additional fields (advanced)'=>'Campos adicionales (avanzado)','Add custom fields by hand when a key is not in the list above, or to set a friendly label. One field per line, as the meta key, optionally followed by a vertical bar and a label. Example: _billing_vat_number | VAT number'=>'Añade campos personalizados a mano cuando una clave no esté en la lista de arriba, o para establecer una etiqueta descriptiva. Un campo por línea, como la clave del metadato, seguida opcionalmente de una barra vertical y una etiqueta. Ejemplo: _billing_vat_number | Número de IVA','Charged to customer'=>'Cobrado al cliente','Paid to the courier'=>'Pagado al transportista','Leave empty to use the amount charged to the customer. Enter 0 if this order cost you nothing to ship.'=>'Déjalo vacío para usar el importe cobrado al cliente. Escribe 0 si enviar este pedido no te costó nada.','Already merged into another order.'=>'Ya se combinó con otro pedido.','Order is in the trash.'=>'El pedido está en la papelera.','Order has a refund on it.'=>'El pedido tiene un reembolso.','Order is refunded.'=>'El pedido está reembolsado.','Pick at least two orders that still exist.'=>'Elige al menos dos pedidos que todavía existan.','These orders are in different currencies. Merging them would produce a meaningless total.'=>'Estos pedidos están en monedas distintas. Combinarlos daría un total sin sentido.','These orders do not agree on whether prices include tax, so their totals cannot be added together.'=>'Estos pedidos no coinciden en si los precios incluyen impuestos, así que sus totales no se pueden sumar.','Remove the orders listed below from the selection, then try again.'=>'Quita de la selección los pedidos que aparecen abajo y vuelve a intentarlo.','A paid order is being merged away. Its payment record stays on the cancelled order, and only the products move.'=>'Se va a combinar un pedido pagado. Su registro de pago se queda en el pedido cancelado y solo se mueven los productos.','The main order you picked is not a paid one, so your revenue figures will drop by the amount of the paid orders being cancelled. Picking a paid order as the main order avoids this.'=>'El pedido principal que elegiste no está pagado, así que tus cifras de ingresos bajarán en el importe de los pedidos pagados que se cancelan. Elegir un pedido pagado como principal lo evita.','Revenue from an older order will be re-dated to the main order, so past-day reports will shift.'=>'Los ingresos de un pedido más antiguo pasarán a la fecha del pedido principal, así que los informes de días pasados cambiarán.','These orders do not look like the same customer. Different: %s. Check before you merge, because the merged order keeps only the main order\'s customer details.'=>'Estos pedidos no parecen del mismo cliente. Diferente: %s. Revísalo antes de combinar, porque el pedido combinado conserva solo los datos del cliente del pedido principal.','The same coupon is on more than one of these orders. Each discount is already baked into its own products and stays correct; the coupon is counted once on the merged order.'=>'El mismo cupón está en más de uno de estos pedidos. Cada descuento ya está incluido en sus propios productos y sigue siendo correcto; el cupón se cuenta una vez en el pedido combinado.','account'=>'cuenta','email'=>'correo electrónico','phone'=>'teléfono','address'=>'dirección','The main order could not be loaded.'=>'No se pudo cargar el pedido principal.','Order no longer exists.'=>'El pedido ya no existe.','There was nothing left to merge.'=>'No quedaba nada que combinar.','Some items would not move, so this order was left untouched.'=>'Algunos artículos no se pudieron mover, así que este pedido no se ha tocado.','Order could not be re-read after moving its items.'=>'No se pudo volver a leer el pedido después de mover sus artículos.','Merged into order %s by BrikPanel. Its items and totals now live on that order.'=>'Combinado en el pedido %s por BrikPanel. Sus artículos y totales ahora están en ese pedido.','Merged in order %1$s. New order total: %2$s.'=>'Se combinó el pedido %1$s. Nuevo total del pedido: %2$s.' . "\0" . 'Se combinaron los pedidos %1$s. Nuevo total del pedido: %2$s.','Duplicate shipping charges were removed; one shipping line was kept.'=>'Se quitaron los gastos de envío duplicados; se conservó una línea de envío.','The orders were merged, but totalling up the merged order failed: %s. Open it and press Recalculate.'=>'Los pedidos se combinaron, pero falló el cálculo del total del pedido combinado: %s. Ábrelo y pulsa Recalcular.','Merge orders'=>'Combinar pedidos','You do not have permission to merge orders.'=>'No tienes permiso para combinar pedidos.','This merge has expired. Select the orders again.'=>'Esta combinación ha caducado. Selecciona los pedidos de nuevo.','You do not have permission to edit one of these orders.'=>'No tienes permiso para editar uno de estos pedidos.','This merge is already running. Give it a moment, then check the order.'=>'Esta combinación ya está en marcha. Espera un momento y luego revisa el pedido.','Order merging is switched off. Turn it back on under WooCommerce, Settings, BrikPanel, Orders List.'=>'La combinación de pedidos está desactivada. Vuelve a activarla en WooCommerce, Ajustes, BrikPanel, Lista de pedidos.','The BrikPanel interface is switched off for this account, so order merging is unavailable.'=>'La interfaz de BrikPanel está desactivada para esta cuenta, así que la combinación de pedidos no está disponible.','Back to orders'=>'Volver a los pedidos','This merge has expired or was already used. Go back to the orders list and select the orders again.'=>'Esta combinación ha caducado o ya se usó. Vuelve a la lista de pedidos y selecciónalos de nuevo.','Products from the other orders move onto the main order. The others are cancelled with a note pointing here, and nothing is deleted.'=>'Los productos de los otros pedidos pasan al pedido principal. Los otros se cancelan con una nota que apunta aquí y no se elimina nada.','These orders cannot be merged'=>'Estos pedidos no se pueden combinar','Which order stays?'=>'¿Qué pedido se queda?','This order keeps its number, its customer details and its payment. Everything else moves into it.'=>'Este pedido conserva su número, los datos del cliente y su pago. Todo lo demás pasa a él.','%d item'=>'%d artículo' . "\0" . '%d artículos','Paid'=>'De pago','Shipping charge'=>'Gastos de envío','You are sending one parcel, but the customer may have paid shipping more than once.'=>'Envías un solo paquete, pero puede que el cliente haya pagado el envío más de una vez.','Charge shipping once'=>'Cobrar el envío una vez','Keeps the most expensive shipping line and drops the rest. Refund the difference to the customer yourself if you owe it.'=>'Conserva la línea de envío más cara y quita las demás. Si debes la diferencia al cliente, reembólsala tú.','Add every shipping charge up'=>'Sumar todos los gastos de envío','Matches what the customer actually paid, so your books stay exact.'=>'Coincide con lo que el cliente pagó de verdad, así tus cuentas siguen exactas.','Update preview'=>'Actualizar vista previa','Before you continue'=>'Antes de continuar','Mark the merged order as Processing so the sale still counts as paid.'=>'Marcar el pedido combinado como Procesando para que la venta siga contando como pagada.','After merging'=>'Después de combinar','Order kept'=>'Pedido conservado','Orders cancelled'=>'Pedidos cancelados','Items in total'=>'Artículos en total','New order total'=>'Nuevo total del pedido','This total is a projection. Tax is carried over exactly as each order recorded it, never recalculated at today\'s rates.'=>'Este total es una estimación. El impuesto se traslada exactamente como lo registró cada pedido, nunca se recalcula con los tipos actuales.','Merge %d order'=>'Combinar %d pedido' . "\0" . 'Combinar %d pedidos','Select at least two orders to merge.'=>'Selecciona al menos dos pedidos para combinar.','You can merge up to %d orders at once.'=>'Puedes combinar hasta %d pedidos a la vez.','%d order was merged into this one.'=>'Se combinó %d pedido en este.' . "\0" . 'Se combinaron %d pedidos en este.','Some orders were left alone:'=>'Algunos pedidos se dejaron como estaban:','This order was merged into %s. Its items and money live there now.'=>'Este pedido se combinó en %s. Sus artículos e importes están ahora allí.','Merged in: %s'=>'Combinados: %s','A merge into this order did not finish. Check its items and the orders you were merging before trying again.'=>'Una combinación en este pedido no terminó. Revisa sus artículos y los pedidos que estabas combinando antes de volver a intentarlo.','Hi {customer_first_name}, this is {site_title} about your order {order_number}. Its current status is {order_status}.'=>'Hola {customer_first_name}, te escribo de {site_title} sobre tu pedido {order_number}. Su estado actual es {order_status}.','Message the customer on WhatsApp'=>'Escribir al cliente por WhatsApp','A one-click WhatsApp shortcut for reaching a customer about their order: a small WhatsApp icon on the orders list and a "Message on WhatsApp" button under the billing address on the order edit screen. It opens a chat pre-targeting the order\'s billing phone. Shown to everyone who can manage WooCommerce orders by default.'=>'Un atajo de WhatsApp de un clic para contactar con un cliente sobre su pedido: un pequeño icono de WhatsApp en la lista de pedidos y un botón «Escribir por WhatsApp» debajo de la dirección de facturación en la pantalla de edición del pedido. Abre un chat que ya apunta al teléfono de facturación del pedido. Por defecto se muestra a todo el mundo que pueda gestionar pedidos de WooCommerce.','WhatsApp order shortcut'=>'Atajo de WhatsApp en pedidos','Show the WhatsApp icon on the orders list and the "Message on WhatsApp" button on the order edit screen. Turn this off to remove both everywhere. On by default.'=>'Mostrar el icono de WhatsApp en la lista de pedidos y el botón «Escribir por WhatsApp» en la pantalla de edición del pedido. Desactívalo para quitar ambos en todas partes. Activado por defecto.','Hide WhatsApp shortcut from roles'=>'Ocultar el atajo de WhatsApp a ciertos roles','No roles selected: everyone sees it'=>'Ningún rol seleccionado: todos lo ven','Users with any of the selected roles no longer see the WhatsApp shortcut, while everyone else keeps it. A user hidden this way can switch it back on for their own account from their WordPress profile page. Leave empty to show it to everyone who can manage WooCommerce orders.'=>'Los usuarios con cualquiera de los roles seleccionados dejan de ver el atajo de WhatsApp, y el resto lo conserva. Un usuario oculto así puede volver a activarlo solo para su cuenta desde su página de perfil de WordPress. Déjalo vacío para mostrarlo a todo el mundo que pueda gestionar pedidos de WooCommerce.','WhatsApp opens with this text already typed in, so you only have to press send - nothing goes out on its own. Write it in any language, and use line breaks freely. {order_items} lists every product on its own line, so give it a line of its own. Clear this field to go back to opening an empty conversation.'=>'WhatsApp se abre con este texto ya escrito, así que solo tienes que pulsar enviar: nada sale por su cuenta. Escríbelo en cualquier idioma y usa saltos de línea con libertad. {order_items} lista cada producto en su propia línea, así que dale una línea propia. Vacía este campo para volver a abrir una conversación vacía.','Current status name'=>'Nombre del estado actual','List of items, one per line'=>'Lista de artículos, uno por línea','Message per order status'=>'Mensaje por estado del pedido','Say something different depending on where the order stands - one message while it is being prepared, another while it is still awaiting payment. Switch a status on and write its message; every status you leave off uses the general message above.'=>'Di algo distinto según en qué punto esté el pedido: un mensaje mientras se prepara, otro mientras sigue pendiente de pago. Activa un estado y escribe su mensaje; cada estado que dejes desactivado usa el mensaje general de arriba.','No order statuses are registered yet.'=>'Todavía no hay ningún estado de pedido registrado.','WhatsApp shortcut'=>'Atajo de WhatsApp','Show the WhatsApp order shortcut for my account'=>'Mostrar el atajo de WhatsApp en pedidos para mi cuenta','Your role has the WhatsApp order shortcut turned off. Tick this to show the WhatsApp icon on the orders list and the button on the order edit screen for your account only.'=>'Tu rol tiene el atajo de WhatsApp en pedidos desactivado. Marca esto para mostrar el icono de WhatsApp en la lista de pedidos y el botón en la pantalla de edición del pedido solo para tu cuenta.','Show in the row'=>'Mostrar en la fila','Ticked columns stay in the order row instead of opening under the order.'=>'Las columnas marcadas se quedan en la fila del pedido en lugar de abrirse debajo del pedido.','Shipping'=>'Envío','None'=>'Ninguno','%s ×'=>'%s ×','via %s'=>'vía %s','No billing address'=>'Sin dirección de facturación','(Phone: %s)'=>'(Teléfono: %s)','No shipping address'=>'Sin dirección de envío','No shipping needed'=>'No requiere envío','+ %d more item'=>'+ %d artículo más' . "\0" . '+ %d artículos más','Items (%s)'=>'Artículos (%s)','No items'=>'Sin artículos','Open order'=>'Abrir pedido','Preview'=>'Vista previa','Billing'=>'Facturación','Ship to'=>'Enviar a','BrikPanel'=>'BrikPanel','The WP Consent API plugin is active on this site, so BrikPanel follows whatever your cookie banner reports for the statistics category.'=>'El plugin WP Consent API está activo en este sitio, así que BrikPanel sigue lo que tu banner de cookies indique para la categoría de estadísticas.','No consent plugin was detected on this site. With this on, tracking stays off until your cookie banner tells BrikPanel that analytics are allowed.'=>'No se ha detectado ningún plugin de consentimiento en este sitio. Con esto activado, el seguimiento permanece desactivado hasta que tu banner de cookies le indique a BrikPanel que las analíticas están permitidas.','Navigation'=>'Navegación','Modern navigation'=>'Navegación moderna','Replace the default WordPress admin menu with a modern, clean sidebar navigation'=>'Sustituye el menú de administración predeterminado de WordPress por una navegación lateral moderna y limpia','Style the default menu'=>'Aplicar estilo al menú predeterminado','When Modern navigation is off, give the standard WordPress admin menu the BrikPanel look. Turn this off to keep the original WordPress menu unchanged.'=>'Cuando la navegación moderna está desactivada, da al menú de administración estándar de WordPress el aspecto de BrikPanel. Desactiva esto para mantener el menú original de WordPress sin cambios.','Hide new menu items by default'=>'Ocultar los nuevos elementos de menú por defecto','When a newly installed plugin adds a sidebar menu item, keep it hidden until you review it in the editor below. Handy when you manage sites for clients and do not want new items to appear before you have checked them. Items you have already placed are unaffected.'=>'Cuando un plugin recién instalado añade un elemento al menú lateral, mantenlo oculto hasta que lo revises en el editor de abajo. Práctico si gestionas sitios para clientes y no quieres que aparezcan elementos nuevos antes de comprobarlos. Los elementos que ya has colocado no se ven afectados.','Orders List'=>'Lista de pedidos','Enhanced orders page'=>'Página de pedidos mejorada','Enhance the orders list page with modern search, filters, overview section, and styling'=>'Mejora la página de la lista de pedidos con búsqueda moderna, filtros, sección de resumen y estilo','Compact order list'=>'Lista de pedidos compacta','Show each order as one short row. Click the arrow next to an order to see its addresses, phone number and items without leaving the list. Works when Enhanced orders page is on.'=>'Muestra cada pedido en una sola fila corta. Haz clic en la flecha junto a un pedido para ver sus direcciones, teléfono y artículos sin salir de la lista. Funciona cuando la página de pedidos mejorada está activada.','Select two or more orders in the list and combine them into one. Items move to the order you pick as the main one; the others are cancelled with a note pointing to it, never deleted. A preview screen shows what will change before anything is written.'=>'Selecciona dos o más pedidos en la lista y combínalos en uno. Los artículos pasan al pedido que elijas como principal; los demás se cancelan con una nota que apunta a él, nunca se eliminan. Una pantalla de vista previa muestra qué cambiará antes de escribir nada.','Order Edit Page'=>'Página de edición de pedido','Modern order edit'=>'Edición de pedido moderna','Clean up the order edit page: hide unnecessary metaboxes and apply modern styling'=>'Limpiar la página de edición de pedidos: ocultar las cajas meta innecesarias y aplicar un estilo moderno','Simplified product editor'=>'Editor de productos simplificado','Replace the default WooCommerce product editor with a simplified, easy-to-use interface'=>'Sustituye el editor de productos predeterminado de WooCommerce por una interfaz simplificada y fácil de usar','Product type selector'=>'Selector de tipo de producto','Show a product type dropdown in the simplified editor so you can create subscription, variable subscription, bundle and other types registered by third-party plugins. When off, only simple and variable products can be created. Auto-enabled if a subscription/bookings/bundles plugin is active.'=>'Muestra un desplegable de tipo de producto en el editor simplificado para que puedas crear suscripciones, suscripciones variables, packs y otros tipos registrados por plugins de terceros. Cuando está desactivado, solo se pueden crear productos simples y variables. Se activa automáticamente si hay un plugin de suscripciones, reservas o packs activo.','Visible editor sections'=>'Secciones visibles del editor','Toggle a section to show or hide it. Use the arrows to reorder; the product editor renders sections in the order shown here. Metaboxes registered by other plugins (Yoast SEO, Rank Math, All in One SEO, SEOPress, custom post types, etc.) appear in this list automatically, tagged "Plugin". Enable and position any you want to edit right inside the BrikPanel editor.'=>'Activa o desactiva una sección para mostrarla u ocultarla. Usa las flechas para reordenarlas; el editor de productos muestra las secciones en el orden que ves aquí. Las cajas meta registradas por otros plugins (Yoast SEO, Rank Math, All in One SEO, SEOPress, tipos de contenido personalizados, etc.) aparecen automáticamente en esta lista, etiquetadas como "Plugin". Activa y coloca las que quieras editar directamente en el editor de BrikPanel.','Use the full screen width'=>'Usar todo el ancho de la pantalla','On a wide monitor, let the editor use the extra width instead of staying in a narrow centre column. It keeps growing with the screen rather than stopping at a fixed size, and the short setting cards move into a side column, the way the standard WordPress editor arranges them. Has no effect on screens narrower than about 1360 pixels.'=>'En un monitor ancho, deja que el editor use el ancho adicional en lugar de quedarse en una columna central estrecha. Sigue creciendo con la pantalla en vez de detenerse en un tamaño fijo, y las tarjetas de ajustes cortas pasan a una columna lateral, tal como las coloca el editor estándar de WordPress. No tiene efecto en pantallas de menos de 1360 píxeles aproximadamente.','Product publish scheduling'=>'Programación de publicación de productos','Add a "Scheduled" option to the status menu in the product editor so you can set a future date and time for a product to go live automatically. Works for simple and variable products.'=>'Añade una opción "Programado" al menú de estado del editor de productos para que puedas fijar una fecha y una hora futuras en las que el producto se publique automáticamente. Funciona con productos simples y variables.','Auto-include ACF field groups'=>'Incluir grupos de campos ACF automáticamente','Automatically render Advanced Custom Fields field groups whose Location Rules target products. When off, ACF field groups are hidden from the editor.'=>'Muestra automáticamente los grupos de campos de Advanced Custom Fields cuyas reglas de ubicación apuntan a productos. Cuando está desactivado, los grupos de campos de ACF se ocultan del editor.','Auto-show fields other plugins add'=>'Mostrar automáticamente los campos que añaden otros plugins','Automatically show, and save, fields that another plugin adds to WooCommerce\'s native "Product data" tabs (internal product codes, subscription options, booking settings, extra fields, and so on), with no setup, for both simple and variable products. When off (the default), pick the sections you want in the "Additional product data sections" picker below. Each option lists the fields it contains, so you can find a plugin\'s field by name. Per-variation fields added by other plugins are always kept and saved either way, so saving a product never wipes them.'=>'Muestra y guarda automáticamente los campos que otro plugin añade a las pestañas nativas «Datos del producto» de WooCommerce (códigos internos de producto, opciones de suscripción, ajustes de reservas, campos extra, etc.), sin configuración, tanto en productos simples como variables. Cuando está desactivado (por defecto), elige las secciones que quieras en el selector «Secciones adicionales de datos del producto» de abajo. Cada opción lista los campos que contiene, así que puedes encontrar el campo de un plugin por su nombre. Los campos por variación que añaden otros plugins se conservan y se guardan siempre en ambos casos, así que guardar un producto nunca los borra.','Additional product data sections'=>'Secciones adicionales de datos de producto','Only needed when "Auto-show fields other plugins add" is off (or to force-include a section). Pick which sections from WooCommerce\'s native "Product data" tabs (General, Inventory, Shipping, and custom tabs added by Subscriptions, Memberships, Bookings, swatches, SEO plugins…) should appear as "Additional product data" inside the BrikPanel editor.'=>'Solo es necesario cuando «Mostrar automáticamente los campos que añaden otros plugins» está desactivado (o para incluir una sección a la fuerza). Elige qué secciones de las pestañas nativas «Datos del producto» de WooCommerce (General, Inventario, Envío y pestañas personalizadas añadidas por Subscriptions, Memberships, Bookings, swatches, plugins de SEO…) deben aparecer como «Datos adicionales del producto» dentro del editor de BrikPanel.','Additional product data position'=>'Posición de los datos adicionales del producto','Where the "Additional product data" card appears inside the BrikPanel product editor.'=>'Dónde aparece la tarjeta "Datos adicionales del producto" dentro del editor de productos de BrikPanel.','Top, right under the product name'=>'Arriba, justo debajo del nombre del producto','Middle, between pricing and inventory'=>'En medio, entre precios e inventario','Bottom, end of the editor'=>'Abajo, al final del editor','Additional variation data sections'=>'Secciones adicionales de datos de variación','Pick which per-variation fields added by third-party plugins (pricing extensions, subscriptions, inventory add-ons…) should appear inside each variation row. Leave empty to hide all (hidden by default).'=>'Elige qué campos por variación añadidos por plugins de terceros (extensiones de precios, suscripciones, complementos de inventario…) deben aparecer en cada fila de variación. Déjalo vacío para ocultarlos todos (ocultos por defecto).','Modern products list'=>'Lista de productos moderna','Replace the default products list with a modern, AJAX-powered interface with inline editing'=>'Sustituye la lista de productos predeterminada por una interfaz moderna basada en AJAX con edición en línea','Quick Edit drawer fields'=>'Campos del panel de edición rápida','Pick which fields appear in the Quick Edit drawer and the order they render in. Toggle a field to show or hide it; use the arrows to reorder. "Simple only" fields are skipped automatically when editing variable products. The featured-product star toggle also controls the matching icons in the products list and the product editor header.'=>'Elige qué campos aparecen en el panel de edición rápida y el orden en que se renderizan. Activa o desactiva un campo para mostrarlo u ocultarlo; usa las flechas para reordenar. Los campos "Solo simple" se omiten automáticamente al editar productos variables. El conmutador de estrella de producto destacado también controla los iconos coincidentes en la lista de productos y en el encabezado del editor de productos.','Open product in new tab'=>'Abrir producto en una pestaña nueva','When enabled, clicking a product name in the products list opens the edit page in a new browser tab.'=>'Cuando está activado, hacer clic en el nombre de un producto en la lista de productos abre la página de edición en una pestaña nueva del navegador.','Products per page'=>'Productos por página','Number of products to display per page in the products list'=>'Número de productos a mostrar por página en la lista de productos','Category tree view'=>'Vista de árbol de categorías','Show product categories as a folder tree: click a parent to expand or collapse its sub-categories, drag a category onto another to nest it, and filter the whole tree as you type. Up to 300 categories the full hierarchy is kept on a single page, so a branch is never split across pagination; a larger catalogue keeps paging and still gets the tree.'=>'Muestra las categorías de producto como un árbol de carpetas: pulsa una categoría superior para desplegar o plegar sus subcategorías, arrastra una categoría sobre otra para anidarla y filtra todo el árbol mientras escribes. Hasta 300 categorías, la jerarquía completa se mantiene en una sola página, así que una rama nunca se parte entre páginas; un catálogo mayor sigue paginando y aun así obtiene el árbol.','Categories per page'=>'Categorías por página','Number of categories to display per page. Ignored while the category tree view is on, because the whole tree is shown at once.'=>'Número de categorías que se muestran por página. Se ignora mientras la vista de árbol de categorías está activada, porque entonces se muestra todo el árbol a la vez.','Backorder notification option'=>'Opción de notificación de reserva','Reveal a "Notify customer" choice under the stock status when "On backorder" is selected. Lets you allow backorders silently or with an order-note alert. Applies to simple products and variations.'=>'Muestra una opción "Notificar al cliente" bajo el estado de stock cuando se selecciona "En reserva". Te permite permitir reservas en silencio o con una alerta en la nota del pedido. Se aplica a productos simples y variaciones.','Multiple images per variation'=>'Múltiples imágenes por variación','Allow each variation to have its own image gallery (multiple images), and swap the product gallery on the storefront when a variation is selected. When off, each variation is limited to a single image, the WooCommerce default. Existing extra variation images are kept in the database and will reappear if you re-enable this option.'=>'Permite que cada variación tenga su propia galería de imágenes (varias imágenes) y cambia la galería del producto en la tienda cuando se elige una variación. Cuando está desactivado, cada variación se limita a una sola imagen, lo habitual en WooCommerce. Las imágenes adicionales de variación existentes se conservan en la base de datos y volverán a aparecer si reactivas esta opción.','Create global attributes automatically'=>'Crear atributos globales automáticamente','When you type a new variation attribute name in the product editor, turn it into a real WooCommerce attribute (Products &rarr; Attributes) instead of keeping it as a product-only custom attribute. Global attributes are what colour and size swatch themes, layered navigation and attribute filters read, so most stores want this on. Attributes are created only when the product is published, so drafts are left alone, and an attribute that already exists is reused instead of duplicated. Turning this off later does not undo attributes that were already created; remove those in Products &rarr; Attributes.'=>'Cuando escribes el nombre de un nuevo atributo de variación en el editor de productos, se convierte en un atributo real de WooCommerce (Productos &rarr; Atributos) en lugar de quedarse como un atributo personalizado solo de ese producto. Los atributos globales son los que leen los temas con muestras de color y talla, la navegación por capas y los filtros de atributos, así que la mayoría de las tiendas quieren esto activado. Los atributos se crean solo cuando se publica el producto, así que los borradores se dejan en paz, y un atributo que ya existe se reutiliza en lugar de duplicarse. Desactivar esto más tarde no deshace los atributos ya creados; elimínalos en Productos &rarr; Atributos.','Modern dashboard'=>'Dashboard moderno','Replace the default WordPress dashboard with a modern, Shopify-inspired analytics dashboard'=>'Sustituye el escritorio predeterminado de WordPress por un dashboard de analíticas moderno inspirado en Shopify','Dashboard top bar'=>'Barra superior del dashboard','Hide the WordPress admin bar on the BrikPanel dashboard and replace it with a BrikPanel-styled e-commerce top bar featuring live revenue, live visitors, global search, quick-create actions, and order notifications.'=>'Oculta la barra de administración de WordPress en el dashboard de BrikPanel y la sustituye por una barra superior de comercio electrónico al estilo BrikPanel con ingresos en vivo, visitantes en vivo, búsqueda global, acciones de creación rápida y notificaciones de pedidos.','Top bar items'=>'Elementos de la barra superior','Choose which controls appear in the BrikPanel top bar. Turn a control off to hide it from the bar.'=>'Elige qué controles aparecen en la barra superior de BrikPanel. Desactiva un control para ocultarlo de la barra.','Include WordPress dashboard widgets'=>'Incluir widgets del escritorio de WordPress','Pick which WordPress dashboard widgets (e.g. At a Glance, Activity, Fail2Ban log) should also appear inside the BrikPanel dashboard, styled to match. Widgets are arranged in a responsive 3-column grid.'=>'Elige qué widgets del escritorio de WordPress (p. ej. De un vistazo, Actividad, registro de Fail2Ban) también deben aparecer dentro del dashboard de BrikPanel, con un estilo coincidente. Los widgets se organizan en una rejilla responsive de 3 columnas.','Widget access'=>'Acceso a los widgets','Choose who can see each embedded WordPress dashboard widget. Use this to keep sensitive widgets like "Site Health Status" limited to administrators or specific roles. Administrators always see every widget.'=>'Elige quién puede ver cada widget del escritorio de WordPress incrustado. Úsalo para limitar widgets sensibles como "Estado de salud del sitio" a los administradores o a roles concretos. Los administradores siempre ven todos los widgets.','Dashboard sections'=>'Secciones del dashboard','Toggle a section to show or hide it. Use the arrows to reorder; the dashboard renders sections in the order shown here. Hidden sections skip rendering entirely, so their data is not fetched.'=>'Activa o desactiva una sección para mostrarla u ocultarla. Usa las flechas para reordenar; el panel muestra las secciones en el orden que ves aquí. Las secciones ocultas no se generan en absoluto, así que sus datos no se consultan.','Profit section fields'=>'Campos de la sección de beneficios','Choose which fields appear in the Profit section. Revenue and Net profit are always shown. Hiding a field only removes it from view. It is still factored into Net profit where it is a real cost, so the figure stays accurate.'=>'Elige qué campos aparecen en la sección de beneficios. Los ingresos y el beneficio neto siempre se muestran. Ocultar un campo solo lo quita de la vista. Sigue contando en el beneficio neto cuando es un coste real, así que la cifra se mantiene exacta.','Tax in the Profit section'=>'Impuestos en la sección de beneficios','Where the tax your customers paid appears in the Profit section. Inside Expenses: Revenue includes the tax and the same tax is one of the Expenses. Taken out of Revenue and Expenses: Revenue is shown without tax. Kept in Revenue: Revenue includes the tax, the amount is shown under it, and it is not counted in Expenses. Net profit is exactly the same in all three.'=>'Dónde aparecen los impuestos que pagaron tus clientes en la sección de beneficios. Dentro de los gastos: los ingresos incluyen los impuestos y esos mismos impuestos son uno de los gastos. Fuera de los ingresos y los gastos: los ingresos se muestran sin impuestos. Dentro de los ingresos: los ingresos incluyen los impuestos, el importe se muestra debajo y no se cuentan en los gastos. El beneficio neto es exactamente el mismo en los tres casos.','Inside Expenses'=>'Dentro de los gastos','Taken out of Revenue and Expenses'=>'Fuera de los ingresos y los gastos','Kept in Revenue (not in Expenses)'=>'Dentro de los ingresos (no en los gastos)','Decide which order statuses your analytics count. This drives every figure: Revenue, Orders, Average Order Value, Profit, Customer Lifetime Value and the order-rate breakdown. If you use a shipment-tracking or returns plugin that adds custom statuses (for example "Partially shipped", "Delivered" or "Partially refunded"), add them here so those orders stop being left out of your numbers.'=>'Decide qué estados de pedido cuentan en tus analíticas. Esto determina todas las cifras: ingresos, pedidos, valor medio del pedido, beneficio, valor de vida del cliente y el desglose de la tasa de pedidos. Si usas un plugin de seguimiento de envíos o de devoluciones que añade estados personalizados (por ejemplo "Enviado parcialmente", "Entregado" o "Reembolsado parcialmente"), añádelos aquí para que esos pedidos dejen de quedar fuera de tus cifras.','Statuses counted as valid sales'=>'Estados contados como ventas válidas','Orders in these statuses are counted as real, completed sales across Revenue, Orders, AOV, Profit and Customer Lifetime Value. Defaults to Processing and Completed, which is what WooCommerce itself treats as paid. Leave empty to keep the default.'=>'Los pedidos en estos estados se cuentan como ventas reales y completadas en los ingresos, los pedidos, el AOV, el beneficio y el valor de vida del cliente. Por defecto son En proceso y Completado, que es lo que el propio WooCommerce trata como pagado. Déjalo vacío para mantener el valor predeterminado.','Statuses counted as refunds'=>'Estados contados como reembolsos','Orders in these statuses are treated as refunds in the returns and refund-rate figures, and still count toward Customer Lifetime Value (the customer did buy). Defaults to the WooCommerce Refunded status. Leave empty to keep the default.'=>'Los pedidos en estos estados se tratan como reembolsos en las cifras de devoluciones y de tasa de reembolso, y siguen contando para el valor de vida del cliente (el cliente sí compró). Por defecto es el estado Reembolsado de WooCommerce. Déjalo vacío para mantener el valor predeterminado.','Subtract shipping cost from Net profit'=>'Restar el coste de envío del beneficio neto','On by default. What you charge for shipping is treated as a cost as well as revenue, so it stops inflating your Net profit. WooCommerce only records what the customer was charged for delivery, never what you paid the courier, so that charge is what gets deducted. When you know the real figure for an order, enter it in the Shipping cost box on that order and it is used instead. For orders you ship free of charge nothing was charged, so nothing is deducted here, so add a "Cost per order" expense set to "Orders shipped free" to cover the courier on those. Turning this off raises your Net profit in past periods too.'=>'Activado por defecto. Lo que cobras por el envío se trata como coste además de como ingreso, para que deje de inflar tu beneficio neto. WooCommerce solo registra lo que se cobró al cliente por la entrega, nunca lo que pagaste al transportista, así que se resta ese cobro. Cuando sepas la cifra real de un pedido, escríbela en la casilla Coste de envío de ese pedido y se usará en su lugar. En los pedidos que envías gratis no se cobró nada, así que aquí no se resta nada; añade un gasto "Coste por pedido" con "Pedidos con envío gratis" para cubrir al transportista en esos. Desactivarlo sube también tu beneficio neto de periodos pasados.','Visitor tracking'=>'Seguimiento de visitantes','Track visitors, page views, product views, add-to-carts, checkout visits and live visitors on your storefront. Turn this off if you already use a dedicated analytics tool. BrikPanel will stop adding any tracking scripts or requests to your store pages, and the related dashboard cards will simply stop receiving new data.'=>'Registra visitantes, páginas vistas, visualizaciones de producto, añadidos al carrito, visitas al pago y visitantes en vivo en tu tienda. Desactívalo si ya usas una herramienta de analítica dedicada. BrikPanel dejará de añadir scripts o peticiones de seguimiento a las páginas de tu tienda, y las tarjetas relacionadas del panel simplemente dejarán de recibir datos nuevos.','Wait for cookie consent'=>'Esperar el consentimiento de cookies','Hold visitor tracking back until the visitor allows analytics: no tracking cookie, no browser storage and no tracking request is created before then. BrikPanel accepts consent from the WordPress Consent API (the "statistics" category), from a cookie banner that calls brikpanel_start_tracking(), or from the brikpanel_frontend_tracking_allowed filter. Consent works without a page reload, and when it is withdrawn tracking stops at once and BrikPanel deletes its own tracking cookies and browser storage for that visitor. This covers analytics only: abandoned-cart email capture is a separate feature with its own switch. It saves no cart for a guest until they enter their email, while a logged-in customer\'s cart is saved as soon as it has items, using the email on their account. Leave this off if your store does not need a consent banner: your analytics keep working exactly as before.'=>'Retiene el seguimiento de visitantes hasta que el visitante permite las analíticas: antes de eso no se crea ninguna cookie de seguimiento, ningún almacenamiento en el navegador ni ninguna petición de seguimiento. BrikPanel acepta el consentimiento de la Consent API de WordPress (la categoría «statistics»), de un banner de cookies que llame a brikpanel_start_tracking(), o del filtro brikpanel_frontend_tracking_allowed. El consentimiento funciona sin recargar la página, y cuando se retira el seguimiento se detiene al instante y BrikPanel borra sus propias cookies de seguimiento y el almacenamiento del navegador de ese visitante. Esto solo cubre las analíticas: la captura de correos de carritos abandonados es una función aparte con su propio interruptor. No guarda ningún carrito de un invitado hasta que introduce su correo, mientras que el carrito de un cliente con sesión iniciada se guarda en cuanto tiene productos, con el correo de su cuenta. Déjalo desactivado si tu tienda no necesita un banner de consentimiento: tus analíticas siguen funcionando exactamente como antes.','BrikPanel already ignores every crawler it recognises, including Googlebot, Google Storebot, Bing, the AI crawlers and any tool that identifies itself as a bot. Add anything else you want left out of your analytics here, one entry per line. A partial name is enough: typing "shopping" leaves out every visit whose browser name contains it.'=>'BrikPanel ya ignora todos los rastreadores que reconoce, incluidos Googlebot, Google Storebot, Bing, los rastreadores de IA y cualquier herramienta que se identifique como bot. Añada aquí cualquier otro que quiera dejar fuera de sus analíticas, uno por línea. Basta con una parte del nombre: escribir "shopping" deja fuera todas las visitas cuyo nombre de navegador lo contenga.','Visits from these addresses are never counted. Use it for your own office or warehouse, or for a crawler that pretends to be a normal browser. One per line. You can enter a single address, or a whole range in the 203.0.113.0/24 style.'=>'Las visitas desde estas direcciones nunca se cuentan. Úselo para su propia oficina o almacén, o para un rastreador que se hace pasar por un navegador normal. Una por línea. Puede introducir una sola dirección o todo un rango con el formato 203.0.113.0/24.','Live visitor refresh interval'=>'Intervalo de actualización de visitantes en vivo','seconds'=>'segundos','How often an open store page reports that its visitor is still there, for the Live view. Higher values mean fewer requests to your server; the Live view reacts a little slower. Default is 30 seconds.'=>'Con qué frecuencia una página abierta de la tienda informa de que su visitante sigue ahí, para la vista En vivo. Valores más altos significan menos peticiones a tu servidor; la vista En vivo reacciona un poco más despacio. Por defecto son 30 segundos.','Customer details in Live view'=>'Datos del cliente en la vista En vivo','When a logged-in customer browses your store, show their name, email and phone in the Live visitors panel. Turn this off to keep live tracking fully anonymous: no personal details are cached at all. Live visitor data is only ever kept in a short-lived cache (a couple of minutes) and is never written to the database permanently.'=>'Cuando un cliente con sesión iniciada navega por tu tienda, muestra su nombre, correo y teléfono en el panel de visitantes en vivo. Desactívalo para mantener el seguimiento en vivo totalmente anónimo: no se guarda en caché ningún dato personal. Los datos de visitantes en vivo solo se mantienen en una caché de corta duración (un par de minutos) y nunca se escriben de forma permanente en la base de datos.','Traffic source in Live view'=>'Fuente de tráfico en la vista En vivo','Show where each live visitor came from (for example Organic Search · google.com or Paid · bing.com) under the page they are on. Hover a visitor to see the campaign, search term and landing page from their link. The source is remembered only for the open browser tab and is kept with the rest of the live data for a couple of minutes.'=>'Muestra de dónde vino cada visitante en vivo (por ejemplo Búsqueda orgánica · google.com o De pago · bing.com) debajo de la página que está viendo. Pasa el ratón por encima de un visitante para ver la campaña, el término de búsqueda y la página de entrada de su enlace. El origen solo se recuerda para la pestaña abierta del navegador y se guarda con el resto de los datos en vivo durante un par de minutos.','Modern coupons page settings, plus optional usage restriction fields for power users migrating from the default WooCommerce editor.'=>'Ajustes modernos de la página de cupones, más campos opcionales de restricción de uso para usuarios avanzados que migran del editor predeterminado de WooCommerce.','Modern coupons page'=>'Página de cupones moderna','Replace the default coupons list with a modern, AJAX-powered interface'=>'Sustituye la lista de cupones predeterminada por una interfaz moderna basada en AJAX','Restrict to specific products'=>'Restringir a productos específicos','Show a "Products" picker so you can limit the coupon to a hand-picked product list.'=>'Muestra un selector "Productos" para que puedas limitar el cupón a una lista de productos elegida a mano.','Exclude specific products'=>'Excluir productos específicos','Show an "Exclude products" picker so you can disallow specific products even when the rest of the cart qualifies.'=>'Muestra un selector "Excluir productos" para que puedas no permitir productos específicos incluso cuando el resto del carrito sea válido.','Restrict to product categories'=>'Restringir a categorías de producto','Show a "Product categories" picker so the coupon only applies to items in the selected categories.'=>'Muestra un selector "Categorías de producto" para que el cupón solo se aplique a artículos de las categorías seleccionadas.','Exclude product categories'=>'Excluir categorías de producto','Show an "Exclude categories" picker so the coupon never applies to items in the selected categories.'=>'Muestra un selector "Excluir categorías" para que el cupón nunca se aplique a artículos de las categorías seleccionadas.','Assign to specific customers'=>'Asignar a clientes específicos','Show a searchable customer picker so you can assign the coupon to one or more registered users, or to any email address you type.'=>'Muestra un selector de clientes con búsqueda para asignar el cupón a uno o varios usuarios registrados o a cualquier dirección de correo que escribas.','Show a "Limit usage to X items" field that caps how many matching items the discount applies to per cart.'=>'Muestra un campo "Limitar uso a X artículos" que limita a cuántos artículos coincidentes se aplica el descuento por carrito.','Login Page'=>'Página de inicio de sesión','Modern login page'=>'Página de inicio de sesión moderna','Replace the default WordPress login page with a clean, modern design and AJAX-powered authentication'=>'Sustituye la página de inicio de sesión predeterminada de WordPress por un diseño moderno y limpio con autenticación basada en AJAX','Hide "Powered by WordPress" credit'=>'Ocultar crédito "Funciona con WordPress"','Remove the "Powered by WordPress" text below the login card'=>'Quitar el texto "Funciona con WordPress" debajo de la tarjeta de inicio de sesión','Force native login submission'=>'Forzar envío nativo de inicio de sesión','Recommended. Submits the login form to wp-login.php natively while keeping the modern design, so any 2FA, SSO, or custom authentication plugin (Wordfence Login Security, Two Factor, WP 2FA, miniOrange, Solid Security, Duo, Rublon, etc.) works as expected. Disable only if you rely on the AJAX login endpoint and are certain no authentication plugin alters the login flow.'=>'Recomendado. Envía el formulario de inicio de sesión a wp-login.php de forma nativa manteniendo el diseño moderno, para que cualquier plugin de 2FA, SSO o autenticación personalizada (Wordfence Login Security, Two Factor, WP 2FA, miniOrange, Solid Security, Duo, Rublon, etc.) funcione como se espera. Desactívalo solo si dependes del endpoint AJAX de inicio de sesión y estás seguro de que ningún plugin de autenticación altera el flujo de inicio de sesión.','Login page heading'=>'Encabezado de la página de acceso','The line above the login card. Password reset and registration screens always show their own wording instead, so the heading never contradicts the form underneath it.'=>'La línea sobre la tarjeta de acceso. Las pantallas de restablecimiento de contraseña y de registro muestran siempre su propio texto, para que el encabezado nunca contradiga al formulario que hay debajo.','Default ("Welcome back")'=>'Por defecto («Bienvenido de nuevo»)','Site name'=>'Nombre del sitio','Custom text'=>'Texto personalizado','login page headingHidden'=>'Oculto','Custom heading text'=>'Texto de encabezado personalizado','Used when the heading above is set to Custom text. Up to 100 characters.'=>'Se usa cuando el encabezado de arriba está configurado como Texto personalizado. Hasta 100 caracteres.','Admin notices'=>'Avisos de administración','Hide third-party admin notices'=>'Ocultar avisos de administración de terceros','Suppress admin notices from other plugins and themes. BrikPanel\'s own notices always remain visible. Turn this off to restore the default WordPress behaviour.'=>'Suprime los avisos de administración de otros plugins y temas. Los avisos propios de BrikPanel siempre permanecen visibles. Desactívalo para restaurar el comportamiento predeterminado de WordPress.','Also hide error notices'=>'Ocultar también los avisos de error','By default red error notices stay on screen, since they usually mean something is broken. Enable this to tuck them into the notifications bell too. Only applies while "Hide third-party admin notices" is on.'=>'Por defecto, los avisos de error en rojo permanecen en pantalla, ya que normalmente significan que algo está roto. Activa esto para guardarlos también en la campana de notificaciones. Solo se aplica mientras "Ocultar avisos de administración de terceros" está activado.','Hide WooCommerce ads'=>'Ocultar anuncios de WooCommerce','Hide the ads WooCommerce.com shows in your admin: promo cards such as the one above the Orders list, the sale badge on the Extensions menu and extension suggestions. Turn this off to show them again.'=>'Oculta los anuncios que WooCommerce.com muestra en tu administración: tarjetas promocionales como la que aparece sobre la lista de Pedidos, la insignia de oferta del menú Extensiones y las sugerencias de extensiones. Desactívalo para volver a mostrarlos.','Real-time alerts when a new paid order arrives while you have the WordPress admin open.'=>'Alertas en tiempo real cuando llega un nuevo pedido pagado mientras tienes la administración de WordPress abierta.','Show new order popup'=>'Mostrar popup de nuevo pedido','Display a slide-in card in the corner of the admin whenever a new paid order arrives.'=>'Muestra una tarjeta deslizante en la esquina de la administración cada vez que llega un nuevo pedido pagado.','Play notification sound'=>'Reproducir sonido de notificación','Play a short chime to alert you of new paid orders. Some browsers require an interaction with the page before audio can play automatically.'=>'Reproduce un breve tono para alertarte de nuevos pedidos pagados. Algunos navegadores requieren una interacción con la página antes de que el audio pueda reproducirse automáticamente.','Confetti celebration'=>'Celebración con confeti','Briefly burst confetti across the screen to celebrate each new order.'=>'Lanza brevemente confeti por la pantalla para celebrar cada nuevo pedido.','Sound volume'=>'Volumen del sonido','Volume of the new-order chime, from 0 (silent) to 100 (loud).'=>'Volumen del tono de nuevo pedido, de 0 (silencioso) a 100 (alto).','Polling interval (seconds)'=>'Intervalo de sondeo (segundos)','How often the admin checks for new orders. Lower values feel more instant; higher values reduce server load. Min 10, max 300.'=>'Con qué frecuencia la administración comprueba nuevos pedidos. Valores más bajos parecen más instantáneos; valores más altos reducen la carga del servidor. Mín 10, máx 300.','Developers'=>'Desarrolladores','Build on top of BrikPanel with public hooks and filters. The docs below are generated from the plugin source.'=>'Crea sobre BrikPanel con hooks y filtros públicos. La documentación a continuación se genera a partir del código fuente del plugin.','Login page'=>'Página de inicio de sesión','Notifications'=>'Notificaciones','Import / Export'=>'Importar / Exportar','Interface'=>'Interfaz','Store'=>'Tienda','System'=>'Sistema','Choose…'=>'Elegir…','BrikPanel settings sections'=>'Secciones de ajustes de BrikPanel','Search settings'=>'Buscar ajustes','No settings found.'=>'No se han encontrado ajustes.','BrikPanel settings saved.'=>'Ajustes de BrikPanel guardados.','All shipping methods'=>'Todos los métodos de envío','Order not found.'=>'Pedido no encontrado.','Invalid status.'=>'Estado no válido.','product attributes table columnName'=>'Nombre','product attributes table columnSlug'=>'Slug','product attributes table columnType'=>'Tipo','product attributes table columnOrder by'=>'Ordenar por','product attributes table columnTerms'=>'Términos','Add subcategory'=>'Añadir subcategoría','Add child'=>'Añadir hijo','Move to top level'=>'Mover al nivel superior','No image'=>'Sin imagen','Category not found.'=>'Categoría no encontrada.','A category cannot be its own parent.'=>'Una categoría no puede ser su propia categoría superior.','Parent category not found.'=>'Categoría padre no encontrada.','Cannot set a child category as parent.'=>'No se puede establecer una categoría hija como padre.','That category is already in this position.'=>'Esa categoría ya está en esta posición.','"%1$s" moved under "%2$s"'=>'"%1$s" movido bajo "%2$s"','"%s" moved to the top level'=>'«%s» movida al nivel superior','Product Code'=>'Código de producto','%d code'=>'%d código' . "\0" . '%d códigos','Invalid product.'=>'Producto no válido.','Product Editor'=>'Editor de productos','Product not found.'=>'Producto no encontrado.','Text style'=>'Estilo de texto','Paragraph'=>'Párrafo','Heading 1'=>'Encabezado 1','Heading 2'=>'Encabezado 2','Heading 3'=>'Encabezado 3','Heading 4'=>'Encabezado 4','Heading 5'=>'Encabezado 5','Quote'=>'Cita','Bold'=>'Negrita','Italic'=>'Cursiva','Bullet list'=>'Lista con viñetas','Numbered list'=>'Lista numerada','Align left'=>'Alinear a la izquierda','Align center'=>'Centrar','Align right'=>'Alinear a la derecha','Text color'=>'Color del texto','Insert link'=>'Insertar enlace','Remove link'=>'Eliminar enlace','Insert image'=>'Insertar imagen','Clear formatting'=>'Borrar formato','HTML source'=>'Código HTML','Standard'=>'Estándar','Same as parent'=>'Igual que el padre','No shipping c